struct ConnectionConfig {
    std::string id;
    std::string driver;      // "ab_eip", "modbus_tcp", "mqtt"
    std::string gateway;     // IP/host of PLC, ENxT, or Modbus TCP server
    std::string path;        // CIP path ("1,0") or Modbus unit/server ID
    std::string plc_type;    // "lgx", "mlgx", "plc5", "slc"
    std::string polling_mode = "standard"; // "standard" or "time_sliced"
    std::string polling_pacing = "balanced"; // "gentle", "balanced", "fast"
    int poll_batch_size = 0; // 0 = auto
    int poll_time_budget_ms = 0; // 0 = auto
    int poll_max_reads_per_sec = 0; // 0 = unlimited
    int poll_lanes = 1; // number of internal poll workers for this connection
    int slot = 0;
    int default_timeout_ms = 1000;
    int default_read_ms    = 1000;
    int default_write_ms   = 1000;
    int startup_handle_wait_ms = 0; // 0 = do not block startup waiting for async handles
    int debug              = 0;
    std::vector<std::string> mqtt_subscription_topics;
    std::vector<std::string> mqtt_publication_topics;
};

	struct TagConfig {
	    std::string logical_name;
	    std::string plc_tag_name;
	    std::string path; // optional per-tag CIP path override; defaults to connection path
	    std::string source_type = "plc"; // "plc", "memory", or empty/legacy
	    std::string initial_value;
	    std::string datatype;
        // Modbus 32-bit values are encoded as two 16-bit registers. Most devices use high-word then low-word,
        // but some swap word order. Supported values: "hi_lo" (default) or "lo_hi".
        std::string word_order = "hi_lo";
	    int elem_count = 1; // for Logix arrays: number of elements to read (default 1)
	    int scan_ms = 1000;
	    bool enabled = true; // legacy configs default to enabled
	    bool writable = false;
        bool invert = false; // bool only: publish logical NOT of the value

	    // Derived tags (optional)
	    // If source_tag is set, this tag is derived from another tag in the same connection.
	    // Currently supported: bit extraction from an integer source tag.
	    std::string source_tag; // logical name of the source tag
	    int bit = -1;           // bit index (0 = LSB)

    // Scaling (optional; default none)
    // Linear: map [raw_low..raw_high] -> [scaled_low..scaled_high]
    std::string scaling = "none"; // "none", "linear"
    double raw_low = 0.0;
    double raw_high = 1.0;
    double scaled_low = 0.0;
    double scaled_high = 1.0;
    bool clamp_low = false;
    bool clamp_high = false;
    std::string scaled_datatype = ""; // "", "float32", "float64", "int32", "uint32", "int16", "uint16"

    // Event logging
    bool log_event_on_change  = false;

    // Periodic logging options (all optional)
    bool log_periodic = false;                 // master enable
    std::string log_periodic_mode;             // "interval", "hourly", "daily"

    // interval mode
    int log_periodic_interval_sec = 0;         // e.g. 900 for 15 minutes

    // (future) hourly mode: log at HH:<minute> each hour
    int log_hourly_minute = 0;                 // 0–59

    // (future) daily mode: log at HH:MM once per day
    int log_daily_hour   = 0;                 // 0–23
    int log_daily_minute = 0;                 // 0–59
};

struct TagRuntime {
    TagConfig cfg;
    int32_t handle = PLCTAG_ERR_NOT_FOUND;
    bool handle_deferred = false;
    std::chrono::steady_clock::time_point next_poll;

    // Scaling runtime (precomputed)
    bool scaling_linear = false;
    bool scaling_valid = true;
    double scale_slope = 1.0;  // raw -> scaled
    double scale_offset = 0.0; // raw -> scaled
    double inv_slope = 1.0;    // scaled -> raw
    double inv_offset = 0.0;   // scaled -> raw
    std::string out_datatype;  // published datatype (scaled)

    // Periodic logging runtime state
    bool periodic_enabled = false;
    std::chrono::system_clock::time_point next_periodic_log;
};

