static int64_t system_wall_now_ms() {
    return std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()
    ).count();
}

static int64_t steady_elapsed_ms(std::chrono::steady_clock::time_point start) {
    return std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::steady_clock::now() - start
    ).count();
}

static int detect_physical_cpu_core_count(int logicalCount) {
    std::ifstream cpuinfo("/proc/cpuinfo");
    if (!cpuinfo) return logicalCount;

    auto trimLocal = [](std::string s) {
        const auto first = s.find_first_not_of(" \t\r\n");
        if (first == std::string::npos) return std::string{};
        const auto last = s.find_last_not_of(" \t\r\n");
        return s.substr(first, last - first + 1);
    };

    std::set<std::pair<int, int>> physicalCores;
    std::string line;
    int physicalId = -1;
    int coreId = -1;
    auto flush = [&]() {
        if (physicalId >= 0 && coreId >= 0) {
            physicalCores.insert({physicalId, coreId});
        }
        physicalId = -1;
        coreId = -1;
    };

    while (std::getline(cpuinfo, line)) {
        if (line.empty()) {
            flush();
            continue;
        }
        const auto pos = line.find(':');
        if (pos == std::string::npos) continue;
        const std::string key = trimLocal(line.substr(0, pos));
        const std::string value = trimLocal(line.substr(pos + 1));
        try {
            if (key == "physical id") {
                physicalId = std::stoi(value);
            } else if (key == "core id") {
                coreId = std::stoi(value);
            }
        } catch (...) {
            // Ignore malformed cpuinfo fields and fall back below.
        }
    }
    flush();

    if (!physicalCores.empty()) return static_cast<int>(physicalCores.size());
    return logicalCount;
}

static std::vector<SystemTagDef> collect_host_system_tags() {
    std::vector<SystemTagDef> rows;

    const int logicalCpuCount = static_cast<int>(std::max(1L, sysconf(_SC_NPROCESSORS_ONLN)));
    const int physicalCoreCount = std::max(1, detect_physical_cpu_core_count(logicalCpuCount));
    rows.push_back({"System/Host/CpuCount", "int32", logicalCpuCount});
    rows.push_back({"System/Host/LogicalCpuCount", "int32", logicalCpuCount});
    rows.push_back({"System/Host/PhysicalCoreCount", "int32", physicalCoreCount});

    double loads[3] = {0.0, 0.0, 0.0};
    if (getloadavg(loads, 3) == 3) {
        rows.push_back({"System/Host/LoadAverage1Min", "float64", loads[0]});
        rows.push_back({"System/Host/LoadAverage5Min", "float64", loads[1]});
        rows.push_back({"System/Host/LoadAverage15Min", "float64", loads[2]});
    } else {
        rows.push_back({"System/Host/LoadAverage1Min", "float64", 0.0});
        rows.push_back({"System/Host/LoadAverage5Min", "float64", 0.0});
        rows.push_back({"System/Host/LoadAverage15Min", "float64", 0.0});
    }

    {
        std::ifstream mem("/proc/meminfo");
        std::string key;
        uint64_t valueKb = 0;
        std::string unit;
        uint64_t totalKb = 0;
        uint64_t availKb = 0;
        while (mem >> key >> valueKb >> unit) {
            if (key == "MemTotal:") totalKb = valueKb;
            else if (key == "MemAvailable:") availKb = valueKb;
        }
        const uint64_t totalBytes = totalKb * 1024ULL;
        const uint64_t availBytes = availKb * 1024ULL;
        const double usedPct = totalBytes > 0
            ? 100.0 * static_cast<double>(totalBytes - availBytes) / static_cast<double>(totalBytes)
            : 0.0;
        rows.push_back({"System/Host/MemoryTotalBytes", "uint64", totalBytes});
        rows.push_back({"System/Host/MemoryAvailableBytes", "uint64", availBytes});
        rows.push_back({"System/Host/MemoryUsedPercent", "float64", usedPct});
    }

    {
        struct statvfs st {};
        double usedPct = 0.0;
        if (statvfs("/", &st) == 0 && st.f_blocks > 0) {
            const uint64_t total = static_cast<uint64_t>(st.f_blocks) * static_cast<uint64_t>(st.f_frsize);
            const uint64_t avail = static_cast<uint64_t>(st.f_bavail) * static_cast<uint64_t>(st.f_frsize);
            usedPct = total > 0
                ? 100.0 * static_cast<double>(total - avail) / static_cast<double>(total)
                : 0.0;
        }
        rows.push_back({"System/Host/DiskRootUsedPercent", "float64", usedPct});
    }

    {
        double uptime = 0.0;
        std::ifstream up("/proc/uptime");
        up >> uptime;
        rows.push_back({"System/Host/UptimeSeconds", "uint64", static_cast<uint64_t>(std::max(0.0, uptime))});
    }

    std::error_code ec;
    std::vector<std::string> interfaces;
    for (const auto &entry : fs::directory_iterator("/sys/class/net", ec)) {
        if (ec) break;
        const std::string iface = entry.path().filename().string();
        if (iface.empty() || iface == "lo") continue;
        interfaces.push_back(iface);
    }
    std::sort(interfaces.begin(), interfaces.end());
    for (const auto &iface : interfaces) {
        const fs::path stats = fs::path("/sys/class/net") / iface / "statistics";
        rows.push_back({"System/Host/Network/" + iface + "/RxBytes", "uint64", read_uint64_file(stats / "rx_bytes")});
        rows.push_back({"System/Host/Network/" + iface + "/TxBytes", "uint64", read_uint64_file(stats / "tx_bytes")});
    }

    return rows;
}

static std::vector<SystemTagDef> collect_clock_system_tags() {
    const int64_t nowMs = system_wall_now_ms();
    const int64_t nowSec = nowMs / 1000;
    std::time_t nowTime = static_cast<std::time_t>(nowSec);
    std::tm local {};
    localtime_r(&nowTime, &local);
    const int hour12 = ((local.tm_hour + 11) % 12) + 1;
    const bool isPm = local.tm_hour >= 12;
    const char *amPm = isPm ? "PM" : "AM";
    const double phase1s = static_cast<double>(nowMs % 1000) / 1000.0;
    const double phase2s = static_cast<double>(nowMs % 2000) / 2000.0;
    const double phase5s = static_cast<double>(nowMs % 5000) / 5000.0;

    return {
        {"System/Clock/UnixTimeMs", "int64", nowMs},
        {"System/Clock/UnixTimeSeconds", "int64", nowSec},
        {"System/Clock/Year", "int32", local.tm_year + 1900},
        {"System/Clock/Month", "int32", local.tm_mon + 1},
        {"System/Clock/Day", "int32", local.tm_mday},
        {"System/Clock/Hour", "int32", local.tm_hour},
        {"System/Clock/Hour12", "int32", hour12},
        {"System/Clock/IsPm", "bool", isPm},
        {"System/Clock/AmPm", "string", std::string(amPm)},
        {"System/Clock/Minute", "int32", local.tm_min},
        {"System/Clock/Second", "int32", local.tm_sec},
        {"System/Clock/DayOfWeek", "int32", local.tm_wday},
        {"System/Clock/DayOfYear", "int32", local.tm_yday + 1},
        {"System/Clock/FastBlink", "bool", ((nowMs / 500) % 2) == 0},
        {"System/Clock/SlowBlink", "bool", ((nowMs / 1000) % 2) == 0},
        {"System/Clock/OneSecondPulse", "bool", (nowMs % 1000) < 100},
        {"System/Clock/MinutePulse", "bool", (nowMs % 60000) < 1000},
        {"System/Clock/Phase1s", "double", phase1s},
        {"System/Clock/Phase2s", "double", phase2s},
        {"System/Clock/Phase5s", "double", phase5s}
    };
}

