// Config loading
// -----------------------------

static bool is_supported_datatype(const std::string &dt);
static bool is_modbus_driver_name(const std::string &driver);
static bool build_modbus_plc_tag_name(const json &jt, std::string &outName, std::string &outErr);
static std::string normalize_word_order(const std::string &raw);
static bool update_snapshot_from_plc_at_offset(TagSnapshot &snap,
                                               const ConnectionConfig &conn,
                                               const TagRuntime &tag,
                                               int byteOffset);

ConnectionConfig load_connection_config(const std::string &path) {
    json j = load_json_with_comments(path);

    ConnectionConfig c;
    c.id       = j.at("id").get<std::string>();
    c.driver   = j.value("driver", std::string("ab_eip"));
    c.gateway  = j.value("gateway", std::string{});
    std::string raw_path = j.value("path", std::string{});
    c.slot     = j.value("slot", 0);
    c.plc_type = j.value("plc_type", std::string("lgx"));
    c.polling_mode = to_lower_copy(trim_copy(json_get_string_loose(j, "polling_mode", "standard")));
    if (c.polling_mode != "time_sliced") c.polling_mode = "standard";
    c.polling_pacing = to_lower_copy(trim_copy(json_get_string_loose(j, "polling_pacing", "balanced")));
    if (c.polling_pacing != "gentle" && c.polling_pacing != "fast") c.polling_pacing = "balanced";
    c.poll_batch_size = std::max(0, json_get_int_loose(j, "poll_batch_size", 0));
    c.poll_time_budget_ms = std::max(0, json_get_int_loose(j, "poll_time_budget_ms", 0));
    c.poll_max_reads_per_sec = std::max(0, json_get_int_loose(j, "poll_max_reads_per_sec", 0));
    c.poll_lanes = std::max(1, std::min(8, json_get_int_loose(j, "poll_lanes", 1)));
    c.default_timeout_ms = j.value("default_timeout_ms", 1000);
    c.default_read_ms    = j.value("default_read_ms", 1000);
    c.default_write_ms   = j.value("default_write_ms", 1000);
    c.startup_handle_wait_ms = std::max(0, json_get_int_loose(j, "startup_handle_wait_ms", 0));
    c.debug              = j.value("debug", 0);

    if (c.driver == "ab_eip") {
        if (!raw_path.empty()) {
            c.path = raw_path;
        } else {
            // For ControlLogix/CompactLogix; MicroLogix ignores path
            c.path = "1," + std::to_string(c.slot);
        }
    } else if (is_modbus_driver_name(c.driver)) {
        c.driver = "modbus_tcp";
        c.path = trim_copy(raw_path.empty() ? json_get_string_loose(j, "unit_id", "1") : raw_path);
        if (c.path.empty()) c.path = "1";
        c.plc_type = "modbus_tcp";
    } else if (c.driver == "mqtt") {
        const json settings = (j.contains("settings") && j["settings"].is_object())
            ? j["settings"]
            : json::object();
        c.mqtt_subscription_topics.clear();
        c.mqtt_publication_topics.clear();
        if (settings.contains("messages") && settings["messages"].is_array()) {
            for (const auto &jm : settings["messages"]) {
                const std::string topic = trim_copy(jm.value("topic", std::string{}));
                if (!topic.empty()) c.mqtt_subscription_topics.push_back(topic);
            }
        }
        if (settings.contains("publications") && settings["publications"].is_array()) {
            for (const auto &jp : settings["publications"]) {
                const std::string topic = trim_copy(jp.value("topic", std::string{}));
                if (!topic.empty()) c.mqtt_publication_topics.push_back(topic);
            }
        }
        c.path.clear();
        c.plc_type = "mqtt";
        c.polling_mode = "standard";
        c.polling_pacing = "gentle";
        c.poll_batch_size = 0;
        c.poll_time_budget_ms = 0;
        c.poll_max_reads_per_sec = 0;
        c.poll_lanes = 1;
    } else {
        throw std::runtime_error("Unsupported driver: " + c.driver +
                                 " (expected 'ab_eip', 'modbus_tcp', or 'mqtt')");
    }

    return c;
}

static std::string normalize_modbus_register_prefix(const std::string &raw) {
    std::string s;
    for (unsigned char ch : trim_copy(raw)) {
        if (std::isalnum(ch)) s.push_back(static_cast<char>(std::tolower(ch)));
    }
    if (s == "co" || s == "coil" || s == "coils" || s == "discreteoutput" || s == "discreteoutputs") return "co";
    if (s == "di" || s == "discreteinput" || s == "discreteinputs" || s == "inputstatus") return "di";
    if (s == "hr" || s == "holdingregister" || s == "holdingregisters" || s == "register" || s == "registers") return "hr";
    if (s == "ir" || s == "inputregister" || s == "inputregisters") return "ir";
    return {};
}

static bool json_has_nonempty_value(const json &obj, const char *key) {
    if (!obj.is_object() || !obj.contains(key) || obj.at(key).is_null()) return false;
    if (obj.at(key).is_string()) return !trim_copy(obj.at(key).get<std::string>()).empty();
    return true;
}

static bool build_modbus_plc_tag_name(const json &jt, std::string &outName, std::string &outErr) {
    outName.clear();
    outErr.clear();

    std::string typeRaw = json_get_string_loose(jt, "register_type",
        json_get_string_loose(jt, "modbus_type",
        json_get_string_loose(jt, "register", std::string{})));
    std::string prefix = normalize_modbus_register_prefix(typeRaw);

    int offset = -1;
    if (json_has_nonempty_value(jt, "offset")) {
        offset = json_get_int_loose(jt, "offset", -1);
    } else if (json_has_nonempty_value(jt, "modbus_offset")) {
        offset = json_get_int_loose(jt, "modbus_offset", -1);
    }

    if (offset < 0) {
        const bool hasAddress = json_has_nonempty_value(jt, "address") || json_has_nonempty_value(jt, "modbus_address");
        if (!hasAddress) {
            outErr = "missing Modbus 'address' or 'offset'";
            return false;
        }

        const int address = json_has_nonempty_value(jt, "address")
            ? json_get_int_loose(jt, "address", -1)
            : json_get_int_loose(jt, "modbus_address", -1);
        if (address < 0) {
            outErr = "invalid Modbus address";
            return false;
        }

        if (prefix.empty()) {
            if (address >= 40001 && address <= 49999) {
                prefix = "hr";
                offset = address - 40001;
            } else if (address >= 30001 && address <= 39999) {
                prefix = "ir";
                offset = address - 30001;
            } else if (address >= 10001 && address <= 19999) {
                prefix = "di";
                offset = address - 10001;
            } else {
                outErr = "register_type is required when address is not in 10001/30001/40001 form";
                return false;
            }
        } else {
            const bool zeroBased = json_get_bool_loose(jt, "zero_based", false) ||
                                   json_get_bool_loose(jt, "zero_based_address", false);
            if (zeroBased) {
                offset = address;
            } else if (prefix == "hr" && address >= 40001) {
                offset = address - 40001;
            } else if (prefix == "ir" && address >= 30001) {
                offset = address - 30001;
            } else if (prefix == "di" && address >= 10001) {
                offset = address - 10001;
            } else {
                offset = address - 1;
            }
        }
    }

    if (prefix.empty()) {
        outErr = "missing or unsupported Modbus register_type";
        return false;
    }
    if (offset < 0) {
        outErr = "Modbus address resolved to a negative offset";
        return false;
    }

    outName = prefix + std::to_string(offset);
    return true;
}

static std::string normalize_word_order(const std::string &raw) {
    std::string s;
    for (unsigned char ch : trim_copy(raw)) {
        if (std::isalnum(ch)) s.push_back(static_cast<char>(std::tolower(ch)));
        else if (ch == '_' || ch == '-') s.push_back('_');
    }
    if (s == "lo_hi" || s == "low_hi" || s == "low_high" || s == "lowhigh" || s == "swapped" || s == "swap") {
        return "lo_hi";
    }
    if (s.empty() || s == "hi_lo" || s == "high_lo" || s == "high_low" || s == "highlow" || s == "normal") {
        return "hi_lo";
    }
    return {};
}

	TagFile load_tag_file(const std::string &path) {
	    json j = load_json_with_comments(path);

    TagFile tf;
    tf.connection_id = j.at("connection_id").get<std::string>();

		for (const auto &jt : j.at("tags")) {
	        try {
	            TagConfig t;
	            if (!jt.is_object()) continue;

	            if (!jt.contains("name")) continue;
	            t.logical_name = json_get_string_loose(jt, "name", std::string{});
	            if (t.logical_name.empty()) continue;

	            // Source forms:
	            // - PLC tag:       { name, plc_tag_name, datatype }
	            // - Memory tag:    { name, source: "memory", datatype, initial_value? }
	            // - Derived bit:   { name, source_tag, bit >= 0, datatype=bool }
	            // - Derived alias: { name, source_tag, datatype=(any supported), bit omitted or < 0 }
	            std::string sourceKind = to_lower_copy(trim_copy(json_get_string_loose(jt, "source_type", json_get_string_loose(jt, "source_kind", std::string{}))));
	            const std::string sourceCompat = json_get_string_loose(jt, "source", std::string{});
	            if (sourceKind.empty() && to_lower_copy(trim_copy(sourceCompat)) == "memory") {
	                sourceKind = "memory";
	            }
	            const bool isMemory = (sourceKind == "memory");
	            const std::string source_tag = json_get_string_loose(jt, "source_tag", isMemory ? std::string{} : sourceCompat);
	            const int bit = json_get_int_loose(jt, "bit", -1);
	            const bool hasSource = (!source_tag.empty());
	            const bool isDerivedBit = (hasSource && bit >= 0);
	            const bool isDerivedAlias = (hasSource && bit < 0);

	            if (isMemory) {
	                t.source_type = "memory";
	                t.initial_value = json_get_string_loose(jt, "initial_value", std::string{});
	                t.plc_tag_name.clear();
	                t.source_tag.clear();
	                t.bit = -1;
	                t.elem_count = 1;
	                t.scan_ms = 0;
	                t.datatype = json_get_string_loose(jt, "datatype", std::string{});
	                if (t.datatype.empty()) {
	                    std::cerr << "[load] Warning: skipping memory tag '" << t.logical_name
	                              << "' in " << path << " because datatype is missing.\n";
	                    continue;
	                }
	                if (!is_supported_datatype(t.datatype)) {
	                    std::cerr << "[load] Warning: skipping memory tag '" << t.logical_name
	                              << "' in " << path << " due to unsupported datatype '" << t.datatype << "'.\n";
	                    continue;
	                }
	            } else if (hasSource) {
	                t.source_type = "derived";
	                t.source_tag = source_tag;
	                t.bit = bit;
	                t.plc_tag_name.clear();

	                t.datatype = json_get_string_loose(jt, "datatype", std::string{});
	                if (t.datatype.empty()) {
	                    t.datatype = isDerivedBit ? std::string("bool") : std::string{};
	                }

	                if (isDerivedBit) {
	                    if (t.datatype.empty()) t.datatype = "bool";
	                    if (t.datatype != "bool") {
	                        std::cerr << "[load] Warning: skipping derived-bit tag '" << t.logical_name
	                                  << "' in " << path << " because datatype must be 'bool'.\n";
	                        continue;
	                    }
	                } else {
	                    if (t.datatype.empty()) {
	                        std::cerr << "[load] Warning: skipping derived-alias tag '" << t.logical_name
	                                  << "' in " << path << " because datatype is missing.\n";
	                        continue;
	                    }
	                    if (!is_supported_datatype(t.datatype)) {
	                        std::cerr << "[load] Warning: skipping derived-alias tag '" << t.logical_name
	                                  << "' in " << path << " due to unsupported datatype '" << t.datatype << "'.\n";
	                        continue;
	                    }
	                }
	            } else {
	                t.source_type = "plc";
	                if (!jt.contains("datatype")) continue;
	                t.plc_tag_name = json_get_string_loose(jt, "plc_tag_name", std::string{});
	                if (t.plc_tag_name.empty()) {
	                    std::string modbusName;
	                    std::string modbusErr;
	                    if (build_modbus_plc_tag_name(jt, modbusName, modbusErr)) {
	                        t.plc_tag_name = modbusName;
	                    } else if (json_has_nonempty_value(jt, "register_type") ||
	                               json_has_nonempty_value(jt, "modbus_type") ||
	                               json_has_nonempty_value(jt, "register") ||
	                               json_has_nonempty_value(jt, "address") ||
	                               json_has_nonempty_value(jt, "modbus_address") ||
	                               json_has_nonempty_value(jt, "offset") ||
	                               json_has_nonempty_value(jt, "modbus_offset")) {
	                        std::cerr << "[load] Warning: skipping Modbus tag '" << t.logical_name
	                                  << "' in " << path << ": " << modbusErr << ".\n";
	                        continue;
	                    }
	                }
	                t.path         = trim_copy(json_get_string_loose(jt, "path", std::string{}));
	                t.datatype     = json_get_string_loose(jt, "datatype", std::string{});
	                if (t.plc_tag_name.empty() || t.datatype.empty()) continue;
	                if (!is_supported_datatype(t.datatype)) {
	                    std::cerr << "[load] Warning: skipping tag '" << t.logical_name
	                              << "' in " << path << " due to unsupported datatype '" << t.datatype << "'.\n";
	                    continue;
	                }
	            }

	            t.scan_ms              = json_get_int_loose(jt, "scan_ms", 1000);
	            t.elem_count           = std::max(1, json_get_int_loose(jt, "elem_count", 1));
	            // Legacy tag JSON did not have "enabled"; default to true so old configs keep working.
	            t.enabled              = json_get_bool_loose(jt, "enabled", true);
	            t.writable             = json_get_bool_loose(jt, "writable", false);
                t.invert               = json_get_bool_loose(jt, "invert", false);
                {
                    const std::string rawWordOrder = json_get_string_loose(jt, "word_order",
                        json_get_string_loose(jt, "modbus_word_order", std::string{}));
                    const std::string norm = normalize_word_order(rawWordOrder);
                    if (!norm.empty()) t.word_order = norm;
                }
	            if (hasSource || isMemory) {
	                t.elem_count = 1;
	            }
	            if (isMemory) {
	                t.scan_ms = 0;
	            }
	            if (isDerivedAlias) {
	                // Derived-alias tags are currently read-only; strict writes are only supported for derived-bit tags.
	                t.writable = false;
	                t.bit = -1; // keep the stored config canonical for alias tags
	            }
	            if (t.invert && t.datatype != "bool") {
	                std::cerr << "[load] Warning: tag '" << t.logical_name
	                          << "' invert=true ignored because datatype is not bool.\n";
	                t.invert = false;
	            }

            // Scaling (optional)
            t.scaling         = json_get_string_loose(jt, "scaling", std::string("none"));
            t.raw_low         = json_get_double_loose(jt, "raw_low", t.raw_low);
            t.raw_high        = json_get_double_loose(jt, "raw_high", t.raw_high);
            t.scaled_low      = json_get_double_loose(jt, "scaled_low", t.scaled_low);
            t.scaled_high     = json_get_double_loose(jt, "scaled_high", t.scaled_high);
            t.clamp_low       = json_get_bool_loose(jt, "clamp_low", false);
            t.clamp_high      = json_get_bool_loose(jt, "clamp_high", false);
            t.scaled_datatype = json_get_string_loose(jt, "scaled_datatype", std::string{});
            if (isMemory) {
                t.scaling = "none";
                t.scaled_datatype.clear();
            }

            t.log_event_on_change  = json_get_bool_loose(jt, "log_event_on_change", false);

            // Periodic logging config (all optional)
            t.log_periodic      = json_get_bool_loose(jt, "log_periodic", false);
            t.log_periodic_mode = json_get_string_loose(jt, "log_periodic_mode", std::string{});

            // Accept either "log_periodic_interval_sec" or legacy "log_periodic_interval"
            int interval1 = json_get_int_loose(jt, "log_periodic_interval_sec", 0);
            int interval2 = json_get_int_loose(jt, "log_periodic_interval", 0);
            t.log_periodic_interval_sec = (interval1 > 0) ? interval1 : interval2;

            t.log_hourly_minute = json_get_int_loose(jt, "log_hourly_minute", 0);
            t.log_daily_hour    = json_get_int_loose(jt, "log_daily_hour", 0);
            t.log_daily_minute  = json_get_int_loose(jt, "log_daily_minute", 0);

	            tf.tags.push_back(t);
	        } catch (const std::exception &ex) {
	            std::cerr << "[load] Warning: skipping malformed tag in " << path << ": " << ex.what() << "\n";
	        }
		}
    
    return tf;
}

// -----------------------------
// Libplctag helpers
// -----------------------------

size_t datatype_size_bytes(const std::string &dt) {
    if (dt == "bool")                       return 1;
    if (dt == "int16" || dt == "uint16")   return 2;
    if (dt == "int32" || dt == "uint32")   return 4;
    if (dt == "float32")                   return 4;
    if (dt == "float64")                   return 8;
    if (dt == "string")                    return 88;
    throw std::runtime_error("Unsupported datatype: " + dt);
}

static bool is_supported_datatype(const std::string &dt) {
    return (
        dt == "bool" ||
        dt == "int16" || dt == "uint16" ||
        dt == "int32" || dt == "uint32" ||
        dt == "float32" ||
        dt == "float64" ||
        dt == "string"
    );
}

static bool is_memory_tag(const TagConfig &cfg) {
    return to_lower_copy(trim_copy(cfg.source_type)) == "memory";
}

static bool is_modbus_driver_name(const std::string &driver) {
    const std::string d = to_lower_copy(trim_copy(driver));
    return d == "modbus_tcp" || d == "modbus-tcp";
}

static bool is_modbus_connection(const ConnectionConfig &conn) {
    return is_modbus_driver_name(conn.driver);
}

static bool is_memory_connection_id(const std::string &connId) {
    return trim_copy(connId) == "_memory";
}

	static bool is_numeric_datatype(const std::string &dt) {
    return (
        dt == "int16" || dt == "uint16" ||
        dt == "int32" || dt == "uint32" ||
        dt == "float32" || dt == "float64"
    );
}

static std::string normalize_scaled_datatype(const std::string &dt) {
    if (dt.empty()) return "";
    if (dt == "int16" || dt == "uint16" || dt == "int32" || dt == "uint32" || dt == "float32" || dt == "float64") {
        return dt;
    }
    return "";
}

static bool tagvalue_to_double(const TagValue &v, double &out) {
    bool ok = true;
    std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, bool>) {
            ok = false;
        } else if constexpr (std::is_same_v<T, std::string>) {
            ok = false;
        } else {
            out = static_cast<double>(arg);
        }
    }, v);
    return ok;
}

static bool cast_double_to_tagvalue(double v, const std::string &dt, TagValue &out, std::string &outError) {
    outError.clear();

    if (dt == "float64") {
        out = static_cast<double>(v);
        return true;
    }
    if (dt == "float32") {
        out = static_cast<float>(v);
        return true;
    }

    if (dt == "int32") {
        if (v < static_cast<double>(std::numeric_limits<int32_t>::min()) ||
            v > static_cast<double>(std::numeric_limits<int32_t>::max())) {
            outError = "Scaled value out of range for int32";
            return false;
        }
        out = static_cast<int32_t>(std::llround(v));
        return true;
    }
    if (dt == "uint32") {
        if (v < 0.0 ||
            v > static_cast<double>(std::numeric_limits<uint32_t>::max())) {
            outError = "Scaled value out of range for uint32";
            return false;
        }
        out = static_cast<uint32_t>(std::llround(v));
        return true;
    }
    if (dt == "int16") {
        if (v < static_cast<double>(std::numeric_limits<int16_t>::min()) ||
            v > static_cast<double>(std::numeric_limits<int16_t>::max())) {
            outError = "Scaled value out of range for int16";
            return false;
        }
        out = static_cast<int16_t>(std::llround(v));
        return true;
    }
    if (dt == "uint16") {
        if (v < 0.0 ||
            v > static_cast<double>(std::numeric_limits<uint16_t>::max())) {
            outError = "Scaled value out of range for uint16";
            return false;
        }
        out = static_cast<uint16_t>(std::llround(v));
        return true;
    }

    outError = "Unsupported scaled datatype '" + dt + "'";
    return false;
}

static void init_tag_scaling(TagRuntime &rt, const std::string &sourcePathForLogs = "") {
    rt.scaling_linear = false;
    rt.scaling_valid = true;
    rt.scale_slope = 1.0;
    rt.scale_offset = 0.0;
    rt.inv_slope = 1.0;
    rt.inv_offset = 0.0;
    rt.out_datatype.clear();

    std::string mode = rt.cfg.scaling;
    for (char &c : mode) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    if (mode.empty() || mode == "none") {
        rt.out_datatype = rt.cfg.datatype;
        return;
    }

    if (mode != "linear") {
        std::cerr << "[scale] Warning: tag '" << rt.cfg.logical_name << "' has unsupported scaling='"
                  << rt.cfg.scaling << "'; treating as none."
                  << (sourcePathForLogs.empty() ? "" : (" (" + sourcePathForLogs + ")"))
                  << "\n";
        rt.cfg.scaling = "none";
        rt.out_datatype = rt.cfg.datatype;
        return;
    }

    if (!is_numeric_datatype(rt.cfg.datatype)) {
        std::cerr << "[scale] Warning: tag '" << rt.cfg.logical_name << "' datatype '"
                  << rt.cfg.datatype << "' cannot be scaled; treating scaling as none."
                  << (sourcePathForLogs.empty() ? "" : (" (" + sourcePathForLogs + ")"))
                  << "\n";
        rt.out_datatype = rt.cfg.datatype;
        return;
    }

    const double rawLow = rt.cfg.raw_low;
    const double rawHigh = rt.cfg.raw_high;
    const double scaledLow = rt.cfg.scaled_low;
    const double scaledHigh = rt.cfg.scaled_high;

    const double rawSpan = rawHigh - rawLow;
    const double scaledSpan = scaledHigh - scaledLow;
    if (rawSpan == 0.0 || scaledSpan == 0.0) {
        std::cerr << "[scale] Warning: tag '" << rt.cfg.logical_name
                  << "' has invalid scaling range; treating scaling as none."
                  << (sourcePathForLogs.empty() ? "" : (" (" + sourcePathForLogs + ")"))
                  << "\n";
        rt.out_datatype = rt.cfg.datatype;
        return;
    }

    rt.scaling_linear = true;
    rt.scale_slope = scaledSpan / rawSpan;
    rt.scale_offset = scaledLow - (rawLow * rt.scale_slope);

    rt.inv_slope = rawSpan / scaledSpan;
    rt.inv_offset = rawLow - (scaledLow * rt.inv_slope);

    std::string outDt = normalize_scaled_datatype(rt.cfg.scaled_datatype);
    rt.out_datatype = outDt.empty() ? std::string("float64") : outDt;
}

std::string build_base_conn_str(const ConnectionConfig &c, const std::string &pathOverride = std::string{}) {
    std::string s = is_modbus_connection(c) ? "protocol=modbus_tcp" : "protocol=ab_eip";
    s += "&gateway=" + c.gateway;
    const std::string effectivePath = trim_copy(pathOverride).empty() ? c.path : trim_copy(pathOverride);
    s += "&path=" + effectivePath;
    if (!is_modbus_connection(c)) {
        s += "&cpu=" + c.plc_type;
    }
    if (c.debug > 0) {
        s += "&debug=" + std::to_string(c.debug);
    }
    return s;
}

std::string build_tag_conn_str(const ConnectionConfig &c,
                               const TagConfig &t)
{
    std::string s = build_base_conn_str(c, t.path);
    s += "&name=" + t.plc_tag_name;
    const bool isModbus = is_modbus_connection(c);
    int elemCount = std::max(1, t.elem_count);
    if (isModbus) {
        // libplctag Modbus treats elements as 16-bit registers; for 32-bit values we must request 2 registers.
        if (t.datatype == "int32" || t.datatype == "uint32" || t.datatype == "float32") {
            elemCount = std::max(elemCount, 2);
        } else if (t.datatype == "float64") {
            elemCount = std::max(elemCount, 4);
        }
        // Do not set elem_size for Modbus: libplctag Modbus expects 16-bit registers and can return OOB
        // when elem_size is set to 4 for float32/int32.
    } else {
        if (t.datatype != "string") {
            s += "&elem_size=" + std::to_string(datatype_size_bytes(t.datatype));
        }
    }
    s += "&elem_count=" + std::to_string(elemCount);
    return s;
}

static bool wait_for_tag_ready(int32_t handle, int timeout_ms, std::string &outErr) {
    if (handle < 0) {
        outErr = std::string("plc_tag_create failed: ") + plc_tag_decode_error(handle);
        return false;
    }

    const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(std::max(0, timeout_ms));
    int32_t status = PLCTAG_STATUS_PENDING;
    while (true) {
        status = plc_tag_status(handle);
        if (status == PLCTAG_STATUS_OK) {
            outErr.clear();
            return true;
        }
        if (status != PLCTAG_STATUS_PENDING) {
            outErr = std::string("tag status: ") + plc_tag_decode_error(status);
            return false;
        }
        if (std::chrono::steady_clock::now() >= deadline) {
            outErr = std::string("tag status: timeout (") + plc_tag_decode_error(status) + ")";
            return false;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
}

static bool accept_startup_handle(int32_t handle,
                                  int wait_ms,
                                  bool &pending,
                                  std::string &outErr) {
    pending = false;
    outErr.clear();
    if (handle < 0) {
        outErr = std::string("plc_tag_create failed: ") + plc_tag_decode_error(handle);
        return false;
    }

    int32_t status = plc_tag_status(handle);
    if (status == PLCTAG_STATUS_OK) return true;
    if (status != PLCTAG_STATUS_PENDING) {
        pending = true;
        outErr = std::string("initial tag status: ") + plc_tag_decode_error(status);
        return true;
    }
    if (wait_ms <= 0) {
        pending = true;
        return true;
    }

    const auto deadline = std::chrono::steady_clock::now() + std::chrono::milliseconds(wait_ms);
    while (true) {
        if (std::chrono::steady_clock::now() >= deadline) {
            pending = true;
            return true;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        status = plc_tag_status(handle);
        if (status == PLCTAG_STATUS_OK) return true;
        if (status != PLCTAG_STATUS_PENDING) {
            pending = true;
            outErr = std::string("initial tag status: ") + plc_tag_decode_error(status);
            return true;
        }
    }
}

static void opcua_onWrite(UA_Server *server,
                          const UA_NodeId *sessionId,
                          void *sessionContext,
                          const UA_NodeId *nodeId,
                          void *nodeContext,
                          const UA_NumericRange *range,
                          const UA_DataValue *data) {
    (void)server;
    (void)sessionContext;
    (void)nodeId;
    (void)range;

    // Ignore writes coming from our own internal UA_Server_writeValue calls
    if (g_suppressOpcUaWriteCallback) {
        return;
    }

    // (Optional, keep this too if you added it)
    // Ignore server-internal writes (just in case)
    if (!sessionId || UA_NodeId_isNull(sessionId)) {
        return;
    }

    auto *binding = static_cast<UaTagBinding*>(nodeContext);
    if (!binding) {
        std::cerr << "OPC UA write: nodeContext is null, ignoring\n";
        return;
    }
    if (!binding->writable) {
        std::cerr << "OPC UA write: tag [" << binding->conn_id << "]."
                  << binding->logical_name << " is not writable, ignoring\n";
        return;
    }

    if (!g_mqttDrivers || !g_mqttTagTable || !g_mqttDriverMutex) {
        std::cerr << "OPC UA write: missing driver context.\n";
        return;
    }

    const UA_Variant &var = data->value;
    std::string valueStr;

    if (UA_Variant_hasScalarType(&var, &UA_TYPES[UA_TYPES_BOOLEAN])) {
        UA_Boolean v = *(UA_Boolean*)var.data;
        valueStr = v ? "1" : "0";
    } else if (UA_Variant_hasScalarType(&var, &UA_TYPES[UA_TYPES_INT16])) {
        UA_Int16 v = *(UA_Int16*)var.data;
        valueStr = std::to_string((int)v);
    } else if (UA_Variant_hasScalarType(&var, &UA_TYPES[UA_TYPES_UINT16])) {
        UA_UInt16 v = *(UA_UInt16*)var.data;
        valueStr = std::to_string((unsigned int)v);
    } else if (UA_Variant_hasScalarType(&var, &UA_TYPES[UA_TYPES_INT32])) {
        UA_Int32 v = *(UA_Int32*)var.data;
        valueStr = std::to_string((int32_t)v);
    } else if (UA_Variant_hasScalarType(&var, &UA_TYPES[UA_TYPES_UINT32])) {
        UA_UInt32 v = *(UA_UInt32*)var.data;
        valueStr = std::to_string((uint32_t)v);
    } else if (UA_Variant_hasScalarType(&var, &UA_TYPES[UA_TYPES_FLOAT])) {
        UA_Float v = *(UA_Float*)var.data;
        std::ostringstream oss;
        oss << std::setprecision(9) << (float)v;
        valueStr = oss.str();
    } else if (UA_Variant_hasScalarType(&var, &UA_TYPES[UA_TYPES_DOUBLE])) {
        UA_Double v = *(UA_Double*)var.data;
        std::ostringstream oss;
        oss << std::setprecision(17) << (double)v;
        valueStr = oss.str();
    } else {
        std::cerr << "OPC UA write: unsupported UA variant type for ["
                  << binding->conn_id << "]." << binding->logical_name << "\n";
        return;
    }

    const bool ok = write_tag_by_name(
        *g_mqttDrivers,
        binding->conn_id,
        binding->logical_name,
        valueStr,
        *g_mqttTagTable,
        *g_mqttDriverMutex
    );

    if (!ok) {
        std::cerr << "OPC UA write: write_tag_by_name failed for ["
                  << binding->conn_id << "]." << binding->logical_name << "\n";
        return;
    }
}

void update_snapshot_from_plc(TagSnapshot &snap,
                              const ConnectionConfig &conn,
                              const TagRuntime &tag)
{
    // Delegate to the offset-based reader so Modbus 32-bit word-order decoding and scaling apply consistently.
    (void)update_snapshot_from_plc_at_offset(snap, conn, tag, 0);
}

void print_snapshot(const TagSnapshot &snap) {
    std::cout << "[" << snap.connection_id << "] "
              << snap.logical_name << " = ";
    std::visit([](auto &&arg) { std::cout << arg; }, snap.value);
    std::cout << " (" << snap.datatype << ")\n";
}

std::string tag_value_to_string(const TagValue &v) {
    std::ostringstream oss;
    std::visit([&oss](auto &&arg) { oss << arg; }, v);
    return oss.str();
}

// -----------------------------
// Write helpers
// -----------------------------

bool parse_bool(const std::string &s, bool &out) {
    std::string v;
    v.reserve(s.size());
    for (char c : s) v.push_back(std::tolower(static_cast<unsigned char>(c)));

    if (v == "1" || v == "true" || v == "on" || v == "yes") {
        out = true; return true;
    }
    if (v == "0" || v == "false" || v == "off" || v == "no") {
        out = false; return true;
    }
    return false;
}

bool parse_string_to_tagvalue(const std::string &s,
                              const std::string &dt,
                              TagValue &out)
{
    try {
        if (dt == "bool") {
            bool b;
            if (!parse_bool(s, b)) {
                return false;
            }
            out = b;
            return true;
        } else if (dt == "int16") {
            int16_t v = static_cast<int16_t>(std::stoi(s));
            out = v;
            return true;
        } else if (dt == "uint16") {
            uint16_t v = static_cast<uint16_t>(std::stoul(s));
            out = v;
            return true;
        } else if (dt == "int32") {
            int32_t v = static_cast<int32_t>(std::stol(s));
            out = v;
            return true;
        } else if (dt == "uint32") {
            uint32_t v = static_cast<uint32_t>(std::stoul(s));
            out = v;
            return true;
        } else if (dt == "float32") {
            float v = std::stof(s);
            out = v;
            return true;
        } else if (dt == "float64") {
            double v = std::stod(s);
            out = v;
            return true;
        } else if (dt == "string") {
            out = s;
            return true;
        }
    } catch (...) {
        return false;
    }
    return false;
}

// Helper: convert TagValue -> string for logging
static std::string snapshot_value_to_string(const TagSnapshot &snap) {
    std::ostringstream oss;
    std::visit([&oss](auto &&arg) { oss << arg; }, snap.value);
    return oss.str();
}

static bool update_snapshot_from_plc_at_offset(TagSnapshot &snap,
                                               const ConnectionConfig &conn,
                                               const TagRuntime &tag,
                                               int byteOffset);

static bool extract_bit_from_snapshot(const TagSnapshot &src, int bit, bool &outBit) {
    if (bit < 0) return false;

    bool ok = false;
    uint64_t word = 0;
    std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, int16_t>) { ok = true; word = static_cast<uint16_t>(arg); }
        else if constexpr (std::is_same_v<T, uint16_t>) { ok = true; word = arg; }
        else if constexpr (std::is_same_v<T, int32_t>) { ok = true; word = static_cast<uint32_t>(arg); }
        else if constexpr (std::is_same_v<T, uint32_t>) { ok = true; word = arg; }
        else if constexpr (std::is_same_v<T, bool>) { ok = (bit == 0); word = arg ? 1u : 0u; }
        else { ok = false; }
    }, src.value);
    if (!ok) return false;

    if (bit >= 64) return false;
    outBit = ((word >> static_cast<uint64_t>(bit)) & 1ULL) != 0ULL;
    return true;
}

static bool update_snapshot_from_plc_at_offset(TagSnapshot &snap,
                                               const ConnectionConfig &conn,
                                               const TagRuntime &tag,
                                               int byteOffset);

static bool update_snapshot_from_plc_at_offset(TagSnapshot &snap,
                                               const ConnectionConfig &conn,
                                               const TagRuntime &tag,
                                               int byteOffset)
{
    snap.connection_id = conn.id;
    snap.logical_name  = tag.cfg.logical_name;
    snap.datatype      = tag.cfg.datatype;
    snap.timestamp     = std::chrono::system_clock::now();
    snap.quality       = 1;

    const std::string &dt = tag.cfg.datatype;
    const int32_t handle = tag.handle;

    TagValue raw{};
    if (dt == "float32") {
        if (is_modbus_connection(conn)) {
            // Modbus elements are 16-bit registers; float32 spans two registers.
            const uint16_t w0 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 0));
            const uint16_t w1 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 2));
            const bool swapWords = (tag.cfg.word_order == "lo_hi");
            const uint32_t hi = swapWords ? static_cast<uint32_t>(w1) : static_cast<uint32_t>(w0);
            const uint32_t lo = swapWords ? static_cast<uint32_t>(w0) : static_cast<uint32_t>(w1);
            const uint32_t bits = (hi << 16) | lo;
            float v = 0.0f;
            static_assert(sizeof(float) == sizeof(uint32_t), "float32 size mismatch");
            std::memcpy(&v, &bits, sizeof(v));
            raw = v;
        } else {
            float v = plc_tag_get_float32(handle, byteOffset);
            raw = v;
        }
    } else if (dt == "float64") {
        if (is_modbus_connection(conn)) {
            const uint16_t w0 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 0));
            const uint16_t w1 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 2));
            const uint16_t w2 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 4));
            const uint16_t w3 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 6));
            const bool swapWords = (tag.cfg.word_order == "lo_hi");
            const uint16_t a = swapWords ? w3 : w0;
            const uint16_t b = swapWords ? w2 : w1;
            const uint16_t c = swapWords ? w1 : w2;
            const uint16_t d = swapWords ? w0 : w3;
            const uint64_t bits = (static_cast<uint64_t>(a) << 48) |
                                  (static_cast<uint64_t>(b) << 32) |
                                  (static_cast<uint64_t>(c) << 16) |
                                   static_cast<uint64_t>(d);
            double v = 0.0;
            static_assert(sizeof(double) == sizeof(uint64_t), "float64 size mismatch");
            std::memcpy(&v, &bits, sizeof(v));
            raw = v;
        } else {
            double v = plc_tag_get_float64(handle, byteOffset);
            raw = v;
        }
    } else if (dt == "int32") {
        if (is_modbus_connection(conn)) {
            const uint16_t w0 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 0));
            const uint16_t w1 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 2));
            const bool swapWords = (tag.cfg.word_order == "lo_hi");
            const uint32_t hi = swapWords ? static_cast<uint32_t>(w1) : static_cast<uint32_t>(w0);
            const uint32_t lo = swapWords ? static_cast<uint32_t>(w0) : static_cast<uint32_t>(w1);
            const uint32_t u = (hi << 16) | lo;
            raw = static_cast<int32_t>(u);
        } else {
            int32_t v = plc_tag_get_int32(handle, byteOffset);
            raw = v;
        }
    } else if (dt == "uint32") {
        if (is_modbus_connection(conn)) {
            const uint16_t w0 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 0));
            const uint16_t w1 = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset + 2));
            const bool swapWords = (tag.cfg.word_order == "lo_hi");
            const uint32_t hi = swapWords ? static_cast<uint32_t>(w1) : static_cast<uint32_t>(w0);
            const uint32_t lo = swapWords ? static_cast<uint32_t>(w0) : static_cast<uint32_t>(w1);
            const uint32_t u = (hi << 16) | lo;
            raw = u;
        } else {
            uint32_t v = static_cast<uint32_t>(plc_tag_get_uint32(handle, byteOffset));
            raw = v;
        }
    } else if (dt == "int16") {
        int16_t v = plc_tag_get_int16(handle, byteOffset);
        raw = v;
    } else if (dt == "uint16") {
        uint16_t v = static_cast<uint16_t>(plc_tag_get_uint16(handle, byteOffset));
        raw = v;
    } else if (dt == "bool") {
        int8_t v = is_modbus_connection(conn)
            ? static_cast<int8_t>(plc_tag_get_bit(handle, byteOffset))
            : plc_tag_get_int8(handle, byteOffset);
        bool b = (v != 0);
        if (tag.cfg.invert) b = !b;
        raw = b;
    } else if (dt == "string") {
        int capacity = plc_tag_get_string_capacity(handle, byteOffset);
        if (capacity <= 0) capacity = 82;
        std::vector<char> buffer(static_cast<size_t>(capacity) + 1u, '\0');
        int status = plc_tag_get_string(handle, byteOffset, buffer.data(), static_cast<int>(buffer.size()));
        if (status != PLCTAG_STATUS_OK) {
            snap.quality = 0;
            snap.value = std::string{};
            return false;
        }
        raw = std::string(buffer.data());
    } else {
        snap.quality = 0;
        return false;
    }

    if (!tag.scaling_linear) {
        snap.value = raw;
        snap.datatype = tag.cfg.datatype;
        return true;
    }

    double rawNum = 0.0;
    if (!tagvalue_to_double(raw, rawNum)) {
        snap.value = raw;
        snap.datatype = tag.cfg.datatype;
        return true;
    }

    double scaled = rawNum * tag.scale_slope + tag.scale_offset;
    if (tag.cfg.clamp_low)  scaled = std::max(scaled, tag.cfg.scaled_low);
    if (tag.cfg.clamp_high) scaled = std::min(scaled, tag.cfg.scaled_high);

    TagValue out{};
    std::string castErr;
    if (!cast_double_to_tagvalue(scaled, tag.out_datatype.empty() ? std::string("float64") : tag.out_datatype, out, castErr)) {
        out = static_cast<double>(scaled);
        snap.datatype = "float64";
        snap.value = out;
        return true;
    }

    snap.value = out;
    snap.datatype = tag.out_datatype.empty() ? std::string("float64") : tag.out_datatype;
    return true;
}

// =========================
// WebSocket JSON notifiers
// =========================

void ws_notify_tag_update(const TagSnapshot &snap,
                          const TagConfig &cfg)
{
    if (!ws_is_enabled()) return;

	    json j;
	    j["type"]          = "tag_update";
	    j["connection_id"] = snap.connection_id;
	    j["name"]          = snap.logical_name;
	    j["key"]           = snap.connection_id + ":" + snap.logical_name;
	    j["datatype"]      = snap.datatype;
	    j["quality"]       = snap.quality;

    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        snap.timestamp.time_since_epoch()
    ).count();
	    j["timestamp_ms"] = ms;

	    std::visit([&j](auto &&arg) {
	        j["value"] = arg;
	    }, snap.value);

	    j["enabled"]               = cfg.enabled;
	    j["writable"]              = cfg.writable;
	    j["log_event_on_change"]   = cfg.log_event_on_change;
	    j["log_periodic_mode"]     = cfg.log_periodic_mode;
	    j["log_periodic_interval_sec"] = cfg.log_periodic_interval_sec;

    ws_send_json(j);
}

void ws_notify_system_tag_update(const SystemTagDef &def, int64_t timestamp_ms)
{
    if (!ws_is_enabled()) return;

    json j;
    j["type"] = "tag_update";
    j["connection_id"] = "_system";
    j["name"] = def.name;
    j["key"] = std::string("_system:") + def.name;
    j["datatype"] = def.datatype;
    j["quality"] = 1;
    j["timestamp_ms"] = timestamp_ms;
    j["value"] = def.value;
    j["enabled"] = true;
    j["writable"] = false;
    j["log_event_on_change"] = false;
    j["log_periodic_mode"] = false;
    j["log_periodic_interval_sec"] = 0;

    ws_send_json(j);
}

void ws_notify_alarm_event(const AlarmRuntime &alarm,
                           const TagSnapshot &snap,
                           const std::string &state)
{
    if (!ws_is_enabled()) return;

    const std::string displayName = alarm.cfg.name.empty() ? alarm.cfg.id : alarm.cfg.name;
    std::string message;
    if (state == "active") {
        message = alarm.cfg.message_on_active.empty() ? displayName : alarm.cfg.message_on_active;
    } else if (state == "cleared") {
        message = alarm.cfg.message_on_return;
    } else {
        message = displayName;
    }

    json j;
    j["type"]          = "alarm_event";
    j["alarm_id"]      = alarm.cfg.id;
    j["name"]          = displayName;
    j["connection_id"] = alarm.cfg.connection_id;
    j["tag_name"]      = alarm.cfg.tag_name;
    j["alarm_type"]    = alarm.cfg.type;
    j["enabled"]       = alarm.cfg.enabled;
    j["severity"]      = alarm.cfg.severity;
    j["active"]        = alarm.active;
    j["state"]         = state;   // "active", "cleared", "change"
    j["message"]       = message.empty() ? nullptr : json(message);

    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        snap.timestamp.time_since_epoch()
    ).count();
    j["timestamp_ms"] = ms;

    std::visit([&j](auto &&arg) {
        j["value"] = arg;
    }, snap.value);

    if (alarm.cfg.type == "high" || alarm.cfg.type == "low") {
        j["threshold"]  = alarm.cfg.threshold;
        j["hysteresis"] = alarm.cfg.hysteresis;
    }
    if (alarm.cfg.type == "equals" || alarm.cfg.type == "not_equals" || alarm.cfg.type == "contains" || alarm.cfg.type == "not_contains") {
        j["equals_value"] = alarm.cfg.equals_value;
        j["tolerance"] = alarm.cfg.equals_tolerance;
    }

    ws_send_json(j);
}

void ws_notify_event_log_row(const TagSnapshot *prevSnap,
                             const TagSnapshot &snap)
{
    if (!ws_is_enabled()) return;

    json j;
    j["type"]          = "event_log";
    j["connection_id"] = snap.connection_id;
    j["tag_name"]      = snap.logical_name;

    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        snap.timestamp.time_since_epoch()
    ).count();
    j["timestamp_ms"] = ms;

    // new side
    j["new_quality"] = snap.quality;
    std::visit([&j](auto &&arg) {
        j["new_value"] = arg;
    }, snap.value);

    // old side
    if (prevSnap) {
        j["old_quality"] = prevSnap->quality;
        std::visit([&j](auto &&arg) {
            j["old_value"] = arg;
        }, prevSnap->value);
    } else {
        j["old_quality"] = nullptr;
        j["old_value"]   = nullptr;
    }

    ws_send_json(j);
}

static bool plc_set_value_from_string(const std::string &datatype,
                                      int32_t handle,
                                      const std::string &value_str,
                                      TagValue &outValue,
                                      std::string &outError,
                                      bool bitAccess = false,
                                      const std::string &word_order = std::string("hi_lo"))
{
    try {
        int status = PLCTAG_STATUS_OK;

        if (datatype == "float32") {
            float v = std::stof(value_str);
            outValue = v;
            if (bitAccess) {
                uint32_t bits = 0;
                static_assert(sizeof(float) == sizeof(uint32_t), "float32 size mismatch");
                std::memcpy(&bits, &v, sizeof(bits));
                const uint16_t hi = static_cast<uint16_t>((bits >> 16) & 0xFFFFu);
                const uint16_t lo = static_cast<uint16_t>(bits & 0xFFFFu);
                const bool swapWords = (word_order == "lo_hi");
                const uint16_t w0 = swapWords ? lo : hi;
                const uint16_t w1 = swapWords ? hi : lo;
                status = plc_tag_set_uint16(handle, 0, w0);
                if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
            } else {
                status = plc_tag_set_float32(handle, 0, v);
            }
        } else if (datatype == "float64") {
            double v = std::stod(value_str);
            status = plc_tag_set_float64(handle, 0, v);
            outValue = v;
        } else if (datatype == "int32") {
            int32_t v = static_cast<int32_t>(std::stol(value_str));
            outValue = v;
            if (bitAccess) {
                const uint32_t bits = static_cast<uint32_t>(v);
                const uint16_t hi = static_cast<uint16_t>((bits >> 16) & 0xFFFFu);
                const uint16_t lo = static_cast<uint16_t>(bits & 0xFFFFu);
                const bool swapWords = (word_order == "lo_hi");
                const uint16_t w0 = swapWords ? lo : hi;
                const uint16_t w1 = swapWords ? hi : lo;
                status = plc_tag_set_uint16(handle, 0, w0);
                if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
            } else {
                status = plc_tag_set_int32(handle, 0, v);
            }
        } else if (datatype == "uint32") {
            uint32_t v = static_cast<uint32_t>(std::stoul(value_str));
            outValue = v;
            if (bitAccess) {
                const uint16_t hi = static_cast<uint16_t>((v >> 16) & 0xFFFFu);
                const uint16_t lo = static_cast<uint16_t>(v & 0xFFFFu);
                const bool swapWords = (word_order == "lo_hi");
                const uint16_t w0 = swapWords ? lo : hi;
                const uint16_t w1 = swapWords ? hi : lo;
                status = plc_tag_set_uint16(handle, 0, w0);
                if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
            } else {
                status = plc_tag_set_uint32(handle, 0, v);
            }
        } else if (datatype == "int16") {
            int16_t v = static_cast<int16_t>(std::stoi(value_str));
            status = plc_tag_set_int16(handle, 0, v);
            outValue = v;
        } else if (datatype == "uint16") {
            uint16_t v = static_cast<uint16_t>(std::stoul(value_str));
            status = plc_tag_set_uint16(handle, 0, v);
            outValue = v;
        } else if (datatype == "bool") {
            bool bv;
            if (!parse_bool(value_str, bv)) {
                outError = "Cannot parse value as bool";
                return false;
            }
            if (bitAccess) {
                status = plc_tag_set_bit(handle, 0, bv ? 1 : 0);
            } else {
                int8_t raw = bv ? 1 : 0;
                status = plc_tag_set_int8(handle, 0, raw);
            }
            outValue = bv;
        } else if (datatype == "string") {
            status = plc_tag_set_string(handle, 0, value_str.c_str());
            outValue = value_str;
        } else {
            outError = "Unsupported datatype '" + datatype + "'";
            return false;
        }

        if (status != PLCTAG_STATUS_OK) {
            outError = plc_tag_decode_error(status);
            return false;
        }

        return true;
    } catch (const std::exception &ex) {
        outError = std::string("Error parsing value: ") + ex.what();
        return false;
    }
}

static bool plc_tag_set_from_tagvalue(const std::string &datatype,
                                      int32_t handle,
                                      const TagValue &v,
                                      std::string &outError,
                                      bool bitAccess = false,
                                      const std::string &word_order = std::string("hi_lo"))
{
    outError.clear();
    int status = PLCTAG_STATUS_OK;

    if (datatype == "float32") {
        const float *pv = std::get_if<float>(&v);
        if (!pv) { outError = "Type mismatch: expected float32"; return false; }
        if (bitAccess) {
            uint32_t bits = 0;
            static_assert(sizeof(float) == sizeof(uint32_t), "float32 size mismatch");
            std::memcpy(&bits, pv, sizeof(bits));
            const uint16_t hi = static_cast<uint16_t>((bits >> 16) & 0xFFFFu);
            const uint16_t lo = static_cast<uint16_t>(bits & 0xFFFFu);
            const bool swapWords = (word_order == "lo_hi");
            const uint16_t w0 = swapWords ? lo : hi;
            const uint16_t w1 = swapWords ? hi : lo;
            status = plc_tag_set_uint16(handle, 0, w0);
            if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
        } else {
            status = plc_tag_set_float32(handle, 0, *pv);
        }
    } else if (datatype == "float64") {
        const double *pv = std::get_if<double>(&v);
        if (!pv) { outError = "Type mismatch: expected float64"; return false; }
        status = plc_tag_set_float64(handle, 0, *pv);
    } else if (datatype == "int32") {
        const int32_t *pv = std::get_if<int32_t>(&v);
        if (!pv) { outError = "Type mismatch: expected int32"; return false; }
        if (bitAccess) {
            const uint32_t bits = static_cast<uint32_t>(*pv);
            const uint16_t hi = static_cast<uint16_t>((bits >> 16) & 0xFFFFu);
            const uint16_t lo = static_cast<uint16_t>(bits & 0xFFFFu);
            const bool swapWords = (word_order == "lo_hi");
            const uint16_t w0 = swapWords ? lo : hi;
            const uint16_t w1 = swapWords ? hi : lo;
            status = plc_tag_set_uint16(handle, 0, w0);
            if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
        } else {
            status = plc_tag_set_int32(handle, 0, *pv);
        }
    } else if (datatype == "uint32") {
        const uint32_t *pv = std::get_if<uint32_t>(&v);
        if (!pv) { outError = "Type mismatch: expected uint32"; return false; }
        if (bitAccess) {
            const uint16_t hi = static_cast<uint16_t>((*pv >> 16) & 0xFFFFu);
            const uint16_t lo = static_cast<uint16_t>(*pv & 0xFFFFu);
            const bool swapWords = (word_order == "lo_hi");
            const uint16_t w0 = swapWords ? lo : hi;
            const uint16_t w1 = swapWords ? hi : lo;
            status = plc_tag_set_uint16(handle, 0, w0);
            if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
        } else {
            status = plc_tag_set_uint32(handle, 0, *pv);
        }
    } else if (datatype == "int16") {
        const int16_t *pv = std::get_if<int16_t>(&v);
        if (!pv) { outError = "Type mismatch: expected int16"; return false; }
        status = plc_tag_set_int16(handle, 0, *pv);
    } else if (datatype == "uint16") {
        const uint16_t *pv = std::get_if<uint16_t>(&v);
        if (!pv) { outError = "Type mismatch: expected uint16"; return false; }
        status = plc_tag_set_uint16(handle, 0, *pv);
    } else if (datatype == "bool") {
        const bool *pv = std::get_if<bool>(&v);
        if (!pv) { outError = "Type mismatch: expected bool"; return false; }
        if (bitAccess) {
            status = plc_tag_set_bit(handle, 0, *pv ? 1 : 0);
        } else {
            int8_t raw = (*pv) ? 1 : 0;
            status = plc_tag_set_int8(handle, 0, raw);
        }
    } else if (datatype == "string") {
        const std::string *pv = std::get_if<std::string>(&v);
        if (!pv) { outError = "Type mismatch: expected string"; return false; }
        status = plc_tag_set_string(handle, 0, pv->c_str());
    } else {
        outError = "Unsupported datatype '" + datatype + "'";
        return false;
    }

    if (status != PLCTAG_STATUS_OK) {
        outError = plc_tag_decode_error(status);
        return false;
    }
    return true;
}

static bool plc_tag_get_word_u64(const std::string &datatype,
                                 int32_t handle,
                                 uint64_t &outWord,
                                 int &outBits,
                                 std::string &outError,
                                 bool isModbus = false,
                                 const std::string &word_order = std::string("hi_lo"))
{
    outWord = 0;
    outBits = 0;
    outError.clear();

    if (datatype == "int16") {
        int16_t v = plc_tag_get_int16(handle, 0);
        outWord = static_cast<uint16_t>(v);
        outBits = 16;
        return true;
    }
    if (datatype == "uint16") {
        uint16_t v = static_cast<uint16_t>(plc_tag_get_uint16(handle, 0));
        outWord = v;
        outBits = 16;
        return true;
    }
    if (datatype == "int32") {
        if (isModbus) {
            const uint16_t w0 = static_cast<uint16_t>(plc_tag_get_uint16(handle, 0));
            const uint16_t w1 = static_cast<uint16_t>(plc_tag_get_uint16(handle, 2));
            const bool swapWords = (word_order == "lo_hi");
            const uint32_t hi = swapWords ? static_cast<uint32_t>(w1) : static_cast<uint32_t>(w0);
            const uint32_t lo = swapWords ? static_cast<uint32_t>(w0) : static_cast<uint32_t>(w1);
            outWord = (hi << 16) | lo;
        } else {
            int32_t v = plc_tag_get_int32(handle, 0);
            outWord = static_cast<uint32_t>(v);
        }
        outBits = 32;
        return true;
    }
    if (datatype == "uint32") {
        if (isModbus) {
            const uint16_t w0 = static_cast<uint16_t>(plc_tag_get_uint16(handle, 0));
            const uint16_t w1 = static_cast<uint16_t>(plc_tag_get_uint16(handle, 2));
            const bool swapWords = (word_order == "lo_hi");
            const uint32_t hi = swapWords ? static_cast<uint32_t>(w1) : static_cast<uint32_t>(w0);
            const uint32_t lo = swapWords ? static_cast<uint32_t>(w0) : static_cast<uint32_t>(w1);
            outWord = (hi << 16) | lo;
        } else {
            uint32_t v = static_cast<uint32_t>(plc_tag_get_uint32(handle, 0));
            outWord = v;
        }
        outBits = 32;
        return true;
    }

    outError = "Unsupported source datatype for derived-bit write: '" + datatype + "'";
    return false;
}

static bool plc_tag_set_word_u64(const std::string &datatype,
                                 int32_t handle,
                                 uint64_t word,
                                 std::string &outError,
                                 bool isModbus = false,
                                 const std::string &word_order = std::string("hi_lo"))
{
    outError.clear();
    int status = PLCTAG_STATUS_OK;

    if (datatype == "int16") {
        status = plc_tag_set_int16(handle, 0, static_cast<int16_t>(static_cast<uint16_t>(word)));
    } else if (datatype == "uint16") {
        status = plc_tag_set_uint16(handle, 0, static_cast<uint16_t>(word));
    } else if (datatype == "int32") {
        const uint32_t u = static_cast<uint32_t>(word);
        if (isModbus) {
            const uint16_t hi = static_cast<uint16_t>((u >> 16) & 0xFFFFu);
            const uint16_t lo = static_cast<uint16_t>(u & 0xFFFFu);
            const bool swapWords = (word_order == "lo_hi");
            const uint16_t w0 = swapWords ? lo : hi;
            const uint16_t w1 = swapWords ? hi : lo;
            status = plc_tag_set_uint16(handle, 0, w0);
            if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
        } else {
            status = plc_tag_set_int32(handle, 0, static_cast<int32_t>(u));
        }
    } else if (datatype == "uint32") {
        const uint32_t u = static_cast<uint32_t>(word);
        if (isModbus) {
            const uint16_t hi = static_cast<uint16_t>((u >> 16) & 0xFFFFu);
            const uint16_t lo = static_cast<uint16_t>(u & 0xFFFFu);
            const bool swapWords = (word_order == "lo_hi");
            const uint16_t w0 = swapWords ? lo : hi;
            const uint16_t w1 = swapWords ? hi : lo;
            status = plc_tag_set_uint16(handle, 0, w0);
            if (status == PLCTAG_STATUS_OK) status = plc_tag_set_uint16(handle, 2, w1);
        } else {
            status = plc_tag_set_uint32(handle, 0, u);
        }
    } else {
        outError = "Unsupported source datatype for derived-bit write: '" + datatype + "'";
        return false;
    }

    if (status != PLCTAG_STATUS_OK) {
        outError = plc_tag_decode_error(status);
        return false;
    }
    return true;
}

bool write_tag_by_name(std::vector<DriverContext> &drivers,
                       const std::string &conn_id,
                       const std::string &logical_name,
                       const std::string &value_str,
                       TagTable &table,
                       std::mutex &driverMutex)
{
    ConnectionConfig conn;
    TagConfig cfg;
    int32_t handle = PLCTAG_ERR_NOT_FOUND;
    bool scaling_linear = false;
    double inv_slope = 1.0;
    double inv_offset = 0.0;
    std::string out_datatype;
    TagSnapshot prevSnap;
    bool hadPrev = false;
    bool found = false;
    bool connectionFound = false;

    const std::string key = make_tag_key(conn_id, logical_name);

    {
        std::lock_guard<std::mutex> lock(driverMutex);

        for (auto &driver : drivers) {
            if (driver.conn.id != conn_id) continue;
            connectionFound = true;
            conn = driver.conn;
            for (auto &t : driver.tags) {
                if (t.cfg.logical_name == logical_name) {
                    cfg = t.cfg;
                    handle = t.handle;
                    scaling_linear = t.scaling_linear;
                    inv_slope = t.inv_slope;
                    inv_offset = t.inv_offset;
                    out_datatype = t.out_datatype;
                    found = true;
                    break;
                }
            }
            break;
        }

        if (found) {
            auto itPrev = table.find(key);
            if (itPrev != table.end()) {
                prevSnap = itPrev->second;
                hadPrev = true;
            }
        }
    }

    if (!found) {
        auto pubIt = g_mqttPublicationTopicsByConn.find(conn_id);
        if (pubIt != g_mqttPublicationTopicsByConn.end() &&
            mqtt_name_matches_any_topic_scope(logical_name, pubIt->second)) {
            TagSnapshot snap;
            snap.connection_id = conn_id;
            snap.logical_name = logical_name;
            snap.datatype = "string";
            snap.timestamp = std::chrono::system_clock::now();
            snap.quality = 1;
            snap.value = value_str;

            {
                std::lock_guard<std::mutex> lock(driverMutex);
                table[key] = snap;
            }
            mqtt_publish_topic_value(conn_id, logical_name, value_str);
            std::cout << "Write OK (mqtt-publication): [" << conn_id << "] "
                      << logical_name << " := " << value_str << "\n";
            return true;
        }
        if (g_mqttKnownConnectionIds.count(conn_id) > 0 &&
            !mqtt_is_subscription_tag_name(logical_name)) {
            TagSnapshot snap;
            snap.connection_id = conn_id;
            snap.logical_name = logical_name;
            snap.datatype = "string";
            snap.timestamp = std::chrono::system_clock::now();
            snap.quality = 1;
            snap.value = value_str;

            {
                std::lock_guard<std::mutex> lock(driverMutex);
                table[key] = snap;
            }
            mqtt_publish_topic_value(conn_id, logical_name, value_str);
            std::cout << "Write OK (mqtt-dynamic-any-publication): [" << conn_id << "] "
                      << logical_name << " := " << value_str << "\n";
            return true;
        }
        if (mqtt_connection_known_from_inputs(conn_id) &&
            !mqtt_is_subscription_tag_name(logical_name)) {
            TagSnapshot snap;
            snap.connection_id = conn_id;
            snap.logical_name = logical_name;
            snap.datatype = "string";
            snap.timestamp = std::chrono::system_clock::now();
            snap.quality = 1;
            snap.value = value_str;

            {
                std::lock_guard<std::mutex> lock(driverMutex);
                table[key] = snap;
            }
            mqtt_publish_topic_value(conn_id, logical_name, value_str);
            std::cout << "Write OK (mqtt-dynamic-input-known): [" << conn_id << "] "
                      << logical_name << " := " << value_str << "\n";
            return true;
        }
        if (connectionFound && to_lower_copy(trim_copy(conn.driver)) == "mqtt" &&
            mqtt_name_matches_any_topic_scope(logical_name, conn.mqtt_publication_topics)) {
            TagSnapshot snap;
            snap.connection_id = conn.id;
            snap.logical_name = logical_name;
            snap.datatype = "string";
            snap.timestamp = std::chrono::system_clock::now();
            snap.quality = 1;
            snap.value = value_str;

            {
                std::lock_guard<std::mutex> lock(driverMutex);
                table[key] = snap;
            }
            mqtt_publish_topic_value(conn.id, logical_name, value_str);
            std::cout << "Write OK (mqtt-dynamic): [" << conn.id << "] "
                      << logical_name << " := " << value_str << "\n";
            return true;
        }
        std::cerr << "Connection/tag not found for write: ["
                  << conn_id << "]." << logical_name << "\n";
        return false;
    }
    if (!cfg.writable) {
        std::cerr << "Tag '" << logical_name
                  << "' is not marked writable in config.\n";
        return false;
    }

    if (is_memory_tag(cfg)) {
        TagValue value{};
        if (!parse_string_to_tagvalue(value_str, cfg.datatype, value)) {
            std::cerr << "Write parse failed for memory tag ["
                      << conn_id << "]." << logical_name
                      << " value '" << value_str << "' as " << cfg.datatype << "\n";
            return false;
        }

        TagSnapshot snap;
        snap.connection_id = conn.id;
        snap.logical_name = logical_name;
        snap.datatype = cfg.datatype;
        snap.timestamp = std::chrono::system_clock::now();
        snap.quality = 1;
        snap.value = value;

        {
            std::lock_guard<std::mutex> lock(driverMutex);
            table[key] = snap;
        }

        std::cout << "Write OK (memory): [" << conn.id << "] "
                  << logical_name << " := " << value_str << "\n";

        if (cfg.log_event_on_change) {
            bool valueChanged = !hadPrev || !snapshot_values_equal(snap, prevSnap);
            if (valueChanged) {
                int64_t ts_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                    snap.timestamp.time_since_epoch()
                ).count();
                sqlite_log_event(
                    conn.id,
                    logical_name,
                    hadPrev ? snapshot_value_to_string(prevSnap) : std::string{},
                    snapshot_value_to_string(snap),
                    hadPrev ? prevSnap.quality : -1,
                    snap.quality,
                    ts_ms,
                    R"({"source":"write_memory"})"
                );
            }
        }

        return true;
    }

    if (to_lower_copy(trim_copy(conn.driver)) == "mqtt") {
        TagValue value{};
        if (!parse_string_to_tagvalue(value_str, cfg.datatype, value)) {
            std::cerr << "Write parse failed for mqtt tag ["
                      << conn_id << "]." << logical_name
                      << " value '" << value_str << "' as " << cfg.datatype << "\n";
            return false;
        }

        TagSnapshot snap;
        snap.connection_id = conn.id;
        snap.logical_name = logical_name;
        snap.datatype = cfg.datatype;
        snap.timestamp = std::chrono::system_clock::now();
        snap.quality = 1;
        snap.value = value;

        {
            std::lock_guard<std::mutex> lock(driverMutex);
            table[key] = snap;
        }

        mqtt_publish_topic_value(conn.id, logical_name, value_str);

        std::cout << "Write OK (mqtt): [" << conn.id << "] "
                  << logical_name << " := " << value_str << "\n";
        return true;
    }

    // Serialize libplctag access across poll loop / HTTP / MQTT / OPC UA
    // only for non-memory writes.
    std::unique_lock<std::shared_mutex> plcLock;
    if (g_plcMutex) {
        plcLock = std::unique_lock<std::shared_mutex>(*g_plcMutex);
    }

    const bool isDerivedBit = (!cfg.source_tag.empty() && cfg.bit >= 0);
    if (isDerivedBit) {
        if (cfg.datatype != "bool") {
            std::cerr << "Derived tag '" << logical_name
                      << "' must have datatype 'bool'.\n";
            return false;
        }
        // Strict derived-bit write: read source tag immediately, modify the bit, write, then verify by re-reading.
        bool desiredPublished = false;
        if (!parse_bool(value_str, desiredPublished)) {
            std::cerr << "Write parse failed for derived bool value '"
                      << value_str << "' for [" << conn_id << "]." << logical_name << "\n";
            return false;
        }

        const bool desiredUnderlying = cfg.invert ? (!desiredPublished) : desiredPublished;

        TagConfig srcCfg;

        const std::string srcName = cfg.source_tag;
        const std::string srcKey = make_tag_key(conn_id, srcName);
        TagSnapshot prevDerived;
        bool hadPrevDerived = false;
        TagSnapshot prevSrc;
        bool hadPrevSrc = false;

        {
            std::lock_guard<std::mutex> lock(driverMutex);
            for (auto &driver : drivers) {
                if (driver.conn.id != conn_id) continue;
                for (auto &t : driver.tags) {
                    if (t.cfg.logical_name == srcName) {
                        srcCfg = t.cfg;
                        break;
                    }
                }
                break;
            }

            auto itPrevD = table.find(key);
            if (itPrevD != table.end()) {
                prevDerived = itPrevD->second;
                hadPrevDerived = true;
            }
            auto itPrevS = table.find(srcKey);
            if (itPrevS != table.end()) {
                prevSrc = itPrevS->second;
                hadPrevSrc = true;
            }
        }

        if (srcCfg.logical_name.empty()) {
            std::cerr << "Derived tag '" << logical_name
                      << "' source tag '" << srcName
                      << "' not found.\n";
            return false;
        }

        if (!srcCfg.writable) {
            std::cerr << "Derived tag '" << logical_name
                      << "' source tag '" << srcName
                      << "' is not marked writable.\n";
            return false;
        }

        if (srcCfg.plc_tag_name.empty()) {
            std::cerr << "Derived tag '" << logical_name
                      << "' source tag '" << srcName
                      << "' is missing plc_tag_name.\n";
            return false;
        }

        if (srcCfg.elem_count > 1) {
            std::cerr << "Derived tag '" << logical_name
                      << "' source tag '" << srcName
                      << "' has elem_count > 1; derived-bit writes require a scalar source (e.g. TagName[0]).\n";
            return false;
        }

        // Use a temporary, scalar handle for strict read-modify-write so we don't risk
        // overwriting other elements of an array handle's buffer.
        TagConfig srcTmp = srcCfg;
        srcTmp.elem_count = 1;

        std::string srcTagStr;
        try {
            srcTagStr = build_tag_conn_str(conn, srcTmp);
        } catch (const std::exception &ex) {
            std::cerr << "Derived write failed building source tag string for ["
                      << conn_id << "]." << srcName << ": " << ex.what() << "\n";
            return false;
        }

        const int32_t srcHandle = plc_tag_create(srcTagStr.c_str(), conn.default_timeout_ms);
        std::string readyErr;
        if (!wait_for_tag_ready(srcHandle, conn.default_timeout_ms, readyErr)) {
            std::cerr << "Derived write failed creating source handle for ["
                      << conn_id << "]." << srcName << ": " << readyErr << "\n";
            if (srcHandle >= 0) plc_tag_destroy(srcHandle);
            return false;
        }

        // Read source fresh
        int rs = plc_tag_read(srcHandle, conn.default_read_ms);
        if (rs != PLCTAG_STATUS_OK) {
            std::cerr << "Derived write read failed for source ["
                      << conn_id << "]." << srcName
                      << ": " << plc_tag_decode_error(rs) << "\n";
            plc_tag_destroy(srcHandle);
            return false;
        }

        uint64_t curWord = 0;
        int wordBits = 0;
        std::string rwErr;
        if (!plc_tag_get_word_u64(srcCfg.datatype, srcHandle, curWord, wordBits, rwErr, is_modbus_connection(conn), srcCfg.word_order)) {
            std::cerr << "Derived write failed for ["
                      << conn_id << "]." << logical_name
                      << ": " << rwErr << "\n";
            plc_tag_destroy(srcHandle);
            return false;
        }
        if (cfg.bit >= wordBits) {
            std::cerr << "Derived write failed for ["
                      << conn_id << "]." << logical_name
                      << ": bit " << cfg.bit << " out of range for " << srcCfg.datatype
                      << " (" << wordBits << " bits)\n";
            plc_tag_destroy(srcHandle);
            return false;
        }

        const uint64_t mask = (1ULL << static_cast<uint64_t>(cfg.bit));
        uint64_t nextWord = desiredUnderlying ? (curWord | mask) : (curWord & ~mask);

        if (!plc_tag_set_word_u64(srcCfg.datatype, srcHandle, nextWord, rwErr, is_modbus_connection(conn), srcCfg.word_order)) {
            std::cerr << "Derived write set failed for source ["
                      << conn_id << "]." << srcName
                      << ": " << rwErr << "\n";
            plc_tag_destroy(srcHandle);
            return false;
        }

        int ws = plc_tag_write(srcHandle, conn.default_write_ms);
        if (ws != PLCTAG_STATUS_OK) {
            std::cerr << "Derived write plc_tag_write failed for source ["
                      << conn_id << "]." << srcName
                      << ": " << plc_tag_decode_error(ws) << "\n";
            plc_tag_destroy(srcHandle);
            return false;
        }

        // Verify by re-reading
        int vs = plc_tag_read(srcHandle, conn.default_read_ms);
        if (vs != PLCTAG_STATUS_OK) {
            std::cerr << "Derived write verify read failed for source ["
                      << conn_id << "]." << srcName
                      << ": " << plc_tag_decode_error(vs) << "\n";
            plc_tag_destroy(srcHandle);
            return false;
        }

        uint64_t verifyWord = 0;
        int verifyBits = 0;
        if (!plc_tag_get_word_u64(srcCfg.datatype, srcHandle, verifyWord, verifyBits, rwErr, is_modbus_connection(conn), srcCfg.word_order)) {
            std::cerr << "Derived write verify get failed for source ["
                      << conn_id << "]." << srcName
                      << ": " << rwErr << "\n";
            plc_tag_destroy(srcHandle);
            return false;
        }

        const bool verifyUnderlying = ((verifyWord >> static_cast<uint64_t>(cfg.bit)) & 1ULL) != 0ULL;
        if (verifyUnderlying != desiredUnderlying) {
            std::cerr << "Derived write verify mismatch for ["
                      << conn_id << "]." << logical_name
                      << ": wrote bit=" << (desiredUnderlying ? "1" : "0")
                      << " but read back " << (verifyUnderlying ? "1" : "0") << "\n";
            plc_tag_destroy(srcHandle);
            return false;
        }

        const auto now = std::chrono::system_clock::now();
        TagSnapshot srcSnap;
        srcSnap.connection_id = conn.id;
        srcSnap.logical_name = srcName;
        srcSnap.datatype = srcCfg.datatype;
        srcSnap.timestamp = now;
        srcSnap.quality = 1;
        if (srcCfg.datatype == "int16") srcSnap.value = static_cast<int16_t>(static_cast<uint16_t>(verifyWord));
        else if (srcCfg.datatype == "uint16") srcSnap.value = static_cast<uint16_t>(verifyWord);
        else if (srcCfg.datatype == "int32") srcSnap.value = static_cast<int32_t>(static_cast<uint32_t>(verifyWord));
        else if (srcCfg.datatype == "uint32") srcSnap.value = static_cast<uint32_t>(verifyWord);

        TagSnapshot dSnap;
        dSnap.connection_id = conn.id;
        dSnap.logical_name = logical_name;
        dSnap.datatype = "bool";
        dSnap.timestamp = now;
        dSnap.quality = 1;
        const bool published = cfg.invert ? (!verifyUnderlying) : verifyUnderlying;
        dSnap.value = published;

        {
            std::lock_guard<std::mutex> lock(driverMutex);
            table[srcKey] = srcSnap;
            table[key] = dSnap;
        }

        plc_tag_destroy(srcHandle);

        std::cout << "Write OK (derived): [" << conn.id << "] "
                  << logical_name << " := " << value_str
                  << " (source=" << srcName << " bit=" << cfg.bit << ")\n";

        if (cfg.log_event_on_change) {
            const bool valueChanged = !hadPrevDerived || !snapshot_values_equal(dSnap, prevDerived);
            if (valueChanged) {
                int64_t ts_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                    now.time_since_epoch()
                ).count();
                sqlite_log_event(
                    conn.id,
                    logical_name,
                    hadPrevDerived ? snapshot_value_to_string(prevDerived) : std::string{},
                    snapshot_value_to_string(dSnap),
                    hadPrevDerived ? prevDerived.quality : -1,
                    dSnap.quality,
                    ts_ms,
                    R"({"source":"write_derived"})"
                );
            }
        }

        // (Optional) event log for the source tag too if it is configured to log on change.
        if (srcCfg.log_event_on_change) {
            const bool valueChanged = !hadPrevSrc || !snapshot_values_equal(srcSnap, prevSrc);
            if (valueChanged) {
                int64_t ts_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                    now.time_since_epoch()
                ).count();
                sqlite_log_event(
                    conn.id,
                    srcName,
                    hadPrevSrc ? snapshot_value_to_string(prevSrc) : std::string{},
                    snapshot_value_to_string(srcSnap),
                    hadPrevSrc ? prevSrc.quality : -1,
                    srcSnap.quality,
                    ts_ms,
                    R"({"source":"write_derived"})"
                );
            }
        }

        return true;
    }

    bool destroyWriteHandle = false;
    if (handle < 0) {
        std::string tagStr;
        try {
            tagStr = build_tag_conn_str(conn, cfg);
        } catch (const std::exception &ex) {
            std::cerr << "Write failed building tag string for ["
                      << conn_id << "]." << logical_name << ": "
                      << ex.what() << "\n";
            return false;
        }

        handle = plc_tag_create(tagStr.c_str(), conn.default_timeout_ms);
        std::string readyErr;
        if (!wait_for_tag_ready(handle, conn.default_timeout_ms, readyErr)) {
            std::cerr << "Write failed creating temporary handle for ["
                      << conn_id << "]." << logical_name << ": "
                      << readyErr << "\n";
            if (handle >= 0) plc_tag_destroy(handle);
            return false;
        }
        destroyWriteHandle = true;
    }

    TagValue rawValue{};
    TagValue scaledValue{};
    std::string parseErr;

    if (scaling_linear) {
        if (!is_numeric_datatype(cfg.datatype)) {
            std::cerr << "Tag '" << logical_name
                      << "' has scaling enabled but non-numeric datatype '" << cfg.datatype
                      << "'.\n";
            if (destroyWriteHandle) plc_tag_destroy(handle);
            return false;
        }

        double scaledNum = 0.0;
        try {
            std::string s = trim_copy(value_str);
            if (s.empty()) {
                std::cerr << "Write value is empty.\n";
                if (destroyWriteHandle) plc_tag_destroy(handle);
                return false;
            }
            scaledNum = std::stod(s);
        } catch (const std::exception &ex) {
            std::cerr << "Write parse failed for scaled value '"
                      << value_str << "': " << ex.what() << "\n";
            if (destroyWriteHandle) plc_tag_destroy(handle);
            return false;
        }

        if (cfg.clamp_low)  scaledNum = std::max(scaledNum, cfg.scaled_low);
        if (cfg.clamp_high) scaledNum = std::min(scaledNum, cfg.scaled_high);

        const double rawNum = scaledNum * inv_slope + inv_offset;

        std::string castErr;
        if (!cast_double_to_tagvalue(rawNum, cfg.datatype, rawValue, castErr)) {
            std::cerr << "Write scaling cast failed for raw datatype '" << cfg.datatype
                      << "': " << castErr << "\n";
            if (destroyWriteHandle) plc_tag_destroy(handle);
            return false;
        }

        const std::string dtOut = out_datatype.empty() ? std::string("float64") : out_datatype;
        if (!cast_double_to_tagvalue(scaledNum, dtOut, scaledValue, castErr)) {
            scaledValue = static_cast<double>(scaledNum);
        }

        if (!plc_tag_set_from_tagvalue(cfg.datatype, handle, rawValue, parseErr, is_modbus_connection(conn), cfg.word_order)) {
            std::cerr << "Write set failed for ["
                      << conn_id << "]." << logical_name
                      << ": " << parseErr << "\n";
            if (destroyWriteHandle) plc_tag_destroy(handle);
            return false;
        }
    } else {
        if (!plc_set_value_from_string(cfg.datatype, handle, value_str, rawValue, parseErr, is_modbus_connection(conn), cfg.word_order)) {
            std::cerr << "Write parse/set failed for ["
                      << conn_id << "]." << logical_name
                      << ": " << parseErr << "\n";
            if (destroyWriteHandle) plc_tag_destroy(handle);
            return false;
        }
        scaledValue = rawValue;
    }

    int status = plc_tag_write(handle, conn.default_write_ms);
    if (status != PLCTAG_STATUS_OK) {
        std::cerr << "plc_tag_write failed for ["
                  << conn_id << "]." << logical_name
                  << ": " << plc_tag_decode_error(status) << "\n";
        if (destroyWriteHandle) plc_tag_destroy(handle);
        return false;
    }

    TagSnapshot snap;
    snap.connection_id = conn.id;
    snap.logical_name  = logical_name;
    snap.datatype      = scaling_linear ? (out_datatype.empty() ? std::string("float64") : out_datatype) : cfg.datatype;
    snap.timestamp     = std::chrono::system_clock::now();
    snap.quality       = 1;
    snap.value         = scaling_linear ? scaledValue : rawValue;

    {
        std::lock_guard<std::mutex> lock(driverMutex);
        table[key] = snap;
    }

    std::cout << "Write OK: [" << conn.id << "] "
              << logical_name << " := " << value_str << "\n";

    if (destroyWriteHandle) {
        plc_tag_destroy(handle);
        handle = PLCTAG_ERR_NOT_FOUND;
    }

    if (cfg.log_event_on_change) {
        bool valueChanged = !hadPrev || !snapshot_values_equal(snap, prevSnap);
        if (valueChanged) {
            int64_t ts_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                snap.timestamp.time_since_epoch()
            ).count();

            std::string oldVal = hadPrev ? snapshot_value_to_string(prevSnap) : std::string{};
            std::string newVal = snapshot_value_to_string(snap);
            int oldQ = hadPrev ? prevSnap.quality : -1;
            int newQ = snap.quality;

            std::string extra = R"({"source":"write"})";

            sqlite_log_event(
                conn.id,
                logical_name,
                oldVal,
                newVal,
                oldQ,
                newQ,
                ts_ms,
                extra
            );
        }
    }

    return true;
}

// -----------------------------
// Read helpers / dump
// -----------------------------

	bool read_all_tags_once(std::vector<DriverContext> &drivers, TagTable &tagTable) {
	    bool all_ok = true;

	    // Serialize libplctag access (read + get) with the poll loop / HTTP endpoints.
	    std::shared_lock<std::shared_mutex> plcLock;
	    if (g_plcMutex) {
	        plcLock = std::shared_lock<std::shared_mutex>(*g_plcMutex);
	    }

    for (auto &driver : drivers) {
        for (auto &t : driver.tags) {
            if (t.handle < 0) {
                if (is_memory_tag(t.cfg) || !t.cfg.source_tag.empty()) {
                    continue;
                }
                std::cerr << "Skipping tag '" << t.cfg.logical_name
                          << "' on connection '" << driver.conn.id
                          << "' because handle is invalid.\n";
                all_ok = false;
                continue;
            }

            int32_t status = plc_tag_read(t.handle,
                                          driver.conn.default_read_ms);

            const bool isArray = (t.cfg.elem_count > 1);
            if (!isArray) {
                std::string key = make_tag_key(driver.conn.id, t.cfg.logical_name);

                if (status != PLCTAG_STATUS_OK) {
                    std::cerr << "Read error for ["
                              << driver.conn.id << "]."
                              << t.cfg.logical_name << ": "
                              << plc_tag_decode_error(status) << std::endl;

                    TagSnapshot &snap = tagTable[key];
                    snap.connection_id = driver.conn.id;
                    snap.logical_name  = t.cfg.logical_name;
                    snap.datatype      = t.cfg.datatype;
                    snap.timestamp     = std::chrono::system_clock::now();
                    snap.quality       = 0;

                    all_ok = false;
                } else {
                    TagSnapshot &snap = tagTable[key];
                    update_snapshot_from_plc(snap, driver.conn, t);
                }
            } else {
                const int ec = std::max(1, t.cfg.elem_count);
                const int elemSize = static_cast<int>(datatype_size_bytes(t.cfg.datatype));
                const auto ts = std::chrono::system_clock::now();

                if (status != PLCTAG_STATUS_OK) {
                    std::cerr << "Read error for ["
                              << driver.conn.id << "]."
                              << t.cfg.logical_name << ": "
                              << plc_tag_decode_error(status) << std::endl;
                    all_ok = false;
                }

                for (int i = 0; i < ec; i++) {
                    TagRuntime etmp = t;
                    etmp.cfg.elem_count = 1;
                    etmp.cfg.logical_name = t.cfg.logical_name + "[" + std::to_string(i) + "]";

                    const std::string ekey = make_tag_key(driver.conn.id, etmp.cfg.logical_name);
                    TagSnapshot &esnap = tagTable[ekey];
                    if (status != PLCTAG_STATUS_OK) {
                        esnap.connection_id = driver.conn.id;
                        esnap.logical_name  = etmp.cfg.logical_name;
                        esnap.datatype      = t.cfg.datatype;
                        esnap.timestamp     = ts;
                        esnap.quality       = 0;
                    } else {
                        update_snapshot_from_plc_at_offset(esnap, driver.conn, etmp, i * elemSize);
                        esnap.timestamp = ts;
                    }
                }
            }
        }
    }

    return all_ok;
}

bool dump_tag_table_once(std::vector<DriverContext> &drivers, TagTable &tagTable) {
    bool ok = read_all_tags_once(drivers, tagTable);
    for (const auto &kv : tagTable) {
        print_snapshot(kv.second);
    }
    return ok;
}

void dump_tag_table_as_json(const TagTable &tagTable) {
    json root;
    root["tags"] = json::array();

    for (const auto &kv : tagTable) {
        const TagSnapshot &snap = kv.second;
        json jt;
        jt["connection_id"] = snap.connection_id;
        jt["name"]          = snap.logical_name;
        jt["datatype"]      = snap.datatype;
        jt["quality"]       = snap.quality;

        auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
            snap.timestamp.time_since_epoch()
        ).count();
        jt["timestamp_ms"] = ms;

        std::visit([&jt](auto &&arg) {
            jt["value"] = arg;
        }, snap.value);

        root["tags"].push_back(jt);
    }

    std::cout << root.dump(2) << std::endl;
}

void schedule_next_periodic(TagRuntime &tagRt);

// -----------------------------
// Driver loading / reload
// -----------------------------

		void destroy_all_handles(std::vector<DriverContext> &drivers, bool plcAlreadyLocked = false) {
		    std::unique_lock<std::shared_mutex> plcLock;
		    if (!plcAlreadyLocked && g_plcMutex) {
		        plcLock = std::unique_lock<std::shared_mutex>(*g_plcMutex);
		    }

	    for (auto &driver : drivers) {
	        for (auto &t : driver.tags) {
	            if (t.handle >= 0) {
                plc_tag_destroy(t.handle);
	                t.handle = PLCTAG_ERR_NOT_FOUND;
	            }
	        }
	    }
	}

static void destroy_driver_handles(DriverContext &driver, bool plcAlreadyLocked = false) {
    std::unique_lock<std::shared_mutex> plcLock;
    if (!plcAlreadyLocked && g_plcMutex) {
        plcLock = std::unique_lock<std::shared_mutex>(*g_plcMutex);
    }
    for (auto &t : driver.tags) {
        if (t.handle >= 0) {
            plc_tag_destroy(t.handle);
            t.handle = PLCTAG_ERR_NOT_FOUND;
        }
    }
}

static bool build_driver_context_for_connection(const ConnectionConfig &conn_cfg,
                                                const std::vector<TagConfig> &tag_cfgs,
                                                DriverContext &out,
                                                std::string &err)
{
    const auto connBuildStarted = std::chrono::steady_clock::now();
    DriverContext ctx;
    ctx.conn = conn_cfg;
    std::unordered_set<std::string> seen_logical_names;
    size_t processedTags = 0;
    size_t createdHandles = 0;
    size_t deferredHandles = 0;
    size_t pendingHandles = 0;
    size_t failedHandles = 0;
    auto lastProgress = std::chrono::steady_clock::now();

    {
        std::ostringstream msg;
        msg << "Building connection '" << conn_cfg.id << "' with "
            << tag_cfgs.size() << " configured tag(s)"
            << " (startup_handle_wait_ms=" << conn_cfg.startup_handle_wait_ms << ").";
        runtime_log("info", "load", msg.str());
    }

    for (const auto &tc : tag_cfgs) {
        processedTags++;
        const std::string logical = tc.logical_name;
        if (!logical.empty() && !seen_logical_names.insert(logical).second) {
            std::cerr << "[load] Warning: duplicate tag logical_name '" << logical
                      << "' for connection '" << conn_cfg.id << "'. Skipping duplicate.\n";
            continue;
        }

        TagRuntime rt;
        rt.cfg = tc;
        init_tag_scaling(rt);

        if (!tc.enabled) {
            rt.handle = PLCTAG_ERR_NOT_FOUND;
            ctx.tags.push_back(std::move(rt));
            continue;
        }

        if (is_memory_tag(tc)) {
            rt.handle = PLCTAG_ERR_NOT_FOUND;
            rt.next_poll = std::chrono::steady_clock::time_point{};
            ctx.tags.push_back(std::move(rt));
            continue;
        }

        if (!tc.source_tag.empty()) {
            rt.handle = PLCTAG_ERR_NOT_FOUND;
            rt.next_poll = std::chrono::steady_clock::time_point{};
            ctx.tags.push_back(std::move(rt));
            continue;
        }

        if (!is_supported_datatype(tc.datatype)) {
            std::cerr << "[load] Warning: skipping tag '" << tc.logical_name
                      << "' on connection '" << conn_cfg.id
                      << "' due to unsupported datatype '" << tc.datatype << "'.\n";
            rt.handle = PLCTAG_ERR_NOT_FOUND;
            ctx.tags.push_back(std::move(rt));
            continue;
        }

        std::string tag_str;
        try {
            tag_str = build_tag_conn_str(conn_cfg, tc);
        } catch (const std::exception &ex) {
            std::cerr << "[load] Warning: skipping tag '" << tc.logical_name
                      << "' on connection '" << conn_cfg.id
                      << "' due to error building connection string: " << ex.what() << "\n";
            rt.handle = PLCTAG_ERR_NOT_FOUND;
            ctx.tags.push_back(std::move(rt));
            continue;
        }

        const bool deferStartupHandle = true;
        if (deferStartupHandle) {
            rt.handle = PLCTAG_ERR_NOT_FOUND;
            rt.handle_deferred = true;
            rt.next_poll = std::chrono::steady_clock::now();
            schedule_next_periodic(rt);
            deferredHandles++;
            ctx.tags.push_back(rt);

            if (tc.elem_count > 1) {
                for (int i = 0; i < tc.elem_count; i++) {
                    TagRuntime e;
                    e.cfg = tc;
                    e.cfg.elem_count = 1;
                    e.cfg.source_tag.clear();
                    e.cfg.bit = -1;
                    e.cfg.logical_name = tc.logical_name + "[" + std::to_string(i) + "]";
                    e.cfg.plc_tag_name = tc.plc_tag_name + "[" + std::to_string(i) + "]";
                    e.handle = PLCTAG_ERR_NOT_FOUND;
                    e.handle_deferred = false;
                    const std::string elName = e.cfg.logical_name;
                    if (!elName.empty() && !seen_logical_names.insert(elName).second) {
                        continue;
                    }
                    ctx.tags.push_back(std::move(e));
                }
            }
            continue;
        }

        const int32_t handle = plc_tag_create(tag_str.c_str(), conn_cfg.default_timeout_ms);
        std::string readyErr;
        bool pending = false;
        if (!accept_startup_handle(handle, conn_cfg.startup_handle_wait_ms, pending, readyErr)) {
            std::cerr << "[load] Error creating tag '" << tc.logical_name
                      << "' on connection '" << conn_cfg.id << "': " << readyErr
                      << " (startup_handle_wait_ms=" << conn_cfg.startup_handle_wait_ms << ")\n";
            if (handle >= 0) plc_tag_destroy(handle);
            rt.handle = PLCTAG_ERR_NOT_FOUND;
            failedHandles++;
        } else {
            createdHandles++;
            if (pending) pendingHandles++;
            rt.handle = handle;
            rt.next_poll = std::chrono::steady_clock::now();
            schedule_next_periodic(rt);
        }
        ctx.tags.push_back(rt);

        if (tc.elem_count > 1) {
            for (int i = 0; i < tc.elem_count; i++) {
                TagRuntime e;
                e.cfg = tc;
                e.cfg.elem_count = 1;
                e.cfg.source_tag.clear();
                e.cfg.bit = -1;
                e.cfg.logical_name = tc.logical_name + "[" + std::to_string(i) + "]";
                e.cfg.plc_tag_name = tc.plc_tag_name + "[" + std::to_string(i) + "]";
                e.handle = PLCTAG_ERR_NOT_FOUND;
                const std::string elName = e.cfg.logical_name;
                if (!elName.empty() && !seen_logical_names.insert(elName).second) {
                    continue;
                }
                ctx.tags.push_back(std::move(e));
            }
        }

        const auto nowProgress = std::chrono::steady_clock::now();
        if ((processedTags % 500) == 0 ||
            std::chrono::duration_cast<std::chrono::seconds>(nowProgress - lastProgress).count() >= 30) {
            std::ostringstream msg;
            msg << "Connection '" << conn_cfg.id << "' progress: "
                << processedTags << "/" << tag_cfgs.size()
                << " configured tags processed, handles=" << createdHandles
                << ", deferred=" << deferredHandles
                << ", pending=" << pendingHandles
                << ", failed=" << failedHandles
                << ", elapsed_ms=" << steady_elapsed_ms(connBuildStarted) << ".";
            runtime_log("info", "load", msg.str());
            lastProgress = nowProgress;
        }
    }

    size_t validHandles = 0;
    size_t deferredRuntimeHandles = 0;
    for (const auto &rt : ctx.tags) {
        if (rt.handle >= 0) validHandles++;
        if (rt.handle_deferred) deferredRuntimeHandles++;
    }
    {
        std::ostringstream msg;
        msg << "Built connection '" << conn_cfg.id << "' in "
            << steady_elapsed_ms(connBuildStarted) << " ms (runtime tags="
            << ctx.tags.size() << ", handles=" << validHandles
            << ", deferred_handles=" << deferredRuntimeHandles
            << ", pending_at_start=" << pendingHandles
            << ", failed_handles=" << failedHandles << ").";
        runtime_log(failedHandles > 0 ? "warn" : "info", "load", msg.str());
    }
    out = std::move(ctx);
    err.clear();
    return true;
}

static bool load_single_driver_for_connection(DriverContext &out,
                                              bool &hasDriver,
                                              const std::string &configDir,
                                              const std::string &connId,
                                              std::string &err)
{
    hasDriver = false;
    err.clear();
    if (connId.empty()) {
        err = "Missing connection_id.";
        return false;
    }

    const std::string connDir = joinPath(configDir, "connections");
    const std::string tagDir = joinPath(configDir, "tags");

    bool foundConn = false;
    ConnectionConfig conn_cfg;
    if (!fs::exists(connDir)) {
        err = "Connections directory does not exist.";
        return false;
    }
    for (const auto &entry : fs::directory_iterator(connDir)) {
        if (!entry.is_regular_file()) continue;
        if (entry.path().extension() != ".json") continue;
        try {
            ConnectionConfig c = load_connection_config(entry.path().string());
            if (c.id == connId) {
                conn_cfg = c;
                foundConn = true;
                break;
            }
        } catch (const std::exception &ex) {
            std::cerr << "[reload] Error reading connection file " << entry.path().string()
                      << ": " << ex.what() << "\n";
        }
    }
    if (!foundConn) {
        err = "Connection '" + connId + "' not found.";
        return false;
    }

    const std::string canonicalJson = joinPath(tagDir, connId + ".json");
    const std::string canonicalJsonc = joinPath(tagDir, connId + ".jsonc");
    std::string tagPath;
    if (fs::exists(canonicalJson)) tagPath = canonicalJson;
    else if (fs::exists(canonicalJsonc)) tagPath = canonicalJsonc;
    else if (fs::exists(tagDir)) {
        for (const auto &entry : fs::directory_iterator(tagDir)) {
            if (!entry.is_regular_file()) continue;
            const std::string ext = entry.path().extension().string();
            if (ext != ".json" && ext != ".jsonc") continue;
            try {
                TagFile tf = load_tag_file(entry.path().string());
                if (tf.connection_id == connId) {
                    tagPath = entry.path().string();
                    break;
                }
            } catch (...) {
                // Ignore malformed unrelated tag files here; full reload reports them.
            }
        }
    }

    if (tagPath.empty()) {
        std::cerr << "[reload] Info: no tags defined for connection '" << connId << "'.\n";
        hasDriver = false;
        return true;
    }

    TagFile tf = load_tag_file(tagPath);
    if (tf.connection_id != connId) {
        err = "Tag file connection_id does not match target connection.";
        return false;
    }

    DriverContext ctx;
    if (!build_driver_context_for_connection(conn_cfg, tf.tags, ctx, err)) {
        return false;
    }
    hasDriver = true;
    out = std::move(ctx);
    return true;
}

bool load_mqtt_config(const std::string &configDir) {
    MqttConfig cfg; // starts with defaults
    const std::string connDir = joinPath(configDir, "connections");

    if (fs::exists(connDir)) {
        std::vector<fs::path> connFiles;
        for (const auto &entry : fs::directory_iterator(connDir)) {
            if (!entry.is_regular_file()) continue;
            if (entry.path().extension() != ".json") continue;
            connFiles.push_back(entry.path());
        }
        std::sort(connFiles.begin(), connFiles.end());
        for (const auto &connPath : connFiles) {
            try {
                json jc = load_json_with_comments(connPath.string());
                if (jc.value("driver", std::string("ab_eip")) != "mqtt") continue;
                const json settings = (jc.contains("settings") && jc["settings"].is_object()) ? jc["settings"] : json::object();
                const std::string host = trim_copy(settings.value("host", jc.value("host", std::string{})));
                if (host.empty()) continue;

                cfg.enabled = settings.value("enabled", jc.value("enabled", true));
                cfg.host = host;
                cfg.use_tls = settings.value("use_tls", jc.value("use_tls", cfg.use_tls));
                cfg.port = settings.value("port", jc.value("port", cfg.use_tls ? 8883 : cfg.port));
                cfg.client_id = settings.value("client_id", jc.value("client_id", cfg.client_id));
                cfg.username = settings.value("username", jc.value("username", cfg.username));
                cfg.password = settings.value("password", jc.value("password", cfg.password));
                cfg.tls_insecure = settings.value("tls_insecure", jc.value("tls_insecure", cfg.tls_insecure));
                cfg.cafile = settings.value("cafile", jc.value("cafile", cfg.cafile));
                cfg.capath = settings.value("capath", jc.value("capath", cfg.capath));
                cfg.certfile = settings.value("certfile", jc.value("certfile", cfg.certfile));
                cfg.keyfile = settings.value("keyfile", jc.value("keyfile", cfg.keyfile));
                cfg.tls_version = settings.value("tls_version", jc.value("tls_version", cfg.tls_version));
                cfg.qos = settings.value("qos", jc.value("qos", cfg.qos));
                cfg.keepalive = settings.value("keepalive", jc.value("keepalive", cfg.keepalive));
                cfg.publish_per_field = settings.value("publish_per_field", cfg.publish_per_field);
                cfg.publish_tag_json = settings.value("publish_tag_json", cfg.publish_tag_json);
                cfg.publish_conn_json = settings.value("publish_conn_json", cfg.publish_conn_json);
                cfg.publish_memory_tags = settings.value("publish_memory_tags", cfg.publish_memory_tags);
                cfg.publish_system_tags = settings.value("publish_system_tags", cfg.publish_system_tags);
                cfg.publish_mode = to_lower_copy(trim_copy(settings.value("publish_mode", cfg.publish_mode)));
                cfg.publish_interval_ms = settings.value("publish_interval_ms", cfg.publish_interval_ms);
                cfg.publish_min_update_ms = settings.value("publish_min_update_ms", cfg.publish_min_update_ms);
                if (settings.contains("publish") && settings["publish"].is_object()) {
                    const auto &p = settings["publish"];
                    cfg.publish_per_field = p.value("per_field", cfg.publish_per_field);
                    cfg.publish_tag_json = p.value("tag_json", cfg.publish_tag_json);
                    cfg.publish_conn_json = p.value("connection_json", cfg.publish_conn_json);
                    cfg.publish_memory_tags = p.value("memory_tags", cfg.publish_memory_tags);
                    cfg.publish_system_tags = p.value("system_tags", cfg.publish_system_tags);
                    cfg.publish_mode = to_lower_copy(trim_copy(p.value("mode", cfg.publish_mode)));
                    cfg.publish_interval_ms = p.value("interval_ms", cfg.publish_interval_ms);
                    cfg.publish_min_update_ms = p.value("min_update_ms", cfg.publish_min_update_ms);
                }
                if (cfg.publish_mode != "change" &&
                    cfg.publish_mode != "interval" &&
                    cfg.publish_mode != "change_or_interval") {
                    cfg.publish_mode = "change";
                }
                cfg.publish_interval_ms = std::max(100, cfg.publish_interval_ms);
                cfg.publish_min_update_ms = std::max(0, cfg.publish_min_update_ms);
                cfg.subscribe_enabled = true;
                cfg.command_topic = settings.value("command_topic", jc.value("command_topic", cfg.command_topic));
                cfg.ack_topic_prefix = settings.value("ack_topic_prefix", jc.value("ack_topic_prefix", cfg.ack_topic_prefix));
                if (cfg.command_topic.empty()) cfg.command_topic = cfg.base_topic + "/cmd";
                if (cfg.ack_topic_prefix.empty()) cfg.ack_topic_prefix = cfg.base_topic + "/ack";

                g_mqttCfg = cfg;
                std::cout << "[mqtt] Loaded active broker from MQTT connection file "
                          << connPath.string() << " (" << cfg.host << ":" << cfg.port << ")\n";
                return true;
            } catch (const std::exception &ex) {
                std::cerr << "[mqtt] Error reading MQTT connection file "
                          << connPath.string() << ": " << ex.what() << "\n";
            }
        }
    }

    std::string path = joinPath(configDir, "mqtt.json");

    if (!fs::exists(path)) {
        std::cout << "[mqtt] mqtt.json not found, using defaults: "
                  << cfg.host << ":" << cfg.port
                  << " base_topic='" << cfg.base_topic << "'\n";
        g_mqttCfg = cfg;
        return true;
    }

    try {
        json j = load_json_with_comments(path);

        cfg.enabled       = j.value("enabled", cfg.enabled);
        cfg.host          = j.value("host", cfg.host);
        cfg.port          = j.value("port", cfg.port);
        cfg.client_id     = j.value("client_id", cfg.client_id);
        cfg.base_topic    = j.value("base_topic", cfg.base_topic);
        cfg.qos           = j.value("qos", cfg.qos);
        cfg.retain        = j.value("retain", cfg.retain);
        cfg.keepalive     = j.value("keepalive", cfg.keepalive);
        cfg.username      = j.value("username", cfg.username);
        cfg.password      = j.value("password", cfg.password);
        cfg.publish_only_on_change = j.value("publish_only_on_change",
                                             cfg.publish_only_on_change);
        cfg.payload_format = j.value("payload_format", cfg.payload_format);
        cfg.publish_mode = to_lower_copy(trim_copy(j.value("publish_mode", cfg.publish_mode)));
        cfg.publish_interval_ms = j.value("publish_interval_ms", cfg.publish_interval_ms);
        cfg.publish_min_update_ms = j.value("publish_min_update_ms", cfg.publish_min_update_ms);
        if (j.contains("publish") && j["publish"].is_object()) {
            const auto &p = j["publish"];
            cfg.publish_mode = to_lower_copy(trim_copy(p.value("mode", cfg.publish_mode)));
            cfg.publish_interval_ms = p.value("interval_ms", cfg.publish_interval_ms);
            cfg.publish_min_update_ms = p.value("min_update_ms", cfg.publish_min_update_ms);
        }
        if (cfg.publish_mode.empty()) {
            cfg.publish_mode = cfg.publish_only_on_change ? "change" : "change_or_interval";
        }
        if (cfg.publish_mode != "change" &&
            cfg.publish_mode != "interval" &&
            cfg.publish_mode != "change_or_interval") {
            std::cerr << "[mqtt] Invalid publish_mode '" << cfg.publish_mode
                      << "', using 'change'.\n";
            cfg.publish_mode = "change";
        }
        cfg.publish_interval_ms = std::max(100, cfg.publish_interval_ms);
        cfg.publish_min_update_ms = std::max(0, cfg.publish_min_update_ms);

        cfg.subscribe_enabled = j.value("subscribe_enabled", false);
        cfg.command_topic     = j.value("command_topic", std::string{});

        // NEW: ack_base_topic from config (optional)
        cfg.ack_topic_prefix  = j.value("ack_topic_prefix", cfg.ack_topic_prefix);

        // If not explicitly set, derive command/ack topics from base_topic
        if (cfg.command_topic.empty()) {
            cfg.command_topic = cfg.base_topic + "/cmd";
        }
        if (cfg.ack_topic_prefix.empty()) {
            cfg.ack_topic_prefix = cfg.base_topic + "/ack";
        }

        // Optional patterns section (if you’re using it)
        if (j.contains("patterns") && j["patterns"].is_object()) {
            const auto &p = j["patterns"];
            cfg.publish_per_field   = p.value("per_field",   cfg.publish_per_field);
            cfg.publish_tag_json    = p.value("tag_json",    cfg.publish_tag_json);
            cfg.publish_conn_json   = p.value("connection_json",
                                              cfg.publish_conn_json);
            cfg.publish_memory_tags = p.value("memory_tags", cfg.publish_memory_tags);
            cfg.publish_system_tags = p.value("system_tags", cfg.publish_system_tags);
        }

        // NEW: token-based auth for MQTT writes
        cfg.require_write_token = j.value("require_write_token", cfg.require_write_token);
        cfg.write_token         = j.value("write_token",         cfg.write_token);

        // NEW: TLS configuration
        cfg.use_tls     = j.value("use_tls", cfg.use_tls);
        cfg.cafile      = j.value("cafile", cfg.cafile);
        cfg.capath      = j.value("capath", cfg.capath);
        cfg.certfile    = j.value("certfile", cfg.certfile);
        cfg.keyfile     = j.value("keyfile", cfg.keyfile);
        cfg.tls_version = j.value("tls_version", cfg.tls_version);
        cfg.tls_insecure= j.value("tls_insecure", cfg.tls_insecure);



        g_mqttCfg = cfg;
        std::cout << "[mqtt] Loaded config from " << path << "\n";
        std::cout << "[mqtt]  base_topic:      " << g_mqttCfg.base_topic << "\n";
        std::cout << "[mqtt]  command_topic:   " << g_mqttCfg.command_topic << "\n";
        std::cout << "[mqtt]  ack_topic_prefix: " << g_mqttCfg.ack_topic_prefix << "\n";
        std::cout << "[mqtt]  use_tls:          " << (g_mqttCfg.use_tls ? "true" : "false") << "\n";
        if (g_mqttCfg.use_tls) {
            std::cout << "[mqtt]   cafile:      " << g_mqttCfg.cafile << "\n";
            std::cout << "[mqtt]   capath:      " << g_mqttCfg.capath << "\n";
            std::cout << "[mqtt]   certfile:    " << g_mqttCfg.certfile << "\n";
            std::cout << "[mqtt]   keyfile:     " << g_mqttCfg.keyfile << "\n";
            std::cout << "[mqtt]   tls_version: " << g_mqttCfg.tls_version << "\n";
            std::cout << "[mqtt]   tls_insecure:" << (g_mqttCfg.tls_insecure ? "true" : "false") << "\n";
        }        return true;
    } catch (const std::exception &ex) {
        std::cerr << "[mqtt] Error loading mqtt.json: " << ex.what() << "\n";
        return false;
    }
}

bool load_mqtt_inputs(const std::string &configDir) {
    g_mqttInputs.clear();
    g_mqttInputsByTopic.clear();
    g_mqttPublicationTopicsByConn.clear();
    g_mqttKnownConnectionIds.clear();
    {
        std::lock_guard<std::mutex> lock(g_mqttDirectPublishPolicyMutex);
        g_mqttDirectPublishPolicyByKey.clear();
    }
    {
        std::lock_guard<std::mutex> lock(g_mqttSubscriptionHealthMutex);
        g_mqttSubscriptionHealth.clear();
    }
    std::string path = joinPath(configDir, "mqtt_inputs.json");

    try {
        json j = json::object();
        std::cout << "[mqtt-inputs] init: looking for " << path << "\n";
        const bool hasLegacyInputs = fs::exists(path);
        if (hasLegacyInputs) {
            j = load_json_with_comments(path);

            if ((!j.contains("inputs") || !j["inputs"].is_array()) &&
                (!j.contains("messages") || !j["messages"].is_array())) {
                std::cerr << "[mqtt-inputs] '" << path
                          << "' must contain an 'inputs' or 'messages' array.\n";
                return false;
            }
        } else {
            std::cout << "[mqtt-inputs] mqtt_inputs.json not found; checking MQTT connection files.\n";
        }

        size_t idx = 0;
        auto add_mapping = [&](MqttInputMapping m) {
            m.id = trim_copy(m.id);
            m.topic = trim_copy(m.topic);
            m.connection_id = trim_copy(m.connection_id);
            m.tag_name = trim_copy(m.tag_name);
            m.datatype = trim_copy(m.datatype);
            m.payload_format = trim_copy(to_lower_copy(m.payload_format));
            m.json_field = trim_copy(m.json_field);
            m.json_path = trim_copy(m.json_path);

            if (m.id.empty()) {
                m.id = "input_" + std::to_string(idx);
            }

            bool ok = true;
            if (m.topic.empty()) {
                std::cerr << "[mqtt-inputs] Skipping input '" << m.id
                          << "': missing 'topic'.\n";
                ok = false;
            }
            if (m.connection_id.empty()) {
                std::cerr << "[mqtt-inputs] Skipping input '" << m.id
                          << "': missing 'connection_id'.\n";
                ok = false;
            }
            if (m.tag_name.empty()) {
                std::cerr << "[mqtt-inputs] Skipping input '" << m.id
                          << "': missing 'tag_name'.\n";
                ok = false;
            }
            if (m.datatype.empty()) {
                std::cerr << "[mqtt-inputs] Skipping input '" << m.id
                          << "': missing 'datatype'.\n";
                ok = false;
            }

            if (m.payload_format == "json_key") {
                m.payload_format = "json_field";
            }

            if (m.payload_format != "raw" &&
                m.payload_format != "json_field" &&
                m.payload_format != "json_path") {
                std::cerr << "[mqtt-inputs] Input '" << m.id
                          << "' has invalid payload_format '" << m.payload_format
                          << "'. Expected 'raw', 'json_field', 'json_key', or 'json_path'.\n";
                ok = false;
            }

            if (m.payload_format == "json_field" && m.json_field.empty()) {
                std::cerr << "[mqtt-inputs] Input '" << m.id
                          << "' has payload_format='json_field' but no 'json_field'/'key' name.\n";
                ok = false;
            }

            if (m.payload_format == "json_path" && m.json_path.empty()) {
                std::cerr << "[mqtt-inputs] Input '" << m.id
                          << "' has payload_format='json_path' but no 'json_path'/'path'.\n";
                ok = false;
            }

            if (!ok) {
                return;
            }

            size_t newIdx = g_mqttInputs.size();
            g_mqttInputs.push_back(std::move(m));
            g_mqttInputsByTopic[g_mqttInputs.back().topic].push_back(newIdx);
            {
                std::lock_guard<std::mutex> lock(g_mqttSubscriptionHealthMutex);
                g_mqttSubscriptionHealth.try_emplace(mqtt_subscription_health_key(g_mqttInputs.back()));
            }
            ++idx;
        };

        if (j.contains("inputs") && j["inputs"].is_array()) {
            for (const auto &ji : j["inputs"]) {
                MqttInputMapping m;

                m.id            = ji.value("id", std::string{});
                m.topic         = ji.value("topic", std::string{});
                m.connection_id = ji.value("connection_id", std::string{});
                m.tag_name      = ji.value("tag_name", std::string{});
                m.datatype      = ji.value("datatype", std::string{});

                m.write_to_plc   = ji.value("write_to_plc", true);
                m.payload_format = ji.value("payload_format", std::string("raw"));
                m.json_field     = ji.value("json_field", ji.value("key", std::string{}));
                m.json_path      = ji.value("json_path", ji.value("path", std::string{}));
                m.timeout_enabled = ji.value("timeout_enabled", false);
                m.timeout_ms = ji.value("timeout_ms", int64_t(0));

                add_mapping(std::move(m));
            }
        }

        if (j.contains("messages") && j["messages"].is_array()) {
            for (const auto &jm : j["messages"]) {
                std::string msgId = jm.value("id", std::string{});
                std::string topic = jm.value("topic", std::string{});
                std::string defaultFormat = jm.value("payload_format", std::string("json_field"));
                bool defaultWriteToPlc = jm.value("write_to_plc", true);

                if (!jm.contains("mappings") || !jm["mappings"].is_array()) {
                    std::cerr << "[mqtt-inputs] Skipping message '" << msgId
                              << "': missing 'mappings' array.\n";
                    continue;
                }

                size_t fieldIdx = 0;
                for (const auto &jf : jm["mappings"]) {
                    MqttInputMapping m;
                    std::string key = jf.value("key", jf.value("json_field", std::string{}));
                    std::string pathValue = jf.value("path", jf.value("json_path", std::string{}));
                    m.id = jf.value("id", std::string{});
                    if (m.id.empty()) {
                        m.id = (msgId.empty() ? topic : msgId) + "_" + std::to_string(fieldIdx);
                    }
                    m.topic = topic;
                    m.connection_id = jf.value("connection_id", std::string{});
                    m.tag_name = jf.value("tag_name", std::string{});
                    m.datatype = jf.value("datatype", std::string{});
                    m.write_to_plc = jf.value("write_to_plc", defaultWriteToPlc);
                    m.payload_format = jf.value("payload_format", defaultFormat);
                    m.json_field = key;
                    m.json_path = pathValue;
                    m.timeout_enabled = jm.value("timeout_enabled", false);
                    m.timeout_ms = jm.value("timeout_ms", int64_t(0));
                    add_mapping(std::move(m));
                    ++fieldIdx;
                }
            }
        }

        const std::string connDir = joinPath(configDir, "connections");
        if (fs::exists(connDir)) {
            std::vector<fs::path> connFiles;
            for (const auto &entry : fs::directory_iterator(connDir)) {
                if (!entry.is_regular_file()) continue;
                if (entry.path().extension() != ".json") continue;
                connFiles.push_back(entry.path());
            }
            std::sort(connFiles.begin(), connFiles.end());
            for (const auto &connPath : connFiles) {
                try {
                    json jc = load_json_with_comments(connPath.string());
                    if (jc.value("driver", std::string("ab_eip")) != "mqtt") continue;
                    const std::string connId = trim_copy(jc.value("id", std::string{}));
                    if (connId.empty()) continue;
                    g_mqttKnownConnectionIds.insert(connId);
                    const json settings = (jc.contains("settings") && jc["settings"].is_object()) ? jc["settings"] : json::object();
                    if (settings.contains("publications") && settings["publications"].is_array()) {
                        auto &pubTopics = g_mqttPublicationTopicsByConn[connId];
                        for (const auto &jp : settings["publications"]) {
                            const std::string pubTopic = trim_copy(jp.value("topic", std::string{}));
                            if (pubTopic.empty()) continue;
                            pubTopics.push_back(pubTopic);
                            MqttDirectPublishPolicy policy;
                            policy.mode = to_lower_copy(trim_copy(jp.value(
                                "update_mode",
                                jp.value("publish_mode", std::string("change"))
                            )));
                            if (policy.mode != "change" &&
                                policy.mode != "interval" &&
                                policy.mode != "change_or_interval") {
                                policy.mode = "change";
                            }
                            policy.interval_ms = std::max(100, jp.value(
                                "interval_ms",
                                jp.value("publish_interval_ms", 1000)
                            ));
                            policy.min_update_ms = std::max(0, jp.value(
                                "min_update_ms",
                                jp.value("rate_limit_ms", 0)
                            ));
                            {
                                std::lock_guard<std::mutex> lock(g_mqttDirectPublishPolicyMutex);
                                g_mqttDirectPublishPolicyByKey[make_tag_key(connId, pubTopic)] = policy;
                            }
                        }
                    }
                    if (!settings.contains("messages") || !settings["messages"].is_array()) continue;
                    size_t msgIdx = 0;
                    for (const auto &jm : settings["messages"]) {
                        const std::string topic = trim_copy(jm.value("topic", std::string{}));
                        if (topic.empty()) {
                            ++msgIdx;
                            continue;
                        }
                        MqttInputMapping m;
                        m.id = jm.value("id", std::string{});
                        if (m.id.empty()) m.id = "subscription_" + std::to_string(msgIdx);
                        m.topic = topic;
                        m.connection_id = connId;
                        m.tag_name = topic + "/RawPayload";
                        m.datatype = "string";
                        m.write_to_plc = false;
                        m.payload_format = "raw";
                        m.timeout_enabled = jm.value("timeout_enabled", false);
                        m.timeout_ms = jm.value("timeout_ms", int64_t(0));
                        add_mapping(std::move(m));
                        ++msgIdx;
                    }
                } catch (const std::exception &ex) {
                    std::cerr << "[mqtt-inputs] Error reading MQTT connection file "
                              << connPath.string() << ": " << ex.what() << "\n";
                }
            }
        }

        std::cout << "[mqtt-inputs] Loaded " << g_mqttInputs.size()
                  << " MQTT telemetry input mapping(s).\n";
        return true;
    } catch (const std::exception &ex) {
        std::cerr << "[mqtt-inputs] Error loading '" << path << "': "
                  << ex.what() << "\n";
        return false;
    }
}

bool load_logic_config(const std::string &configDir, bool force = false) {
    const auto started = std::chrono::steady_clock::now();
    const int64_t nowMs = system_wall_now_ms();
    const std::string path = joinPath(configDir, "logic.json");
    const int64_t mtimeMs = fs::exists(path) ? file_mtime_ms(path) : -1;

    {
        std::lock_guard<std::mutex> lock(g_logicMutex);
        if (!force && g_logicState.config_loaded && mtimeMs == g_logicState.config_mtime_ms) {
            return true;
        }
    }

    LogicRuntimeState next;
    next.config_loaded = true;
    next.last_load_ok = true;
    next.validation_only = true;
    next.last_load_ms = nowMs;
    next.config_mtime_ms = mtimeMs;

    try {
        if (!fs::exists(path)) {
            next.last_error.clear();
            next.last_load_duration_ms = steady_elapsed_ms(started);
            {
                std::lock_guard<std::mutex> lock(g_logicMutex);
                g_logicState = std::move(next);
            }
            std::cout << "[logic] logic.json not found; logic runtime scaffold loaded with 0 scripts.\n";
            return true;
        }

        std::unordered_map<std::string, LogicScriptConfig> previousById;
        {
            std::lock_guard<std::mutex> lock(g_logicMutex);
            for (const auto &script : g_logicState.scripts) {
                if (!script.id.empty()) previousById[script.id] = script;
            }
            next.runs_total = g_logicState.runs_total;
            next.failures_total = g_logicState.failures_total;
            next.last_run_ms = g_logicState.last_run_ms;
        }

        json j = load_json_with_comments(path);
        if (!j.is_object()) {
            throw std::runtime_error("logic.json must be a JSON object.");
        }
        if (!j.contains("scripts") || !j["scripts"].is_array()) {
            throw std::runtime_error("logic.json must contain a 'scripts' array.");
        }
        if (!j.contains("blocks") || !j["blocks"].is_array()) {
            throw std::runtime_error("logic.json must contain a 'blocks' array.");
        }
        const json scripts = j["scripts"];
        const json blocks = j["blocks"];

        std::unordered_set<std::string> seenIds;
        auto load_item = [&](const json &js, const std::string &kind) {
            if (!js.is_object()) return;
            LogicScriptConfig script;
            script.kind = kind;
            script.id = trim_copy(json_get_string_loose(js, "id", std::string{}));
            if (script.id.empty()) {
                std::cerr << "[logic] Skipping " << kind << " with missing id.\n";
                return;
            }
            if (!seenIds.insert(script.id).second) {
                std::cerr << "[logic] Skipping duplicate logic item id '" << script.id << "'.\n";
                return;
            }
            script.name = trim_copy(json_get_string_loose(js, "name", script.id));
            if (script.name.empty()) script.name = script.id;
            script.enabled = json_get_bool_loose(js, "enabled", false);
            script.interval_ms = std::max(0, json_get_int_loose(js, "interval_ms", 0));
            script.engine = trim_copy(json_get_string_loose(js, "engine", std::string("javascript")));
            if (script.engine.empty()) script.engine = "javascript";
            if (kind == "block") {
                if (!js.contains("setup_source") || !js["setup_source"].is_string()) {
                    throw std::runtime_error("Block '" + script.id + "' requires string field 'setup_source'.");
                }
                if (!js.contains("loop_source") || !js["loop_source"].is_string()) {
                    throw std::runtime_error("Block '" + script.id + "' requires string field 'loop_source'.");
                }
                script.setup_source = json_get_string_loose(js, "setup_source", std::string{});
                script.loop_source = json_get_string_loose(js, "loop_source", std::string{});
            } else {
                if (!js.contains("source") || !js["source"].is_string()) {
                    throw std::runtime_error("Script '" + script.id + "' requires string field 'source'.");
                }
                script.source = json_get_string_loose(js, "source", std::string{});
            }
            auto prevIt = previousById.find(script.id);
            if (prevIt != previousById.end()) {
                script.last_run_ms = prevIt->second.last_run_ms;
                script.last_run_duration_ms = prevIt->second.last_run_duration_ms;
                script.last_run_ok = prevIt->second.last_run_ok;
                script.runs_total = prevIt->second.runs_total;
                script.failures_total = prevIt->second.failures_total;
                script.referenced_tags = prevIt->second.referenced_tags;
                script.missing_tags = prevIt->second.missing_tags;
                script.evaluated_reads = prevIt->second.evaluated_reads;
                script.memory_writes = prevIt->second.memory_writes;
                script.variables = prevIt->second.variables;
                script.read_preview = prevIt->second.read_preview;
                script.write_preview = prevIt->second.write_preview;
                script.variable_preview = prevIt->second.variable_preview;
                script.last_error = prevIt->second.last_error;
                const bool same_body = (script.kind == "script")
                    ? (script.source == prevIt->second.source)
                    : (script.setup_source == prevIt->second.setup_source &&
                       script.loop_source == prevIt->second.loop_source);
                if (same_body) {
                    script.setup_initialized = prevIt->second.setup_initialized;
                    script.retained_vars = prevIt->second.retained_vars;
                } else {
                    script.setup_initialized = false;
                    script.retained_vars.clear();
                }
            }
            next.scripts.push_back(std::move(script));
        };
        for (const auto &js : scripts) load_item(js, "script");
        for (const auto &js : blocks) load_item(js, "block");

        next.last_load_duration_ms = steady_elapsed_ms(started);
        const size_t scriptCount = next.scripts.size();
        {
            std::lock_guard<std::mutex> lock(g_logicMutex);
            g_logicState = std::move(next);
        }
        std::cout << "[logic] Loaded " << scriptCount
                  << " script definition(s) from " << path
                  << " (validation mode).\n";
        return true;
    } catch (const std::exception &ex) {
        next.config_loaded = false;
        next.last_load_ok = false;
        next.last_error = ex.what();
        next.last_load_duration_ms = steady_elapsed_ms(started);
        {
            std::lock_guard<std::mutex> lock(g_logicMutex);
            g_logicState = std::move(next);
        }
        std::cerr << "[logic] Error loading logic.json: " << ex.what() << "\n";
        return false;
    }
}

static bool validate_logic_source_text(const std::string &source, std::string &errorOut) {
    enum class State {
        Normal,
        SingleQuote,
        DoubleQuote,
        TemplateString,
        Escape,
        LineComment,
        BlockComment
    };

    State state = State::Normal;
    State returnState = State::Normal;
    std::vector<char> stack;
    int line = 1;
    int col = 0;

    auto fail = [&](const std::string &msg) {
        std::ostringstream oss;
        oss << msg << " at line " << line << ", column " << col << ".";
        errorOut = oss.str();
        return false;
    };

    for (size_t i = 0; i < source.size(); ++i) {
        const char ch = source[i];
        if (ch == '\n') {
            ++line;
            col = 0;
        } else {
            ++col;
        }

        switch (state) {
            case State::Normal:
                if (ch == '/' && i + 1 < source.size() && source[i + 1] == '/') {
                    state = State::LineComment;
                    ++i;
                    ++col;
                } else if (ch == '/' && i + 1 < source.size() && source[i + 1] == '*') {
                    state = State::BlockComment;
                    ++i;
                    ++col;
                } else if (ch == '\'') {
                    state = State::SingleQuote;
                } else if (ch == '"') {
                    state = State::DoubleQuote;
                } else if (ch == '`') {
                    state = State::TemplateString;
                } else if (ch == '(' || ch == '[' || ch == '{') {
                    stack.push_back(ch);
                } else if (ch == ')' || ch == ']' || ch == '}') {
                    if (stack.empty()) return fail(std::string("Unexpected '") + ch + "'");
                    const char open = stack.back();
                    const bool ok =
                        (open == '(' && ch == ')') ||
                        (open == '[' && ch == ']') ||
                        (open == '{' && ch == '}');
                    if (!ok) return fail(std::string("Mismatched '") + ch + "'");
                    stack.pop_back();
                }
                break;

            case State::SingleQuote:
                if (ch == '\\') {
                    returnState = state;
                    state = State::Escape;
                } else if (ch == '\'') {
                    state = State::Normal;
                } else if (ch == '\n') {
                    return fail("Unterminated single-quoted string");
                }
                break;

            case State::DoubleQuote:
                if (ch == '\\') {
                    returnState = state;
                    state = State::Escape;
                } else if (ch == '"') {
                    state = State::Normal;
                } else if (ch == '\n') {
                    return fail("Unterminated double-quoted string");
                }
                break;

            case State::TemplateString:
                if (ch == '\\') {
                    returnState = state;
                    state = State::Escape;
                } else if (ch == '`') {
                    state = State::Normal;
                }
                break;

            case State::Escape:
                state = returnState;
                break;

            case State::LineComment:
                if (ch == '\n') {
                    state = State::Normal;
                }
                break;

            case State::BlockComment:
                if (ch == '*' && i + 1 < source.size() && source[i + 1] == '/') {
                    state = State::Normal;
                    ++i;
                    ++col;
                }
                break;
        }
    }

    if (state == State::SingleQuote) {
        errorOut = "Unterminated single-quoted string.";
        return false;
    }
    if (state == State::DoubleQuote) {
        errorOut = "Unterminated double-quoted string.";
        return false;
    }
    if (state == State::TemplateString) {
        errorOut = "Unterminated template string.";
        return false;
    }
    if (state == State::BlockComment) {
        errorOut = "Unterminated block comment.";
        return false;
    }
    if (!stack.empty()) {
        errorOut = std::string("Unclosed '") + stack.back() + "'.";
        return false;
    }
    errorOut.clear();
    return true;
}

static std::string strip_logic_comments(const std::string &source) {
    enum class State {
        Normal,
        SingleQuote,
        DoubleQuote,
        TemplateString,
        Escape,
        LineComment,
        BlockComment
    };

    std::string out = source;
    State state = State::Normal;
    State returnState = State::Normal;

    for (size_t i = 0; i < out.size(); ++i) {
        const char ch = out[i];
        const char next = (i + 1 < out.size()) ? out[i + 1] : '\0';

        switch (state) {
            case State::Normal:
                if (ch == '/' && next == '/') {
                    out[i] = ' ';
                    out[i + 1] = ' ';
                    state = State::LineComment;
                    ++i;
                } else if (ch == '/' && next == '*') {
                    out[i] = ' ';
                    out[i + 1] = ' ';
                    state = State::BlockComment;
                    ++i;
                } else if (ch == '\'') {
                    state = State::SingleQuote;
                } else if (ch == '"') {
                    state = State::DoubleQuote;
                } else if (ch == '`') {
                    state = State::TemplateString;
                }
                break;

            case State::SingleQuote:
                if (ch == '\\') {
                    returnState = state;
                    state = State::Escape;
                } else if (ch == '\'') {
                    state = State::Normal;
                }
                break;

            case State::DoubleQuote:
                if (ch == '\\') {
                    returnState = state;
                    state = State::Escape;
                } else if (ch == '"') {
                    state = State::Normal;
                }
                break;

            case State::TemplateString:
                if (ch == '\\') {
                    returnState = state;
                    state = State::Escape;
                } else if (ch == '`') {
                    state = State::Normal;
                }
                break;

            case State::Escape:
                state = returnState;
                break;

            case State::LineComment:
                if (ch == '\n') {
                    state = State::Normal;
                } else {
                    out[i] = ' ';
                }
                break;

            case State::BlockComment:
                if (ch == '*' && next == '/') {
                    out[i] = ' ';
                    out[i + 1] = ' ';
                    state = State::Normal;
                    ++i;
                } else if (ch != '\n') {
                    out[i] = ' ';
                }
                break;
        }
    }

    return out;
}

struct LogicReferenceValidation {
    int referenced_tags = 0;
    int missing_tags = 0;
    int evaluated_reads = 0;
    int memory_writes = 0;
    int variables = 0;
    std::string read_preview;
    std::string write_preview;
    std::string variable_preview;
    std::string error;
};

static LogicReferenceValidation validate_logic_read_references(
    const std::string &source,
    const std::set<std::string> &tagKeys,
    const std::set<std::string> &systemTagNames,
    const std::unordered_map<std::string, TagSnapshot> &tagSnapshots,
    const std::unordered_map<std::string, SystemTagDef> &systemSnapshots)
{
    LogicReferenceValidation out;
    static const std::regex callRe(
        R"(\b(tag|quality|hasTag)\s*\(\s*(['"])([^'"]+)\2\s*,\s*(['"])([^'"]+)\4\s*\))"
    );
    std::sregex_iterator it(source.begin(), source.end(), callRe);
    std::sregex_iterator end;
    std::vector<std::string> missing;
    for (; it != end; ++it) {
        const std::string conn = (*it)[3].str();
        const std::string name = (*it)[5].str();
        ++out.referenced_tags;
        bool found = false;
        if (conn == "_system") {
            found = systemTagNames.count(name) > 0;
        } else {
            found = tagKeys.count(make_tag_key(conn, name)) > 0;
        }
        if (!found) {
            ++out.missing_tags;
            if (missing.size() < 5) missing.push_back(conn + ":" + name);
            continue;
        }

        if (out.evaluated_reads < 10) {
            const std::string func = (*it)[1].str();
            std::string rendered;
            if (func == "hasTag") {
                rendered = "true";
            } else if (conn == "_system") {
                auto sit = systemSnapshots.find(name);
                if (sit != systemSnapshots.end()) {
                    if (func == "quality") rendered = "1";
                    else rendered = sit->second.value.is_string() ? sit->second.value.get<std::string>() : sit->second.value.dump();
                }
            } else {
                auto tit = tagSnapshots.find(make_tag_key(conn, name));
                if (tit != tagSnapshots.end()) {
                    if (func == "quality") rendered = std::to_string(tit->second.quality);
                    else rendered = snapshot_value_to_string(tit->second);
                }
            }
            if (!rendered.empty()) {
                if (!out.read_preview.empty()) out.read_preview += "; ";
                out.read_preview += func + "(" + conn + ":" + name + ")=" + rendered;
                ++out.evaluated_reads;
            }
        }
    }
    if (!missing.empty()) {
        std::ostringstream oss;
        oss << "Missing tag reference";
        if (missing.size() != 1 || out.missing_tags > 1) oss << "s";
        oss << ": ";
        for (size_t i = 0; i < missing.size(); ++i) {
            if (i) oss << ", ";
            oss << missing[i];
        }
        if (out.missing_tags > static_cast<int>(missing.size())) {
            oss << ", +" << (out.missing_tags - static_cast<int>(missing.size())) << " more";
        }
        out.error = oss.str();
    }
    return out;
}

static bool logic_string_to_double(const std::string &s, double &out);

static bool parse_logic_literal_value(std::string raw, std::string &valueOut, std::string &errorOut) {
    raw = trim_copy(raw);
    if (raw.empty()) {
        errorOut = "setTag value is empty.";
        return false;
    }
    if ((raw.front() == '"' && raw.back() == '"') ||
        (raw.front() == '\'' && raw.back() == '\'')) {
        valueOut.clear();
        bool escaped = false;
        for (size_t i = 1; i + 1 < raw.size(); ++i) {
            char ch = raw[i];
            if (escaped) {
                switch (ch) {
                    case 'n': valueOut.push_back('\n'); break;
                    case 'r': valueOut.push_back('\r'); break;
                    case 't': valueOut.push_back('\t'); break;
                    default: valueOut.push_back(ch); break;
                }
                escaped = false;
            } else if (ch == '\\') {
                escaped = true;
            } else {
                valueOut.push_back(ch);
            }
        }
        if (escaped) valueOut.push_back('\\');
        return true;
    }
    const std::string lower = to_lower_copy(raw);
    if (lower == "true" || lower == "false" || lower == "on" || lower == "off" ||
        lower == "yes" || lower == "no" || lower == "null") {
        valueOut = lower == "null" ? std::string{} : lower;
        return true;
    }
    double literalNumber = 0.0;
    if (logic_string_to_double(raw, literalNumber)) {
        valueOut = raw;
        return true;
    }
    errorOut = "setTag value must be a simple literal for now.";
    return false;
}

static bool is_logic_identifier(const std::string &s) {
    if (s.empty()) return false;
    const unsigned char first = static_cast<unsigned char>(s.front());
    if (!(std::isalpha(first) || s.front() == '_')) return false;
    for (char ch : s) {
        const unsigned char c = static_cast<unsigned char>(ch);
        if (!(std::isalnum(c) || ch == '_')) return false;
    }
    return true;
}

static bool evaluate_logic_helper_call(
    const std::string &expr,
    const std::set<std::string> &tagKeys,
    const std::set<std::string> &systemTagNames,
    const std::unordered_map<std::string, TagSnapshot> &tagSnapshots,
    const std::unordered_map<std::string, SystemTagDef> &systemSnapshots,
    std::string &valueOut,
    std::string &errorOut)
{
    static const std::regex exactCallRe(
        R"(^\s*(tag|quality|hasTag)\s*\(\s*(['"])([^'"]+)\2\s*,\s*(['"])([^'"]+)\4\s*\)\s*$)"
    );
    std::smatch m;
    if (!std::regex_match(expr, m, exactCallRe)) return false;

    const std::string func = m[1].str();
    const std::string conn = m[3].str();
    const std::string name = m[5].str();
    const bool found = (conn == "_system")
        ? (systemTagNames.count(name) > 0)
        : (tagKeys.count(make_tag_key(conn, name)) > 0);

    if (func == "hasTag") {
        valueOut = found ? "true" : "false";
        errorOut.clear();
        return true;
    }
    if (!found) {
        errorOut = "Missing tag reference: " + conn + ":" + name;
        return true;
    }
    if (conn == "_system") {
        auto sit = systemSnapshots.find(name);
        if (sit == systemSnapshots.end()) {
            errorOut = "System tag has no current value: " + name;
            return true;
        }
        valueOut = (func == "quality")
            ? std::string("1")
            : (sit->second.value.is_string() ? sit->second.value.get<std::string>() : sit->second.value.dump());
        errorOut.clear();
        return true;
    }
    auto tit = tagSnapshots.find(make_tag_key(conn, name));
    if (tit == tagSnapshots.end()) {
        TagSnapshot live;
        if (logic_lookup_live_snapshot(make_tag_key(conn, name), live)) {
            valueOut = (func == "quality")
                ? std::to_string(live.quality)
                : snapshot_value_to_string(live);
            errorOut.clear();
            return true;
        }
        if (func == "quality") {
            valueOut = "0";
            errorOut.clear();
            return true;
        }
        // Known tag but no snapshot yet: return empty string so callers can
        // use defaults (for example json(payload, path, default)).
        valueOut.clear();
        errorOut.clear();
        return true;
    }
    valueOut = (func == "quality")
        ? std::to_string(tit->second.quality)
        : snapshot_value_to_string(tit->second);
    errorOut.clear();
    return true;
}

struct LogicExprValue {
    enum class Kind { Number, Bool, String };
    Kind kind = Kind::Number;
    double number = 0.0;
    bool boolean = false;
    std::string text;
};

static bool logic_string_to_double(const std::string &s, double &out) {
    std::string v = trim_copy(s);
    if (v.empty()) return false;
    if (v.size() > 2 && v[0] == '0' && (v[1] == 'x' || v[1] == 'X')) {
        char *hexEnd = nullptr;
        errno = 0;
        unsigned long long n = std::strtoull(v.c_str() + 2, &hexEnd, 16);
        if (hexEnd && *hexEnd == '\0' && errno != ERANGE) {
            out = static_cast<double>(n);
            return true;
        }
    }
    char *end = nullptr;
    errno = 0;
    double d = std::strtod(v.c_str(), &end);
    if (!end || *end != '\0' || errno == ERANGE) return false;
    out = d;
    return true;
}

static bool logic_string_to_bool(const std::string &s, bool &out) {
    const std::string v = to_lower_copy(trim_copy(s));
    if (v == "true" || v == "1" || v == "on" || v == "yes") {
        out = true;
        return true;
    }
    if (v == "false" || v == "0" || v == "off" || v == "no") {
        out = false;
        return true;
    }
    return false;
}

static std::string logic_format_number(double v) {
    if (std::isfinite(v) && std::fabs(v - std::round(v)) < 1e-9) {
        std::ostringstream oss;
        oss << static_cast<int64_t>(std::llround(v));
        return oss.str();
    }
    std::ostringstream oss;
    oss << std::setprecision(12) << v;
    return oss.str();
}

class LogicExpressionParser {
public:
    LogicExpressionParser(const std::string &expr,
                          const std::unordered_map<std::string, std::string> &vars,
                          const std::set<std::string> &keys,
                          const std::set<std::string> &systemNames,
                          const std::unordered_map<std::string, TagSnapshot> &snapshots,
                          const std::unordered_map<std::string, SystemTagDef> &systemDefs)
        : text(expr),
          variables(vars),
          tagKeys(keys),
          systemTagNames(systemNames),
          tagSnapshots(snapshots),
          systemSnapshots(systemDefs) {}

    bool parse(LogicExprValue &out, std::string &err) {
        error.clear();
        pos = 0;
        out = parse_or();
        skip_ws();
        if (error.empty() && pos != text.size()) {
            error = std::string("Unexpected token near '") + text.substr(pos, std::min<size_t>(16, text.size() - pos)) + "'";
        }
        err = error;
        return error.empty();
    }

private:
    const std::string &text;
    const std::unordered_map<std::string, std::string> &variables;
    const std::set<std::string> &tagKeys;
    const std::set<std::string> &systemTagNames;
    const std::unordered_map<std::string, TagSnapshot> &tagSnapshots;
    const std::unordered_map<std::string, SystemTagDef> &systemSnapshots;
    size_t pos = 0;
    std::string error;

    void skip_ws() {
        while (pos < text.size() && std::isspace(static_cast<unsigned char>(text[pos]))) ++pos;
    }

    bool consume(const std::string &tok) {
        skip_ws();
        if (text.compare(pos, tok.size(), tok) == 0) {
            pos += tok.size();
            return true;
        }
        return false;
    }

    LogicExprValue make_num(double v) {
        LogicExprValue out;
        out.kind = LogicExprValue::Kind::Number;
        out.number = v;
        out.boolean = std::fabs(v) > 1e-12;
        out.text = logic_format_number(v);
        return out;
    }

    LogicExprValue make_bool(bool v) {
        LogicExprValue out;
        out.kind = LogicExprValue::Kind::Bool;
        out.boolean = v;
        out.number = v ? 1.0 : 0.0;
        out.text = v ? "true" : "false";
        return out;
    }

    LogicExprValue make_string(std::string v) {
        LogicExprValue out;
        out.kind = LogicExprValue::Kind::String;
        out.text = std::move(v);
        double d = 0.0;
        bool b = false;
        if (logic_string_to_double(out.text, d)) {
            out.number = d;
            out.boolean = std::fabs(d) > 1e-12;
        } else if (logic_string_to_bool(out.text, b)) {
            out.number = b ? 1.0 : 0.0;
            out.boolean = b;
        }
        return out;
    }

    bool as_bool(const LogicExprValue &v) {
        if (v.kind == LogicExprValue::Kind::String) {
            bool b = false;
            if (logic_string_to_bool(v.text, b)) return b;
            double d = 0.0;
            if (logic_string_to_double(v.text, d)) return std::fabs(d) > 1e-12;
            return !v.text.empty();
        }
        return v.kind == LogicExprValue::Kind::Bool ? v.boolean : (std::fabs(v.number) > 1e-12);
    }

    bool as_number(const LogicExprValue &v, double &out) {
        if (v.kind == LogicExprValue::Kind::String) {
            if (logic_string_to_double(v.text, out)) return true;
            error = "Expected numeric value.";
            return false;
        }
        if (v.kind != LogicExprValue::Kind::Number) {
            error = "Expected numeric value.";
            return false;
        }
        out = v.number;
        return true;
    }

    bool as_string_arg(const LogicExprValue &v, std::string &out) {
        if (v.kind != LogicExprValue::Kind::String) {
            error = "Expected string argument.";
            return false;
        }
        out = v.text;
        return true;
    }

    std::string as_text(const LogicExprValue &v) {
        if (v.kind == LogicExprValue::Kind::String) return v.text;
        if (v.kind == LogicExprValue::Kind::Bool) return v.boolean ? "true" : "false";
        return logic_format_number(v.number);
    }

    LogicExprValue value_from_text(const std::string &value) {
        double d = 0.0;
        if (logic_string_to_double(value, d)) return make_num(d);
        bool b = false;
        if (logic_string_to_bool(value, b)) return make_bool(b);
        return make_string(value);
    }

    LogicExprValue value_from_json(const json &value) {
        if (value.is_boolean()) return make_bool(value.get<bool>());
        if (value.is_number()) return make_num(value.get<double>());
        if (value.is_string()) return value_from_text(value.get<std::string>());
        if (value.is_null()) return make_string({});
        return make_string(value.dump());
    }

    json value_to_json(const LogicExprValue &value) {
        if (value.kind == LogicExprValue::Kind::Bool) return value.boolean;
        if (value.kind == LogicExprValue::Kind::Number) return value.number;
        return value.text;
    }

    bool json_path_lookup(const json &root, const std::string &path, json &valueOut) {
        const json *cur = &root;
        if (path.empty()) {
            valueOut = *cur;
            return true;
        }
        size_t start = 0;
        while (start <= path.size()) {
            const size_t dot = path.find('.', start);
            const std::string part = path.substr(start, dot == std::string::npos ? std::string::npos : dot - start);
            if (part.empty()) return false;
            if (cur->is_object()) {
                auto it = cur->find(part);
                if (it == cur->end()) return false;
                cur = &(*it);
            } else if (cur->is_array()) {
                char *end = nullptr;
                errno = 0;
                const unsigned long idx = std::strtoul(part.c_str(), &end, 10);
                if (!end || *end != '\0' || errno == ERANGE || idx >= cur->size()) return false;
                cur = &((*cur)[idx]);
            } else {
                return false;
            }
            if (dot == std::string::npos) break;
            start = dot + 1;
        }
        valueOut = *cur;
        return true;
    }

    bool collect_numbers(const std::string &func, const std::vector<LogicExprValue> &args, std::vector<double> &nums) {
        nums.clear();
        nums.reserve(args.size());
        for (const auto &arg : args) {
            double n = 0.0;
            if (!as_number(arg, n)) {
                error = func + " expects numeric arguments.";
                return false;
            }
            nums.push_back(n);
        }
        return true;
    }

    bool as_uint64(const LogicExprValue &value, const std::string &func, uint64_t &out) {
        double n = 0.0;
        if (!as_number(value, n)) {
            error = func + " expects numeric arguments.";
            return false;
        }
        if (!std::isfinite(n) || n < 0.0 || n > static_cast<double>(std::numeric_limits<uint64_t>::max())) {
            error = func + " value is outside the supported unsigned integer range.";
            return false;
        }
        out = static_cast<uint64_t>(std::floor(n + 0.5));
        return true;
    }

    bool as_bit_index(const LogicExprValue &value, const std::string &func, int &out) {
        uint64_t n = 0;
        if (!as_uint64(value, func, n)) return false;
        if (n > 63) {
            error = func + " bit number must be between 0 and 63.";
            return false;
        }
        out = static_cast<int>(n);
        return true;
    }

    LogicExprValue evaluate_function(const std::string &name, const std::vector<LogicExprValue> &args) {
        const std::string func = to_lower_copy(name);
        std::vector<double> nums;

        if (func == "tag" || func == "quality" || func == "hastag") {
            if (args.size() != 2) {
                error = name + " expects 2 arguments.";
                return make_num(0.0);
            }
            std::string conn;
            std::string tagName;
            if (!as_string_arg(args[0], conn) || !as_string_arg(args[1], tagName)) return make_num(0.0);
            const bool found = (conn == "_system")
                ? (systemTagNames.count(tagName) > 0)
                : (tagKeys.count(make_tag_key(conn, tagName)) > 0);
            if (func == "hastag") return make_bool(found);
            if (!found) {
                error = "Missing tag reference: " + conn + ":" + tagName;
                return make_num(0.0);
            }
            if (conn == "_system") {
                auto sit = systemSnapshots.find(tagName);
                if (sit == systemSnapshots.end()) {
                    error = "System tag has no current value: " + tagName;
                    return make_num(0.0);
                }
                if (func == "quality") return make_num(1.0);
                const std::string value = sit->second.value.is_string() ? sit->second.value.get<std::string>() : sit->second.value.dump();
                return value_from_text(value);
            }
            auto tit = tagSnapshots.find(make_tag_key(conn, tagName));
            if (tit == tagSnapshots.end()) {
                TagSnapshot live;
                if (logic_lookup_live_snapshot(make_tag_key(conn, tagName), live)) {
                    if (func == "quality") return make_num(static_cast<double>(live.quality));
                    return value_from_text(snapshot_value_to_string(live));
                }
                if (func == "quality") return make_num(0.0);
                // Known tag but no snapshot yet: return empty string so
                // expression helpers can apply defaults.
                return make_string({});
            }
            if (func == "quality") return make_num(static_cast<double>(tit->second.quality));
            return value_from_text(snapshot_value_to_string(tit->second));
        }

        if (func == "json") {
            if (args.size() != 2 && args.size() != 3) {
                error = "json expects 2 or 3 arguments.";
                return make_num(0.0);
            }
            const std::string payload = as_text(args[0]);
            std::string path;
            if (!as_string_arg(args[1], path)) return make_num(0.0);
            try {
                const json parsed = json::parse(payload);
                json found;
                if (json_path_lookup(parsed, path, found)) return value_from_json(found);
                if (args.size() == 3) return args[2];
                error = "JSON path not found: " + path;
                return make_num(0.0);
            } catch (const std::exception &ex) {
                if (args.size() == 3) return args[2];
                error = std::string("Invalid JSON: ") + ex.what();
                return make_num(0.0);
            }
        }

        if (func == "hasjson") {
            if (args.size() != 2) {
                error = "hasJson expects 2 arguments.";
                return make_num(0.0);
            }
            const std::string payload = as_text(args[0]);
            std::string path;
            if (!as_string_arg(args[1], path)) return make_num(0.0);
            try {
                const json parsed = json::parse(payload);
                json found;
                return make_bool(json_path_lookup(parsed, path, found));
            } catch (...) {
                return make_bool(false);
            }
        }

        if (func == "jsonobj") {
            if (args.empty() || (args.size() % 2) != 0) {
                error = "jsonObj expects key/value argument pairs.";
                return make_num(0.0);
            }
            json out = json::object();
            for (size_t i = 0; i < args.size(); i += 2) {
                std::string key;
                if (!as_string_arg(args[i], key)) return make_num(0.0);
                out[key] = value_to_json(args[i + 1]);
            }
            return make_string(out.dump());
        }

        if (func == "jsonset") {
            if (args.size() != 3) {
                error = "jsonSet expects 3 arguments: jsonSet(base, key, value).";
                return make_num(0.0);
            }
            std::string key;
            if (!as_string_arg(args[1], key)) return make_num(0.0);

            json out = json::object();
            const std::string base = trim_copy(as_text(args[0]));
            if (!base.empty()) {
                try {
                    out = json::parse(base);
                } catch (...) {
                    // Treat invalid/partial base as empty object for
                    // incremental script construction.
                    out = json::object();
                }
            }
            if (!out.is_object()) {
                error = "jsonSet base must be a JSON object string.";
                return make_num(0.0);
            }
            out[key] = value_to_json(args[2]);
            return make_string(out.dump());
        }

        if (func == "jsonarray") {
            json out = json::array();
            for (const auto &arg : args) out.push_back(value_to_json(arg));
            return make_string(out.dump());
        }

        if (func == "str") {
            if (args.size() != 1) {
                error = "str expects 1 argument.";
                return make_num(0.0);
            }
            return make_string(as_text(args[0]));
        }

        if (func == "num" || func == "number") {
            if (args.size() != 1 && args.size() != 2) {
                error = name + " expects 1 or 2 arguments.";
                return make_num(0.0);
            }
            double n = 0.0;
            if (logic_string_to_double(as_text(args[0]), n)) return make_num(n);
            if (args.size() == 2) {
                if (as_number(args[1], n)) return make_num(n);
                return make_num(0.0);
            }
            error = "Cannot convert value to number.";
            return make_num(0.0);
        }

        if (func == "bool") {
            if (args.size() != 1 && args.size() != 2) {
                error = "bool expects 1 or 2 arguments.";
                return make_num(0.0);
            }
            bool b = false;
            if (logic_string_to_bool(as_text(args[0]), b)) return make_bool(b);
            if (args.size() == 2) return make_bool(as_bool(args[1]));
            error = "Cannot convert value to boolean.";
            return make_num(0.0);
        }

        if (func == "concat") {
            if (args.empty()) {
                error = "concat expects at least 1 argument.";
                return make_num(0.0);
            }
            std::string out;
            for (const auto &arg : args) out += as_text(arg);
            return make_string(out);
        }

        if (func == "lower" || func == "upper" || func == "trim") {
            if (args.size() != 1) {
                error = name + " expects 1 argument.";
                return make_num(0.0);
            }
            std::string value = as_text(args[0]);
            if (func == "lower") return make_string(to_lower_copy(value));
            if (func == "upper") {
                std::transform(value.begin(), value.end(), value.begin(), [](unsigned char c) { return static_cast<char>(std::toupper(c)); });
                return make_string(value);
            }
            return make_string(trim_copy(value));
        }

        if (func == "contains" || func == "startswith" || func == "endswith") {
            if (args.size() != 2) {
                error = name + " expects 2 arguments.";
                return make_num(0.0);
            }
            const std::string value = as_text(args[0]);
            const std::string needle = as_text(args[1]);
            if (func == "contains") return make_bool(value.find(needle) != std::string::npos);
            if (func == "startswith") return make_bool(value.rfind(needle, 0) == 0);
            return make_bool(value.size() >= needle.size() && value.compare(value.size() - needle.size(), needle.size(), needle) == 0);
        }

        if (func == "bit") {
            if (args.size() != 2) {
                error = "bit expects 2 arguments.";
                return make_num(0.0);
            }
            uint64_t value = 0;
            int bitNumber = 0;
            if (!as_uint64(args[0], func, value) || !as_bit_index(args[1], func, bitNumber)) return make_num(0.0);
            return make_bool(((value >> bitNumber) & 1ULL) != 0ULL);
        }

        if (func == "bits") {
            if (args.size() != 2) {
                error = "bits expects 2 arguments.";
                return make_num(0.0);
            }
            uint64_t value = 0;
            uint64_t mask = 0;
            if (!as_uint64(args[0], func, value) || !as_uint64(args[1], func, mask)) return make_num(0.0);
            return make_num(static_cast<double>(value & mask));
        }

        if (func == "map") {
            if (args.size() != 5) {
                error = "map expects 5 arguments.";
                return make_num(0.0);
            }
            if (!collect_numbers(func, args, nums)) return make_num(0.0);
            const double inSpan = nums[2] - nums[1];
            if (std::fabs(inSpan) < 1e-12) {
                error = "map input range cannot be zero.";
                return make_num(0.0);
            }
            return make_num(nums[3] + ((nums[0] - nums[1]) * (nums[4] - nums[3]) / inSpan));
        }

        if (func == "clamp") {
            if (args.size() != 3) {
                error = "clamp expects 3 arguments.";
                return make_num(0.0);
            }
            if (!collect_numbers(func, args, nums)) return make_num(0.0);
            const double lo = std::min(nums[1], nums[2]);
            const double hi = std::max(nums[1], nums[2]);
            return make_num(std::min(std::max(nums[0], lo), hi));
        }

        if (func == "round") {
            if (args.size() != 1 && args.size() != 2) {
                error = "round expects 1 or 2 arguments.";
                return make_num(0.0);
            }
            if (!collect_numbers(func, args, nums)) return make_num(0.0);
            if (args.size() == 1) return make_num(std::round(nums[0]));
            const double places = std::round(nums[1]);
            if (places < -12.0 || places > 12.0) {
                error = "round decimal places must be between -12 and 12.";
                return make_num(0.0);
            }
            const double scale = std::pow(10.0, places);
            if (std::fabs(scale) < 1e-12) return make_num(std::round(nums[0]));
            return make_num(std::round(nums[0] * scale) / scale);
        }

        if (func == "min" || func == "max") {
            if (args.size() < 2) {
                error = func + " expects at least 2 arguments.";
                return make_num(0.0);
            }
            if (!collect_numbers(func, args, nums)) return make_num(0.0);
            double result = nums.front();
            for (size_t i = 1; i < nums.size(); ++i) {
                result = (func == "min") ? std::min(result, nums[i]) : std::max(result, nums[i]);
            }
            return make_num(result);
        }

        error = "Unknown function '" + name + "'.";
        return make_num(0.0);
    }

    LogicExprValue parse_or() {
        LogicExprValue left = parse_and();
        while (error.empty()) {
            if (!consume("||")) break;
            LogicExprValue right = parse_and();
            left = make_bool(as_bool(left) || as_bool(right));
        }
        return left;
    }

    LogicExprValue parse_and() {
        LogicExprValue left = parse_equality();
        while (error.empty()) {
            if (!consume("&&")) break;
            LogicExprValue right = parse_equality();
            left = make_bool(as_bool(left) && as_bool(right));
        }
        return left;
    }

    LogicExprValue parse_equality() {
        LogicExprValue left = parse_relational();
        while (error.empty()) {
            if (consume("==")) {
                LogicExprValue right = parse_relational();
                left = make_bool(left.kind == LogicExprValue::Kind::String || right.kind == LogicExprValue::Kind::String
                    ? left.text == right.text
                    : left.kind == LogicExprValue::Kind::Bool || right.kind == LogicExprValue::Kind::Bool
                    ? as_bool(left) == as_bool(right)
                    : std::fabs(left.number - right.number) < 1e-9);
            } else if (consume("!=")) {
                LogicExprValue right = parse_relational();
                left = make_bool(left.kind == LogicExprValue::Kind::String || right.kind == LogicExprValue::Kind::String
                    ? left.text != right.text
                    : left.kind == LogicExprValue::Kind::Bool || right.kind == LogicExprValue::Kind::Bool
                    ? as_bool(left) != as_bool(right)
                    : std::fabs(left.number - right.number) >= 1e-9);
            } else {
                break;
            }
        }
        return left;
    }

    LogicExprValue parse_relational() {
        LogicExprValue left = parse_add();
        while (error.empty()) {
            if (consume("<=")) {
                LogicExprValue right = parse_add();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                left = make_bool(a <= b);
            } else if (consume(">=")) {
                LogicExprValue right = parse_add();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                left = make_bool(a >= b);
            } else if (consume("<")) {
                LogicExprValue right = parse_add();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                left = make_bool(a < b);
            } else if (consume(">")) {
                LogicExprValue right = parse_add();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                left = make_bool(a > b);
            } else {
                break;
            }
        }
        return left;
    }

    LogicExprValue parse_add() {
        LogicExprValue left = parse_mul();
        while (error.empty()) {
            if (consume("+")) {
                LogicExprValue right = parse_mul();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                left = make_num(a + b);
            } else if (consume("-")) {
                LogicExprValue right = parse_mul();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                left = make_num(a - b);
            } else {
                break;
            }
        }
        return left;
    }

    LogicExprValue parse_mul() {
        LogicExprValue left = parse_unary();
        while (error.empty()) {
            if (consume("*")) {
                LogicExprValue right = parse_unary();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                left = make_num(a * b);
            } else if (consume("/")) {
                LogicExprValue right = parse_unary();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                if (std::fabs(b) < 1e-12) {
                    error = "Division by zero.";
                    return left;
                }
                left = make_num(a / b);
            } else if (consume("%")) {
                LogicExprValue right = parse_unary();
                double a = 0.0, b = 0.0;
                if (!as_number(left, a) || !as_number(right, b)) return left;
                if (std::fabs(b) < 1e-12) {
                    error = "Modulo by zero.";
                    return left;
                }
                left = make_num(std::fmod(a, b));
            } else {
                break;
            }
        }
        return left;
    }

    LogicExprValue parse_unary() {
        if (consume("!")) {
            LogicExprValue v = parse_unary();
            return make_bool(!as_bool(v));
        }
        if (consume("-")) {
            LogicExprValue v = parse_unary();
            double n = 0.0;
            if (!as_number(v, n)) return v;
            return make_num(-n);
        }
        return parse_primary();
    }

    LogicExprValue parse_primary() {
        skip_ws();
        if (pos >= text.size()) {
            error = "Unexpected end of expression.";
            return make_num(0.0);
        }
        if (consume("(")) {
            LogicExprValue v = parse_or();
            if (error.empty() && !consume(")")) error = "Expected ')'.";
            return v;
        }

        const char ch = text[pos];
        if (ch == '"' || ch == '\'') {
            const char quote = ch;
            ++pos;
            std::string value;
            bool escaped = false;
            while (pos < text.size()) {
                const char c = text[pos++];
                if (escaped) {
                    switch (c) {
                        case 'n': value.push_back('\n'); break;
                        case 'r': value.push_back('\r'); break;
                        case 't': value.push_back('\t'); break;
                        default: value.push_back(c); break;
                    }
                    escaped = false;
                } else if (c == '\\') {
                    escaped = true;
                } else if (c == quote) {
                    return make_string(value);
                } else {
                    value.push_back(c);
                }
            }
            error = "Unterminated string literal.";
            return make_string({});
        }

        if (std::isdigit(static_cast<unsigned char>(ch)) || ch == '.') {
            if (ch == '0' && pos + 2 < text.size() && (text[pos + 1] == 'x' || text[pos + 1] == 'X')) {
                char *hexEnd = nullptr;
                errno = 0;
                const char *start = text.c_str() + pos + 2;
                unsigned long long n = std::strtoull(start, &hexEnd, 16);
                if (!hexEnd || hexEnd == start || errno == ERANGE) {
                    error = "Invalid hex number.";
                    return make_num(0.0);
                }
                pos += 2 + static_cast<size_t>(hexEnd - start);
                return make_num(static_cast<double>(n));
            }
            char *end = nullptr;
            errno = 0;
            const char *start = text.c_str() + pos;
            double d = std::strtod(start, &end);
            if (!end || end == start || errno == ERANGE) {
                error = "Invalid number.";
                return make_num(0.0);
            }
            pos += static_cast<size_t>(end - start);
            return make_num(d);
        }

        if (std::isalpha(static_cast<unsigned char>(ch)) || ch == '_') {
            const size_t start = pos;
            ++pos;
            while (pos < text.size()) {
                const unsigned char c = static_cast<unsigned char>(text[pos]);
                if (!(std::isalnum(c) || text[pos] == '_')) break;
                ++pos;
            }
            const std::string ident = text.substr(start, pos - start);
            const std::string lower = to_lower_copy(ident);
            skip_ws();
            if (consume("(")) {
                std::vector<LogicExprValue> args;
                skip_ws();
                if (!consume(")")) {
                    while (error.empty()) {
                        args.push_back(parse_or());
                        if (!error.empty()) break;
                        if (consume(")")) break;
                        if (!consume(",")) {
                            error = "Expected ',' or ')' in function call.";
                            break;
                        }
                    }
                }
                if (!error.empty()) return make_num(0.0);
                return evaluate_function(ident, args);
            }
            if (lower == "true") return make_bool(true);
            if (lower == "false") return make_bool(false);
            auto vit = variables.find(ident);
            if (vit == variables.end()) {
                error = "Unknown variable '" + ident + "'.";
                return make_num(0.0);
            }
            double d = 0.0;
            if (logic_string_to_double(vit->second, d)) return make_num(d);
            bool b = false;
            if (logic_string_to_bool(vit->second, b)) return make_bool(b);
            return make_string(vit->second);
        }

        error = std::string("Unexpected token '") + ch + "'.";
        return make_num(0.0);
    }
};

static bool evaluate_logic_expression_value(
    const std::string &expr,
    const std::unordered_map<std::string, std::string> &variables,
    const std::set<std::string> &tagKeys,
    const std::set<std::string> &systemTagNames,
    const std::unordered_map<std::string, TagSnapshot> &tagSnapshots,
    const std::unordered_map<std::string, SystemTagDef> &systemSnapshots,
    std::string &valueOut,
    std::string &errorOut)
{
    LogicExpressionParser parser(expr, variables, tagKeys, systemTagNames, tagSnapshots, systemSnapshots);
    LogicExprValue v;
    if (!parser.parse(v, errorOut)) return false;
    if (v.kind == LogicExprValue::Kind::String) valueOut = v.text;
    else if (v.kind == LogicExprValue::Kind::Bool) valueOut = v.boolean ? std::string("true") : std::string("false");
    else valueOut = logic_format_number(v.number);
    return true;
}

static bool logic_keyword_at(const std::string &source, size_t pos, const std::string &keyword);

static LogicReferenceValidation evaluate_logic_variables(
    const std::string &source,
    const std::set<std::string> &tagKeys,
    const std::set<std::string> &systemTagNames,
    const std::unordered_map<std::string, TagSnapshot> &tagSnapshots,
    const std::unordered_map<std::string, SystemTagDef> &systemSnapshots,
    std::unordered_map<std::string, std::string> &variables)
{
    LogicReferenceValidation out;
    static const std::regex assignRe(R"((?:\b(const|let)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([^;]+)\s*;)");
    std::sregex_iterator it(source.begin(), source.end(), assignRe);
    std::sregex_iterator end;
    std::vector<std::string> errors;

    for (; it != end; ++it) {
        const std::string declKw = trim_copy((*it)[1].str());
        const std::string name = (*it)[2].str();
        const std::string expr = trim_copy((*it)[3].str());
        if (expr.empty()) continue;
        if (!declKw.empty() && declKw != "const" && declKw != "let") continue;
        if (!expr.empty() && expr.front() == '=') continue; // guard malformed "=="
        std::string value;
        std::string err;
        if (evaluate_logic_helper_call(expr, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, value, err)) {
            if (!err.empty()) {
                if (errors.size() < 5) errors.push_back(name + ": " + err);
                continue;
            }
        } else if (is_logic_identifier(expr)) {
            auto vit = variables.find(expr);
            if (vit == variables.end()) {
                if (errors.size() < 5) errors.push_back(name + ": unknown variable '" + expr + "'");
                continue;
            }
            value = vit->second;
        } else if (!parse_logic_literal_value(expr, value, err)) {
            if (!evaluate_logic_expression_value(expr, variables, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, value, err)) {
                if (errors.size() < 5) errors.push_back(name + ": " + err);
                continue;
            }
        }
        variables[name] = value;
        if (out.variables < 10) {
            if (!out.variable_preview.empty()) out.variable_preview += "; ";
            out.variable_preview += name + "=" + value;
        }
        ++out.variables;
    }

    if (!errors.empty()) {
        std::ostringstream oss;
        oss << "Variable error";
        if (errors.size() != 1) oss << "s";
        oss << ": ";
        for (size_t i = 0; i < errors.size(); ++i) {
            if (i) oss << "; ";
            oss << errors[i];
        }
        out.error = oss.str();
    }
    return out;
}

static bool logic_find_matching_paren(const std::string &text, size_t openPos, size_t &closePos, std::string &errorOut) {
    int depth = 0;
    bool inSingle = false;
    bool inDouble = false;
    bool escaped = false;
    for (size_t i = openPos; i < text.size(); ++i) {
        const char ch = text[i];
        if (inSingle || inDouble) {
            if (escaped) {
                escaped = false;
            } else if (ch == '\\') {
                escaped = true;
            } else if ((inSingle && ch == '\'') || (inDouble && ch == '"')) {
                inSingle = false;
                inDouble = false;
            }
            continue;
        }
        if (ch == '\'') {
            inSingle = true;
            continue;
        }
        if (ch == '"') {
            inDouble = true;
            continue;
        }
        if (ch == '(') {
            ++depth;
        } else if (ch == ')') {
            --depth;
            if (depth == 0) {
                closePos = i;
                return true;
            }
        }
    }
    errorOut = "Missing ')' in setTag call.";
    return false;
}

static bool logic_split_args(const std::string &text, std::vector<std::string> &args, std::string &errorOut) {
    args.clear();
    size_t start = 0;
    int depth = 0;
    bool inSingle = false;
    bool inDouble = false;
    bool escaped = false;
    for (size_t i = 0; i < text.size(); ++i) {
        const char ch = text[i];
        if (inSingle || inDouble) {
            if (escaped) {
                escaped = false;
            } else if (ch == '\\') {
                escaped = true;
            } else if ((inSingle && ch == '\'') || (inDouble && ch == '"')) {
                inSingle = false;
                inDouble = false;
            }
            continue;
        }
        if (ch == '\'') {
            inSingle = true;
            continue;
        }
        if (ch == '"') {
            inDouble = true;
            continue;
        }
        if (ch == '(') {
            ++depth;
        } else if (ch == ')') {
            --depth;
            if (depth < 0) {
                errorOut = "Unexpected ')' in argument list.";
                return false;
            }
        } else if (ch == ',' && depth == 0) {
            args.push_back(trim_copy(text.substr(start, i - start)));
            start = i + 1;
        }
    }
    if (inSingle || inDouble) {
        errorOut = "Unterminated string literal in argument list.";
        return false;
    }
    if (depth != 0) {
        errorOut = "Unbalanced parentheses in argument list.";
        return false;
    }
    args.push_back(trim_copy(text.substr(start)));
    return true;
}

static bool logic_collect_settag_calls(const std::string &source,
                                       std::vector<std::array<std::string, 3>> &calls,
                                       std::string &errorOut) {
    calls.clear();
    size_t pos = 0;
    while (pos < source.size()) {
        size_t hit = source.find("setTag", pos);
        if (hit == std::string::npos) break;
        if (!logic_keyword_at(source, hit, "setTag")) {
            pos = hit + 6;
            continue;
        }
        size_t p = hit + 6;
        while (p < source.size() && std::isspace(static_cast<unsigned char>(source[p]))) ++p;
        if (p >= source.size() || source[p] != '(') {
            pos = hit + 6;
            continue;
        }
        size_t close = 0;
        if (!logic_find_matching_paren(source, p, close, errorOut)) return false;
        std::vector<std::string> args;
        if (!logic_split_args(source.substr(p + 1, close - p - 1), args, errorOut)) return false;
        if (args.size() != 3) {
            errorOut = "setTag expects 3 arguments.";
            return false;
        }
        calls.push_back({args[0], args[1], args[2]});
        pos = close + 1;
    }
    return true;
}

static LogicReferenceValidation apply_logic_memory_writes(
    const std::string &source,
    const std::unordered_map<std::string, std::string> &variables,
    const std::set<std::string> &tagKeys,
    const std::set<std::string> &systemTagNames,
    const std::unordered_map<std::string, TagSnapshot> &tagSnapshots,
    const std::unordered_map<std::string, SystemTagDef> &systemSnapshots,
    std::vector<DriverContext> &drivers,
    TagTable &tagTable,
    std::mutex &driverMutex,
    std::deque<UaUpdate> &uaQueue,
    std::deque<MqttPublishJob> &mqttQueue)
{
    LogicReferenceValidation out;
    std::vector<std::string> errors;
    std::vector<std::array<std::string, 3>> calls;
    std::string callError;
    if (!logic_collect_settag_calls(source, calls, callError)) {
        out.error = callError;
        return out;
    }

    for (const auto &call : calls) {
        std::string conn;
        std::string name;
        std::string argError;
        if (!parse_logic_literal_value(call[0], conn, argError)) {
            if (errors.size() < 5) errors.push_back("setTag connection must be a string literal.");
            continue;
        }
        if (!parse_logic_literal_value(call[1], name, argError)) {
            if (errors.size() < 5) errors.push_back("setTag tag name must be a string literal.");
            continue;
        }
        const std::string rawValue = call[2];
        if (conn == "_system") {
            if (errors.size() < 5) errors.push_back("setTag cannot write _system tags: " + conn + ":" + name);
            continue;
        }
        std::string valueText;
        std::string literalError;
        const std::string rawTrimmed = trim_copy(rawValue);
        if (is_logic_identifier(rawTrimmed)) {
            auto vit = variables.find(rawTrimmed);
            if (vit == variables.end()) {
                if (errors.size() < 5) errors.push_back(name + ": unknown variable '" + rawTrimmed + "'");
                continue;
            }
            valueText = vit->second;
        } else {
            if (!parse_logic_literal_value(rawValue, valueText, literalError)) {
                if (!evaluate_logic_expression_value(rawValue, variables, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, valueText, literalError)) {
                    if (errors.size() < 5) errors.push_back(name + ": " + literalError);
                    continue;
                }
            }
        }

        TagConfig cfg;
        bool found = false;
        const std::string key = make_tag_key(conn, name);
        TagSnapshot prev;
        bool hadPrev = false;
        {
            std::lock_guard<std::mutex> lock(driverMutex);
            for (const auto &driver : drivers) {
                if (driver.conn.id != conn) continue;
                for (const auto &tag : driver.tags) {
                    if (tag.cfg.logical_name == name) {
                        cfg = tag.cfg;
                        found = true;
                        break;
                    }
                }
                break;
            }
            auto prevIt = tagTable.find(key);
            if (prevIt != tagTable.end()) {
                prev = prevIt->second;
                hadPrev = true;
            }
        }
        if (!found) {
            const bool mqttDynamicAllowed =
                ((g_mqttKnownConnectionIds.count(conn) > 0) || mqtt_connection_known_from_inputs(conn)) &&
                !mqtt_is_subscription_tag_name(name);
            if (!mqttDynamicAllowed) {
                if (errors.size() < 5) errors.push_back("Tag not found: " + conn + ":" + name);
                continue;
            }

            if (!write_tag_by_name(drivers, conn, name, valueText, tagTable, driverMutex)) {
                if (errors.size() < 5) errors.push_back("Write failed: " + conn + ":" + name);
                continue;
            }

            TagSnapshot snap;
            {
                std::lock_guard<std::mutex> lock(driverMutex);
                auto it = tagTable.find(key);
                if (it == tagTable.end()) {
                    if (errors.size() < 5) errors.push_back("Write succeeded but tag snapshot missing: " + conn + ":" + name);
                    continue;
                }
                snap = it->second;
            }

            out.memory_writes += 1;
            if (out.memory_writes <= 10) {
                if (!out.write_preview.empty()) out.write_preview += "; ";
                out.write_preview += conn + ":" + name + "=" + valueText;
            }
            continue;
        }
        if (!cfg.writable) {
            if (errors.size() < 5) errors.push_back("Tag is not writable: " + conn + ":" + name);
            continue;
        }

        // Reuse the canonical write path (same behavior as POST /write).
        if (!write_tag_by_name(drivers, conn, name, valueText, tagTable, driverMutex)) {
            if (errors.size() < 5) errors.push_back("Write failed: " + conn + ":" + name);
            continue;
        }

        TagSnapshot snap;
        {
            std::lock_guard<std::mutex> lock(driverMutex);
            auto it = tagTable.find(key);
            if (it == tagTable.end()) {
                if (errors.size() < 5) errors.push_back("Write succeeded but tag snapshot missing: " + conn + ":" + name);
                continue;
            }
            snap = it->second;
        }

        if (ws_is_enabled() && (!hadPrev || !snapshot_values_equal(snap, prev))) {
            ws_notify_tag_update(snap, cfg);
        }
        evaluate_tag_alarms(conn, name, snap);
        uaQueue.push_back(UaUpdate{conn, name, snap.value});
        if (g_mqtt && g_mqttCfg.enabled && is_memory_tag(cfg) && g_mqttCfg.publish_memory_tags) {
            MqttPublishJob j;
            j.snap = snap;
            j.hadPrev = hadPrev;
            if (hadPrev) j.prev = prev;
            mqttQueue.push_back(std::move(j));
        }
        if (out.memory_writes < 10) {
            if (!out.write_preview.empty()) out.write_preview += "; ";
            out.write_preview += conn + ":" + name + "=" + snapshot_value_to_string(snap);
        }
        ++out.memory_writes;
    }

    if (!errors.empty()) {
        std::ostringstream oss;
        oss << "Memory write error";
        if (errors.size() != 1) oss << "s";
        oss << ": ";
        for (size_t i = 0; i < errors.size(); ++i) {
            if (i) oss << "; ";
            oss << errors[i];
        }
        out.error = oss.str();
    }
    return out;
}

struct LogicIfBlock {
    std::string condition;
    std::string body;
    std::string else_body;
    bool has_else = false;
    size_t start = 0;
    size_t end = 0;
};

static bool logic_keyword_at(const std::string &source, size_t pos, const std::string &keyword) {
    if (pos + keyword.size() > source.size()) return false;
    if (source.compare(pos, keyword.size(), keyword) != 0) return false;
    const bool beforeOk = (pos == 0) || !(std::isalnum(static_cast<unsigned char>(source[pos - 1])) || source[pos - 1] == '_');
    const size_t after = pos + keyword.size();
    const bool afterOk = (after >= source.size()) || !(std::isalnum(static_cast<unsigned char>(source[after])) || source[after] == '_');
    return beforeOk && afterOk;
}

static bool logic_contains_if_keyword(const std::string &source) {
    size_t pos = 0;
    while (pos < source.size()) {
        size_t hit = source.find("if", pos);
        if (hit == std::string::npos) return false;
        if (logic_keyword_at(source, hit, "if")) return true;
        pos = hit + 2;
    }
    return false;
}

static bool logic_find_matching_delim(const std::string &text,
                                      size_t openPos,
                                      char openCh,
                                      char closeCh,
                                      size_t &closePos,
                                      std::string &errorOut) {
    int depth = 0;
    bool inSingle = false;
    bool inDouble = false;
    bool inTemplate = false;
    bool escaped = false;
    bool inLineComment = false;
    bool inBlockComment = false;

    for (size_t i = openPos; i < text.size(); ++i) {
        const char ch = text[i];
        const char next = (i + 1 < text.size()) ? text[i + 1] : '\0';

        if (inLineComment) {
            if (ch == '\n') inLineComment = false;
            continue;
        }
        if (inBlockComment) {
            if (ch == '*' && next == '/') {
                inBlockComment = false;
                ++i;
            }
            continue;
        }
        if (inSingle || inDouble || inTemplate) {
            if (escaped) {
                escaped = false;
                continue;
            }
            if (ch == '\\') {
                escaped = true;
                continue;
            }
            if (inSingle && ch == '\'') inSingle = false;
            else if (inDouble && ch == '"') inDouble = false;
            else if (inTemplate && ch == '`') inTemplate = false;
            continue;
        }

        if (ch == '/' && next == '/') {
            inLineComment = true;
            ++i;
            continue;
        }
        if (ch == '/' && next == '*') {
            inBlockComment = true;
            ++i;
            continue;
        }
        if (ch == '\'') {
            inSingle = true;
            continue;
        }
        if (ch == '"') {
            inDouble = true;
            continue;
        }
        if (ch == '`') {
            inTemplate = true;
            continue;
        }
        if (ch == openCh) {
            ++depth;
        } else if (ch == closeCh) {
            --depth;
            if (depth == 0) {
                closePos = i;
                return true;
            }
        }
    }

    errorOut = std::string("Missing '") + closeCh + "' for if block.";
    return false;
}

static bool logic_collect_if_blocks(const std::string &source,
                                    std::vector<LogicIfBlock> &blocks,
                                    std::string &errorOut) {
    blocks.clear();
    size_t pos = 0;
    while (pos < source.size()) {
        size_t hit = source.find("if", pos);
        if (hit == std::string::npos) break;
        if (!logic_keyword_at(source, hit, "if")) {
            pos = hit + 2;
            continue;
        }

        const size_t after = hit + 2;
        size_t p = after;
        while (p < source.size() && std::isspace(static_cast<unsigned char>(source[p]))) ++p;
        if (p >= source.size() || source[p] != '(') {
            pos = after;
            continue;
        }
        size_t condEnd = 0;
        if (!logic_find_matching_delim(source, p, '(', ')', condEnd, errorOut)) return false;
        size_t b = condEnd + 1;
        while (b < source.size() && std::isspace(static_cast<unsigned char>(source[b]))) ++b;
        if (b >= source.size() || source[b] != '{') {
            errorOut = "Expected '{' after if condition.";
            return false;
        }
        size_t bodyEnd = 0;
        if (!logic_find_matching_delim(source, b, '{', '}', bodyEnd, errorOut)) return false;

        LogicIfBlock block;
        block.start = hit;
        block.end = bodyEnd + 1;
        block.condition = trim_copy(source.substr(p + 1, condEnd - p - 1));
        block.body = source.substr(b + 1, bodyEnd - b - 1);
        if (logic_contains_if_keyword(block.body)) {
            errorOut = "Nested if blocks are not supported.";
            return false;
        }

        size_t next = bodyEnd + 1;
        while (next < source.size() && std::isspace(static_cast<unsigned char>(source[next]))) ++next;
        if (logic_keyword_at(source, next, "else")) {
            size_t e = next + 4;
            while (e < source.size() && std::isspace(static_cast<unsigned char>(source[e]))) ++e;
            if (e >= source.size() || source[e] != '{') {
                errorOut = "Expected '{' after else.";
                return false;
            }
            size_t elseEnd = 0;
            if (!logic_find_matching_delim(source, e, '{', '}', elseEnd, errorOut)) return false;
            block.has_else = true;
            block.else_body = source.substr(e + 1, elseEnd - e - 1);
            if (logic_contains_if_keyword(block.else_body)) {
                errorOut = "Nested if blocks are not supported.";
                return false;
            }
            block.end = elseEnd + 1;
            next = elseEnd + 1;
        }
        blocks.push_back(std::move(block));
        pos = next;
    }
    return true;
}

static std::string logic_without_if_blocks(const std::string &source,
                                           const std::vector<LogicIfBlock> &blocks) {
    std::string out = source;
    for (const auto &block : blocks) {
        if (block.start >= out.size()) continue;
        const size_t end = std::min(block.end, out.size());
        for (size_t i = block.start; i < end; ++i) {
            if (out[i] != '\n') out[i] = ' ';
        }
    }
    return out;
}

static void logic_merge_result(LogicReferenceValidation &dst,
                               const LogicReferenceValidation &src) {
    dst.referenced_tags += src.referenced_tags;
    dst.missing_tags += src.missing_tags;
    dst.evaluated_reads += src.evaluated_reads;
    dst.memory_writes += src.memory_writes;
    dst.variables += src.variables;
    auto appendPreview = [](std::string &target, const std::string &value) {
        if (value.empty()) return;
        if (!target.empty()) target += "; ";
        target += value;
    };
    appendPreview(dst.read_preview, src.read_preview);
    appendPreview(dst.write_preview, src.write_preview);
    appendPreview(dst.variable_preview, src.variable_preview);
    if (dst.error.empty() && !src.error.empty()) dst.error = src.error;
}

static void logic_run_validation_cycle(const std::set<std::string> &tagKeys,
                                       const std::set<std::string> &systemTagNames,
                                       const std::unordered_map<std::string, TagSnapshot> &tagSnapshots,
                                       const std::unordered_map<std::string, SystemTagDef> &systemSnapshots,
                                       std::vector<DriverContext> *drivers,
                                       TagTable *tagTable,
                                       std::mutex *driverMutex,
                                       std::deque<UaUpdate> *uaQueue,
                                       std::deque<MqttPublishJob> *mqttQueue) {
    std::vector<size_t> due;
    {
        std::lock_guard<std::mutex> lock(g_logicMutex);
        const int64_t nowMs = system_wall_now_ms();
        for (size_t i = 0; i < g_logicState.scripts.size(); ++i) {
            auto &script = g_logicState.scripts[i];
            if (!script.enabled) continue;
            const int interval = std::max(1000, script.interval_ms);
            if (script.last_run_ms <= 0 || (nowMs - script.last_run_ms) >= interval) {
                due.push_back(i);
            }
        }
    }
    if (due.empty()) return;

    for (size_t idx : due) {
        const auto started = std::chrono::steady_clock::now();
        int64_t nowMs = system_wall_now_ms();
        std::string engine;
        std::string kind;
        std::string source;
        std::string setupSource;
        std::string loopSource;
        bool setupInitialized = false;
        std::unordered_map<std::string, std::string> retainedVars;
        {
            std::lock_guard<std::mutex> lock(g_logicMutex);
            if (idx >= g_logicState.scripts.size()) continue;
            engine = to_lower_copy(trim_copy(g_logicState.scripts[idx].engine));
            kind = trim_copy(g_logicState.scripts[idx].kind);
            source = g_logicState.scripts[idx].source;
            setupSource = g_logicState.scripts[idx].setup_source;
            loopSource = g_logicState.scripts[idx].loop_source;
            setupInitialized = g_logicState.scripts[idx].setup_initialized;
            retainedVars = g_logicState.scripts[idx].retained_vars;
        }

        bool ok = true;
        std::string err;
        LogicReferenceValidation refs;
        std::unordered_map<std::string, std::string> variables;
        if (engine != "javascript") {
            ok = false;
            err = "Unsupported logic engine '" + engine + "'.";
        } else {
            std::string parsedSetup;
            std::string parsedLoop;
            if (kind == "block") {
                if (!validate_logic_source_text(setupSource, err)) {
                    ok = false;
                } else if (!validate_logic_source_text(loopSource, err)) {
                    ok = false;
                }
                parsedSetup = strip_logic_comments(setupSource);
                parsedLoop = strip_logic_comments(loopSource);
            } else {
                if (!validate_logic_source_text(source, err)) {
                    ok = false;
                }
                parsedLoop = strip_logic_comments(source);
            }
            if (!ok) {
                // keep err from validation
            } else {
                const std::string &effectiveLoopSource = parsedLoop;
                const std::string &effectiveSetupSource = parsedSetup;
                std::unordered_map<std::string, std::string> setupVars = retainedVars;
                if (ok && kind == "block" && !setupInitialized && !trim_copy(effectiveSetupSource).empty()) {
                    LogicReferenceValidation setupEval = evaluate_logic_variables(effectiveSetupSource, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, setupVars);
                    if (!setupEval.error.empty()) {
                        ok = false;
                        err = "setup: " + setupEval.error;
                    } else {
                        retainedVars = std::move(setupVars);
                        setupInitialized = true;
                    }
                }
                refs = validate_logic_read_references(effectiveLoopSource, tagKeys, systemTagNames, tagSnapshots, systemSnapshots);
                if (refs.missing_tags > 0) {
                    ok = false;
                    err = refs.error;
                } else {
                    variables = retainedVars;

                    std::vector<LogicIfBlock> ifBlocks;
                    std::string ifError;
                    if (ok && !logic_collect_if_blocks(effectiveLoopSource, ifBlocks, ifError)) {
                        ok = false;
                        err = ifError;
                    }
                    const std::string topLevelSource = ok ? logic_without_if_blocks(effectiveLoopSource, ifBlocks) : std::string{};
                    LogicReferenceValidation vars;
                    if (ok) {
                        vars = evaluate_logic_variables(topLevelSource, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, variables);
                    }
                    refs.variables = vars.variables;
                    refs.variable_preview = vars.variable_preview;
                    if (!vars.error.empty()) {
                        ok = false;
                        err = vars.error;
                    }
                    if (ok && drivers && tagTable && driverMutex && uaQueue && mqttQueue) {
                        LogicReferenceValidation writes = apply_logic_memory_writes(topLevelSource, variables, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, *drivers, *tagTable, *driverMutex, *uaQueue, *mqttQueue);
                        refs.memory_writes = writes.memory_writes;
                        refs.write_preview = writes.write_preview;
                        if (!writes.error.empty()) {
                            ok = false;
                            err = writes.error;
                        }
                    }
                    if (ok) {
                        for (const auto &block : ifBlocks) {
                            std::string condValue;
                            std::string condErr;
                            if (!evaluate_logic_expression_value(block.condition, variables, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, condValue, condErr)) {
                                ok = false;
                                err = "if condition: " + condErr;
                                break;
                            }
                            bool cond = false;
                            if (!logic_string_to_bool(condValue, cond)) {
                                ok = false;
                                err = "if condition did not evaluate to a boolean.";
                                break;
                            }
                            const std::string *selectedBody = nullptr;
                            if (cond) selectedBody = &block.body;
                            else if (block.has_else) selectedBody = &block.else_body;
                            if (!selectedBody) continue;

                            LogicReferenceValidation blockVars = evaluate_logic_variables(*selectedBody, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, variables);
                            logic_merge_result(refs, blockVars);
                            if (!blockVars.error.empty()) {
                                ok = false;
                                err = blockVars.error;
                                break;
                            }
                            if (drivers && tagTable && driverMutex && uaQueue && mqttQueue) {
                                LogicReferenceValidation blockWrites = apply_logic_memory_writes(*selectedBody, variables, tagKeys, systemTagNames, tagSnapshots, systemSnapshots, *drivers, *tagTable, *driverMutex, *uaQueue, *mqttQueue);
                                logic_merge_result(refs, blockWrites);
                                if (!blockWrites.error.empty()) {
                                    ok = false;
                                    err = blockWrites.error;
                                    break;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Ensure validation shows the current variable set, including retained
        // locals carried from prior block cycles.
        if (!variables.empty()) {
            std::vector<std::string> names;
            names.reserve(variables.size());
            for (const auto &kv : variables) names.push_back(kv.first);
            std::sort(names.begin(), names.end());
            refs.variables = static_cast<int>(variables.size());
            refs.variable_preview.clear();
            int shown = 0;
            for (const auto &name : names) {
                auto it = variables.find(name);
                if (it == variables.end()) continue;
                if (!refs.variable_preview.empty()) refs.variable_preview += "; ";
                refs.variable_preview += name + "=" + it->second;
                ++shown;
                if (shown >= 10) break;
            }
        }

        const int64_t durationMs = steady_elapsed_ms(started);
        if (ok && kind == "block") {
            retainedVars = variables;
        }
        {
            std::lock_guard<std::mutex> lock(g_logicMutex);
            if (idx >= g_logicState.scripts.size()) continue;
            auto &script = g_logicState.scripts[idx];
            script.last_run_ms = nowMs;
            script.last_run_duration_ms = durationMs;
            script.last_run_ok = ok;
            script.runs_total += 1;
            if (!ok) script.failures_total += 1;
            script.referenced_tags = refs.referenced_tags;
            script.missing_tags = refs.missing_tags;
            script.evaluated_reads = refs.evaluated_reads;
            script.memory_writes = refs.memory_writes;
            script.variables = refs.variables;
            script.read_preview = refs.read_preview;
            script.write_preview = refs.write_preview;
            script.variable_preview = refs.variable_preview;
            script.last_error = ok ? std::string{} : err;
            script.setup_initialized = setupInitialized;
            script.retained_vars = retainedVars;
            g_logicState.last_run_ms = nowMs;
            g_logicState.runs_total += 1;
            if (!ok) {
                g_logicState.failures_total += 1;
                g_logicState.last_error = err;
            } else if (g_logicState.last_load_ok) {
                g_logicState.last_error.clear();
            }
        }
    }
}

bool config_has_enabled_mqtt_connection(const std::string &configDir) {
    const std::string mqttPath = joinPath(configDir, "mqtt.json");
    if (fs::exists(mqttPath)) {
        try {
            json jm = load_json_with_comments(mqttPath);
            if (!jm.value("enabled", false)) {
                return false;
            }
        } catch (...) {
            return false;
        }
    }

    const std::string connDir = joinPath(configDir, "connections");
    std::error_code ec;
    if (!fs::exists(connDir, ec) || !fs::is_directory(connDir, ec)) {
        return false;
    }

    for (const auto &entry : fs::directory_iterator(connDir, ec)) {
        if (ec) break;
        if (!entry.is_regular_file()) continue;
        if (entry.path().extension() != ".json") continue;
        try {
            json jc = load_json_with_comments(entry.path().string());
            if (jc.value("driver", std::string("ab_eip")) != "mqtt") continue;
            const json settings = (jc.contains("settings") && jc["settings"].is_object())
                ? jc["settings"]
                : json::object();
            if (!settings.value("enabled", jc.value("enabled", true))) continue;
            const std::string host = trim_copy(settings.value("host", jc.value("host", std::string{})));
            if (host.empty()) continue;
            return true;
        } catch (...) {
            continue;
        }
    }
    return false;
}

bool load_all_drivers(std::vector<DriverContext> &outDrivers,
                      const std::string &configDir)
{
    std::string connDir = joinPath(configDir, "connections");
    std::string tagDir  = joinPath(configDir, "tags");

    std::cout << "[load] Using configDir:  " << configDir << "\n";
    std::cout << "[load] Connections dir:  " << connDir << "\n";
    std::cout << "[load] Tags dir:         " << tagDir << "\n";

    std::map<std::string, ConnectionConfig> connection_map;

    if (!fs::exists(connDir)) {
        std::cerr << "[load] Warning: connections directory does not exist: "
                  << connDir << "\n";
    } else {
        // Load connections
        for (const auto &entry : fs::directory_iterator(connDir)) {
            if (!entry.is_regular_file()) continue;
            if (entry.path().extension() != ".json") continue;

            std::string path = entry.path().string();
            try {
                ConnectionConfig c = load_connection_config(path);
                std::cout << "[load] Loaded connection '" << c.id
                          << "' (driver=" << c.driver
                          << ", gateway=" << c.gateway
                          << ", path=" << c.path
                          << ", slot=" << c.slot
                          << ", plc_type=" << c.plc_type
                          << ") from " << path << "\n";
                if (connection_map.count(c.id)) {
                    std::cerr << "[load] Warning: duplicate connection id '"
                              << c.id << "'; overwriting previous.\n";
                }
                connection_map[c.id] = c;
            } catch (const std::exception &ex) {
                std::cerr << "[load] Error in connection file " << path
                          << ": " << ex.what() << "\n";
            }
        }
    }

    // Load tag files
    // Prefer one canonical tag file per connection_id (tags/<id>.json). If present, ignore other files
    // that claim the same connection_id (e.g. legacy .jsonc or alternate filenames).
    std::map<std::string, std::vector<TagConfig>> tags_by_conn;

    if (!fs::exists(tagDir)) {
        std::cerr << "[load] Warning: tags directory does not exist: "
                  << tagDir << "\n";
    } else {
        struct TagFileChoice {
            std::string cid;
            std::string path;
            std::string filename;
        };

        std::vector<TagFileChoice> candidates;
        for (const auto &entry : fs::directory_iterator(tagDir)) {
            if (!entry.is_regular_file()) continue;
            const std::string ext = entry.path().extension().string();
            if (ext != ".json" && ext != ".jsonc") continue;

            const std::string path = entry.path().string();
            try {
                TagFile tf = load_tag_file(path);
                if (tf.connection_id.empty()) continue;
                candidates.push_back({tf.connection_id, path, entry.path().filename().string()});
            } catch (const std::exception &ex) {
                std::cerr << "[load] Error in tag file " << path
                          << ": " << ex.what() << "\n";
            }
        }

        std::map<std::string, TagFileChoice> chosen;
        std::unordered_map<std::string, std::vector<TagFileChoice>> byCid;
        for (const auto &c : candidates) byCid[c.cid].push_back(c);

        for (auto &kv : byCid) {
            const std::string &cid = kv.first;
            auto &arr = kv.second;

            auto is_canonical_json = [&](const TagFileChoice &x) {
                return x.filename == (cid + ".json");
            };
            auto is_canonical_jsonc = [&](const TagFileChoice &x) {
                return x.filename == (cid + ".jsonc");
            };

            auto it = std::find_if(arr.begin(), arr.end(), is_canonical_json);
            if (it == arr.end()) it = std::find_if(arr.begin(), arr.end(), is_canonical_jsonc);
            if (it == arr.end()) {
                std::sort(arr.begin(), arr.end(), [](const TagFileChoice &a, const TagFileChoice &b) {
                    return a.filename < b.filename;
                });
                it = arr.begin();
            }

            chosen[cid] = *it;

            if (arr.size() > 1) {
                std::cerr << "[load] Info: multiple tag files for connection_id '" << cid
                          << "'. Using " << it->filename << " and ignoring others.\n";
            }
        }

        for (const auto &kv : chosen) {
            const auto &pick = kv.second;
            try {
                TagFile tf = load_tag_file(pick.path);
                std::cout << "[load] Loaded tag file for connection_id '"
                          << tf.connection_id << "' from " << pick.path << "\n";
                auto &vec = tags_by_conn[tf.connection_id];
                vec.insert(vec.end(), tf.tags.begin(), tf.tags.end());
            } catch (const std::exception &ex) {
                std::cerr << "[load] Error in tag file " << pick.path
                          << ": " << ex.what() << "\n";
            }
        }
    }

    for (const auto &kv : tags_by_conn) {
        const auto &conn_id = kv.first;
        if (!connection_map.count(conn_id)) {
            const bool memoryOnly = std::all_of(kv.second.begin(), kv.second.end(), [](const TagConfig &tag) {
                return is_memory_tag(tag);
            });
            if (!memoryOnly) {
                std::cerr << "[load] Warning: tags configured for connection_id '"
                          << conn_id << "' but no such connection exists.\n";
            }
        }
    }

    struct DriverBuildJob {
        std::string conn_id;
        ConnectionConfig conn_cfg;
        std::vector<TagConfig> tags;
    };
    struct DriverBuildResult {
        bool ok = false;
        std::string conn_id;
        std::string err;
        DriverContext ctx;
    };

    std::vector<DriverBuildJob> jobs;
    for (const auto &kv : connection_map) {
        const std::string &conn_id = kv.first;
        const ConnectionConfig &conn_cfg = kv.second;
        auto tags_it = tags_by_conn.find(conn_id);
        if (tags_it == tags_by_conn.end()) {
            std::cerr << "[load] Info: no tags defined for connection '"
                      << conn_id << "'. Skipping.\n";
            continue;
        }
        std::vector<TagConfig> normalizedTags = tags_it->second;
        if (to_lower_copy(trim_copy(conn_cfg.driver)) == "mqtt") {
            for (auto &tag : normalizedTags) {
                const bool isSubscription =
                    mqtt_name_matches_any_topic_scope(tag.logical_name, conn_cfg.mqtt_subscription_topics) ||
                    mqtt_is_subscription_tag_name(tag.logical_name);
                if (isSubscription) {
                    tag.writable = false;
                    continue;
                }
                if (mqtt_name_matches_any_topic_scope(tag.logical_name, conn_cfg.mqtt_publication_topics)) {
                    tag.writable = true;
                }
            }
        }
        jobs.push_back(DriverBuildJob{conn_id, conn_cfg, std::move(normalizedTags)});
    }
    for (const auto &kv : tags_by_conn) {
        const std::string &conn_id = kv.first;
        if (connection_map.count(conn_id)) continue;
        const bool memoryOnly = std::all_of(kv.second.begin(), kv.second.end(), [](const TagConfig &tag) {
            return is_memory_tag(tag);
        });
        if (!memoryOnly) continue;
        ConnectionConfig memoryConn;
        memoryConn.id = conn_id;
        memoryConn.driver = "memory";
        memoryConn.plc_type = "memory";
        memoryConn.polling_mode = "standard";
        memoryConn.polling_pacing = "gentle";
        jobs.push_back(DriverBuildJob{conn_id, memoryConn, kv.second});
    }

    std::vector<DriverContext> driversLocal;
    std::vector<DriverBuildResult> results(jobs.size());
    if (!jobs.empty()) {
        unsigned int hw = std::thread::hardware_concurrency();
        size_t workerCount = std::min<size_t>(jobs.size(), std::max<size_t>(1, std::min<size_t>(4, hw == 0 ? 2 : hw)));
        {
            std::ostringstream msg;
            msg << "Building " << jobs.size()
                << " connection(s) with " << workerCount
                << " parallel startup worker(s).";
            runtime_log("info", "load", msg.str());
        }

        std::atomic<size_t> nextJob{0};
        std::vector<std::thread> workers;
        workers.reserve(workerCount);
        for (size_t w = 0; w < workerCount; ++w) {
            workers.emplace_back([&]() {
                while (true) {
                    const size_t idx = nextJob.fetch_add(1, std::memory_order_relaxed);
                    if (idx >= jobs.size()) return;
                    const auto &job = jobs[idx];
                    DriverBuildResult result;
                    result.conn_id = job.conn_id;
                    result.ok = build_driver_context_for_connection(job.conn_cfg, job.tags, result.ctx, result.err);
                    results[idx] = std::move(result);
                }
            });
        }
        for (auto &worker : workers) {
            if (worker.joinable()) worker.join();
        }

        for (auto &result : results) {
            if (!result.ok) {
                runtime_log("error", "load", "Error building connection '" + result.conn_id
                    + "': " + (result.err.empty() ? std::string("unknown error") : result.err));
                continue;
            }
            driversLocal.push_back(std::move(result.ctx));
        }
    }

    if (driversLocal.empty()) {
        std::cerr << "[load] No drivers with tags configured; starting with empty tag set.\n";
        outDrivers.clear();
        return true;
    }

    std::cout << "[load] Driver summary:\n";
    for (const auto &d : driversLocal) {
        std::cout << "  Connection '" << d.conn.id
                  << "' has " << d.tags.size() << " tag(s).\n";
    }

    outDrivers = std::move(driversLocal);
    return true;
}

bool load_alarms(const std::string &configDir,
                 std::vector<AlarmRuntime> &outAlarms)
{
    try {
        json j;

        // Prefer alarms_config.db (canonical) if present; fall back to alarms.json if needed.
        {
            std::string errMsg;
            int64_t updatedMs = -1;
            if (sqlite_alarms_config_init(configDir) &&
                sqlite_alarms_config_get(j, updatedMs, errMsg)) {
                // ok
            } else {
                const std::string path = joinPath(configDir, "alarms.json");
                if (!fs::exists(path)) {
                    outAlarms.clear();
                    return true;
                }
                j = load_json_with_comments(path);
            }
        }

        if (!j.is_object() || !j.contains("alarms") || !j["alarms"].is_array()) {
            // This runtime alarm loader only consumes the legacy "alarms" array shape.
            outAlarms.clear();
            return true;
        }

        std::vector<AlarmRuntime> tmp;

	        for (const auto &ja : j["alarms"]) {
	            AlarmConfig cfg;

            cfg.id             = ja.value("id", std::string{});
            cfg.name           = ja.value("name", ja.value("description", cfg.id));
            cfg.connection_id  = ja.value("connection_id", std::string{});
            cfg.tag_name       = ja.value("tag_name", std::string{});
            cfg.type           = ja.value("type", std::string{});
            cfg.threshold      = ja.value("threshold", cfg.threshold);
            cfg.hysteresis     = ja.value("hysteresis", cfg.hysteresis);
            cfg.enabled        = ja.value("enabled", cfg.enabled);
            cfg.severity       = ja.value("severity", cfg.severity);
            cfg.message_on_active = ja.value("message_on_active", ja.value("message", std::string{}));
            cfg.message_on_return = ja.value("message_on_return", std::string{});
	            cfg.group          = ja.value("group", std::string{});
	            cfg.site           = ja.value("site", std::string{});
	            if (ja.contains("value")) cfg.equals_value = ja["value"];
	            else if (ja.contains("equals_value")) cfg.equals_value = ja["equals_value"];
	            // Backward-compat / UI convenience: allow type=equals to use "threshold" as the target value.
	            else if (ja.contains("threshold")) cfg.equals_value = ja["threshold"];
	            cfg.equals_tolerance = ja.value("tolerance", ja.value("equals_tolerance", cfg.equals_tolerance));

            if (cfg.id.empty() || cfg.connection_id.empty() ||
                cfg.tag_name.empty() || cfg.type.empty())
            {
                std::cerr << "[alarms] Skipping alarm with missing fields (id/connection_id/tag_name/type).\n";
                continue;
            }

            // normalize type to lowercase
            for (auto &c : cfg.type) {
                c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            }

	            if (cfg.type != "high" &&
	                cfg.type != "low" &&
	                cfg.type != "change" &&
	                cfg.type != "equals" &&
	                cfg.type != "not_equals" &&
	                cfg.type != "contains" &&
	                cfg.type != "not_contains" &&
	                cfg.type != "empty" &&
	                cfg.type != "not_empty")
	            {
	                std::cerr << "[alarms] Alarm '" << cfg.id
	                          << "' has unsupported type '" << cfg.type
	                          << "'. Skipping.\n";
	                continue;
	            }

		            if ((cfg.type == "equals" || cfg.type == "not_equals" || cfg.type == "contains" || cfg.type == "not_contains") && cfg.equals_value.is_null()) {
		                std::cerr << "[alarms] Alarm '" << cfg.id << "' type=" << cfg.type << " requires field 'value' (or 'threshold'). Skipping.\n";
		                continue;
		            }

            AlarmRuntime rt;
            rt.cfg = cfg;
            rt.active = false;
            rt.hasLastValue = false;
            tmp.push_back(rt);
        }

        outAlarms = std::move(tmp);

        std::cout << "[alarms] Loaded " << outAlarms.size()
                  << " alarm(s)\n";
        return true;
    } catch (const std::exception &ex) {
        std::cerr << "[alarms] Error loading alarms config: " << ex.what() << "\n";
        return false;
    }
}

// Build map from "<conn>:<tag>" → alarm indices
void build_alarm_index(const std::vector<AlarmRuntime> &alarms) {
    g_alarmIndexByTag.clear();
    for (size_t i = 0; i < alarms.size(); ++i) {
        const auto &a = alarms[i];
        if (!a.cfg.enabled) continue;
        std::string key = make_tag_key(a.cfg.connection_id, a.cfg.tag_name);
        g_alarmIndexByTag[key].push_back(i);
    }

    std::cout << "[alarms] Index built for "
              << g_alarmIndexByTag.size() << " tag(s).\n";
}


// Resolve the CA certificate path based on mqtt.json (if present) or default.
static std::string resolve_ca_cert_path(const std::string &configDir) {
    // Default fallback: <configDir>/ca.crt
    std::string defaultPath = joinPath(configDir, "ca.crt");

    // Try to read mqtt.json to see if a cafile is configured
    std::string mqttPath = joinPath(configDir, "mqtt.json");
    if (!fs::exists(mqttPath)) {
        return defaultPath;
    }

    try {
        std::string txt = read_file_to_string(mqttPath);
        nlohmann::json j = nlohmann::json::parse(strip_json_comments(txt));

        std::string cafile = j.value("cafile", "");
        if (cafile.empty()) {
            return defaultPath;
        }

        fs::path p(cafile);
        if (p.is_absolute()) {
            return p.string();
        } else {
            return joinPath(configDir, cafile);
        }
    } catch (...) {
        // If anything goes wrong, just fall back.
        return defaultPath;
    }
}

std::string mqtt_sanitize(const std::string &s) {
    std::string out;
    out.reserve(s.size());
    for (char c : s) {
        if (std::isalnum(static_cast<unsigned char>(c)) ||
            c == '_' || c == '-' || c == '.') {
            out.push_back(c);
        } else {
            out.push_back('_');
        }
    }
    if (out.empty()) out = "_";
    return out;
}

void mqtt_publish_raw(const std::string &topic,
                      const std::string &payload)
{
    if (!g_mqtt) return;

    std::lock_guard<std::mutex> lock(g_mqttMutex);

    int rc = mosquitto_publish(
        g_mqtt,
        nullptr, // message id (we don't track)
        topic.c_str(),
        static_cast<int>(payload.size()),
        payload.data(),
        g_mqttCfg.qos,
        g_mqttCfg.retain
    );

    if (rc != MOSQ_ERR_SUCCESS) {
        std::cerr << "[mqtt] publish to '" << topic << "' failed: "
                  << mosquitto_strerror(rc) << "\n";
        g_mqttRuntimeStats.publish_failures_total.fetch_add(1, std::memory_order_relaxed);
        {
            std::lock_guard<std::mutex> lock(g_mqttRuntimeStats.error_mutex);
            g_mqttRuntimeStats.last_error = std::string("publish failed: ") + mosquitto_strerror(rc);
        }
    } else {
        g_mqttRuntimeStats.messages_published_total.fetch_add(1, std::memory_order_relaxed);
    }
}

// Helper: publish structured ACK for an MQTT command
void mqtt_publish_command_ack(const std::string &conn_id,
                              const std::string &tag_name,
                              const std::string &value_str,
                              bool ok,
                              const std::string &error_msg,
                              const std::string &topic_suffix,
                              int64_t ts_ms,
                              const std::string &source_topic)
{
    if (!g_mqtt || !g_mqttCfg.enabled) {
        return;
    }

    json j;
    j["connection_id"]         = conn_id;
    j["tag"]                   = tag_name;
    j["requested_value"]       = value_str;
    j["ok"]                    = ok;
    j["response_timestamp_ms"] = ts_ms;

    if (!error_msg.empty()) {
        j["error"] = error_msg;
    }
    if (!source_topic.empty()) {
        j["source_topic"] = source_topic;
    }

    const std::string connSafe = mqtt_sanitize(conn_id);
    const std::string tagSafe  = mqtt_sanitize(tag_name);

    // Build final topic:
    //   ack_topic_prefix/<topic_suffix>   (if topic_suffix not empty)
    //   ack_topic_prefix/<conn>/<tag>     (otherwise)
    std::string topic = g_mqttCfg.ack_topic_prefix;
    if (!topic.empty() && topic.back() != '/') {
        topic.push_back('/');
    }

    if (!topic_suffix.empty()) {
        topic += topic_suffix;  // e.g. "microplc03/ML1100.RunCommand"
    } else {
        topic += connSafe + "/" + tagSafe;
    }

    mqtt_publish_raw(topic, j.dump());
}

bool mqtt_publish_snapshot(const TagSnapshot &snap,
                           const TagSnapshot *prev)
{
    if (!g_mqtt || !g_mqttCfg.enabled) {
        return false;
    }
    if (is_memory_connection_id(snap.connection_id) && !g_mqttCfg.publish_memory_tags) {
        return false;
    }

    const std::string key = make_tag_key(snap.connection_id, snap.logical_name);

    auto now = snap.timestamp;
    if (now.time_since_epoch().count() == 0) {
        now = std::chrono::system_clock::now();
    }

    MqttTagState &state = g_mqttTagState[key];

    bool changed = false;

    if (!state.hasValue) {
        changed = true;
    } else {
        // value change
        changed = (snap.value != state.lastValue);
        // you can also include quality changes if you like
        if (!changed && prev && prev->quality != snap.quality) {
            changed = true;
        }
    }

    if (!g_mqttCfg.publish_per_field && !g_mqttCfg.publish_tag_json) {
        return false;
    }

    const auto elapsedMs = state.hasValue
        ? std::chrono::duration_cast<std::chrono::milliseconds>(now - state.lastPublish).count()
        : std::numeric_limits<int64_t>::max();
    if (state.hasValue && g_mqttCfg.publish_min_update_ms > 0 &&
        elapsedMs < g_mqttCfg.publish_min_update_ms) {
        return false;
    }

    bool shouldPublish = false;
    if (g_mqttCfg.publish_mode == "interval") {
        shouldPublish = !state.hasValue || elapsedMs >= g_mqttCfg.publish_interval_ms;
    } else if (g_mqttCfg.publish_mode == "change_or_interval") {
        shouldPublish = changed || !state.hasValue || elapsedMs >= g_mqttCfg.publish_interval_ms;
    } else {
        shouldPublish = changed;
    }
    if (!shouldPublish) {
        return false;
    }

    // Update state
    state.hasValue    = true;
    state.lastPublish = now;
    state.lastValue   = snap.value;

    const std::string base = g_mqttCfg.base_topic.empty()
                           ? std::string("opcbridge")
                           : g_mqttCfg.base_topic;

    const std::string connSafe = mqtt_sanitize(snap.connection_id);
    const std::string tagSafe  = mqtt_sanitize(snap.logical_name);

    // stringify value
    std::string valueStr;
    {
        std::ostringstream oss;
        std::visit([&oss](auto &&arg) { oss << arg; }, snap.value);
        valueStr = oss.str();
    }

    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        now.time_since_epoch()
    ).count();

    // Pattern 1: per-field topics
    if (g_mqttCfg.publish_per_field) {
        std::string t_val = base + "/" + connSafe + "/" + tagSafe + "/value";
        std::string t_qlt = base + "/" + connSafe + "/" + tagSafe + "/quality";
        std::string t_ts  = base + "/" + connSafe + "/" + tagSafe + "/timestamp";

        mqtt_publish_raw(t_val, valueStr);

        {
            std::ostringstream oss;
            oss << snap.quality;
            mqtt_publish_raw(t_qlt, oss.str());
        }

        {
            std::ostringstream oss;
            oss << ms;
            mqtt_publish_raw(t_ts, oss.str());
        }
    }

    // Pattern 2: JSON per tag
    if (g_mqttCfg.publish_tag_json) {
        json jt;
        jt["connection_id"] = snap.connection_id;
        jt["name"]          = snap.logical_name;
        jt["datatype"]      = snap.datatype;
        jt["quality"]       = snap.quality;
        jt["timestamp_ms"]  = ms;

        std::visit([&jt](auto &&arg) {
            jt["value"] = arg;
        }, snap.value);

        std::string topic = base + "/" + connSafe + "/" + tagSafe;
        mqtt_publish_raw(topic, jt.dump());
    }

    return true;
}

bool mqtt_publish_system_tag(const SystemTagDef &def)
{
    if (!g_mqtt || !g_mqttCfg.enabled || !g_mqttCfg.publish_system_tags) {
        return false;
    }
    if (!g_mqttCfg.publish_per_field && !g_mqttCfg.publish_tag_json) {
        return false;
    }

    const std::string key = make_tag_key("_system", def.name);
    const auto now = std::chrono::system_clock::now();
    MqttTagState &state = g_mqttTagState[key];

    const std::string valueStr = def.value.is_string() ? def.value.get<std::string>() : def.value.dump();
    TagValue currentValue = valueStr;
    const bool changed = !state.hasValue || state.lastValue != currentValue;
    const auto elapsedMs = state.hasValue
        ? std::chrono::duration_cast<std::chrono::milliseconds>(now - state.lastPublish).count()
        : std::numeric_limits<int64_t>::max();

    if (state.hasValue && g_mqttCfg.publish_min_update_ms > 0 &&
        elapsedMs < g_mqttCfg.publish_min_update_ms) {
        return false;
    }

    bool shouldPublish = false;
    if (g_mqttCfg.publish_mode == "interval") {
        shouldPublish = !state.hasValue || elapsedMs >= g_mqttCfg.publish_interval_ms;
    } else if (g_mqttCfg.publish_mode == "change_or_interval") {
        shouldPublish = changed || !state.hasValue || elapsedMs >= g_mqttCfg.publish_interval_ms;
    } else {
        shouldPublish = changed;
    }
    if (!shouldPublish) return false;

    state.hasValue = true;
    state.lastPublish = now;
    state.lastValue = currentValue;

    const std::string base = g_mqttCfg.base_topic.empty()
                           ? std::string("opcbridge")
                           : g_mqttCfg.base_topic;
    const std::string connSafe = mqtt_sanitize("_system");
    const std::string tagSafe = mqtt_sanitize(def.name);
    const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        now.time_since_epoch()
    ).count();

    if (g_mqttCfg.publish_per_field) {
        mqtt_publish_raw(base + "/" + connSafe + "/" + tagSafe + "/value", valueStr);
        mqtt_publish_raw(base + "/" + connSafe + "/" + tagSafe + "/quality", "1");
        mqtt_publish_raw(base + "/" + connSafe + "/" + tagSafe + "/timestamp", std::to_string(ms));
    }

    if (g_mqttCfg.publish_tag_json) {
        json jt;
        jt["connection_id"] = "_system";
        jt["name"] = def.name;
        jt["datatype"] = def.datatype;
        jt["quality"] = 1;
        jt["timestamp_ms"] = ms;
        jt["value"] = def.value;
        mqtt_publish_raw(base + "/" + connSafe + "/" + tagSafe, jt.dump());
    }

    return true;
}

bool mqtt_publish_connection_snapshot(const std::string &connId,
                                      const TagTable &table,
                                      bool anyTagChanged)
{
    if (!g_mqtt || !g_mqttCfg.enabled || !g_mqttCfg.publish_conn_json) {
        return false;
    }

    auto now = std::chrono::system_clock::now();
    MqttConnState &st = g_mqttConnState[connId];

    bool heartbeatDue = false;
    if (st.hasPublish) {
        auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(
            now - st.lastPublish
        ).count();
        heartbeatDue = (elapsed >= g_mqttCfg.heartbeat_sec);
    } else {
        heartbeatDue = true;
    }

    if (!anyTagChanged && !heartbeatDue) {
        return false;
    }

    json root;
    root["connection_id"] = connId;
    root["ts"] = std::chrono::duration_cast<std::chrono::milliseconds>(
        now.time_since_epoch()
    ).count();
    root["tags"] = json::array();

    for (const auto &kv : table) {
        const TagSnapshot &snap = kv.second;
        if (snap.connection_id != connId) continue;

        json jt;
        jt["connection_id"] = snap.connection_id;
        jt["name"]          = snap.logical_name;
        jt["datatype"]      = snap.datatype;
        jt["quality"]       = snap.quality;
        jt["timestamp_ms"]  = std::chrono::duration_cast<std::chrono::milliseconds>(
            snap.timestamp.time_since_epoch()
        ).count();

        std::visit([&jt](auto &&arg) {
            jt["value"] = arg;
        }, snap.value);

        root["tags"].push_back(jt);
    }

    const std::string base = g_mqttCfg.base_topic.empty()
                           ? std::string("opcbridge")
                           : g_mqttCfg.base_topic;
    std::string topic = base + "/" + mqtt_sanitize(connId) + "/all";

    mqtt_publish_raw(topic, root.dump());

    st.hasPublish = true;
    st.lastPublish = now;
    return true;
}

// ----------------------------------------------------------
// MQTT config summary / validation (startup diagnostics)
// ----------------------------------------------------------
void mqtt_log_config_summary(const std::string &configDir) {
    std::cout << "[mqtt] ================= MQTT CONFIG SUMMARY =================\n";

    std::cout << "[mqtt] enabled:            " << (g_mqttCfg.enabled ? "true" : "false") << "\n";
    std::cout << "[mqtt] host:               " << g_mqttCfg.host << ":" << g_mqttCfg.port << "\n";
    std::cout << "[mqtt] client_id:          " << g_mqttCfg.client_id << "\n";
    std::cout << "[mqtt] base_topic:         " << g_mqttCfg.base_topic << "\n";
    std::cout << "[mqtt] qos:                " << g_mqttCfg.qos << "\n";
    std::cout << "[mqtt] retain:             " << (g_mqttCfg.retain ? "true" : "false") << "\n";
    std::cout << "[mqtt] keepalive:          " << g_mqttCfg.keepalive << "s\n";

    // Commands / ACKs
    std::cout << "[mqtt] subscribe_enabled:  " << (g_mqttCfg.subscribe_enabled ? "true" : "false") << "\n";
    std::cout << "[mqtt] command_topic:      " << (g_mqttCfg.command_topic.empty()
                                                ? "<empty>"
                                                : g_mqttCfg.command_topic) << "\n";
    std::cout << "[mqtt] ack_topic_prefix:   " << (g_mqttCfg.ack_topic_prefix.empty()
                                                ? "<empty>"
                                                : g_mqttCfg.ack_topic_prefix) << "\n";

    // Publish patterns
    std::cout << "[mqtt] publish_per_field:  " << (g_mqttCfg.publish_per_field ? "true" : "false") << "\n";
    std::cout << "[mqtt] publish_tag_json:   " << (g_mqttCfg.publish_tag_json ? "true" : "false") << "\n";
    std::cout << "[mqtt] publish_conn_json:  " << (g_mqttCfg.publish_conn_json ? "true" : "false") << "\n";

    // Write auth
    std::cout << "[mqtt] require_write_token:" << (g_mqttCfg.require_write_token ? "true" : "false") << "\n";

    if (g_mqttCfg.subscribe_enabled) {
        std::cout << "[mqtt] INFO: MQTT commands are ENABLED. Subscribing to: "
                  << g_mqttCfg.command_topic << "/#\n";
    } else {
        std::cout << "[mqtt] WARNING: subscribe_enabled=false; MQTT commands are DISABLED.\n";
        std::cout << "[mqtt]          No writes from MQTT will be processed.\n";
    }

    if (g_mqttCfg.command_topic.empty()) {
        std::cout << "[mqtt] WARNING: command_topic is empty; MQTT commands cannot be matched.\n";
    }

    if (g_mqttCfg.ack_topic_prefix.empty()) {
        std::cout << "[mqtt] WARNING: ack_topic_prefix is empty; ACK topics will be malformed.\n";
    }

    // TLS summary / validation
    std::cout << "[mqtt] use_tls:            " << (g_mqttCfg.use_tls ? "true" : "false") << "\n";

    if (g_mqttCfg.use_tls) {
        auto resolvePath = [&](const std::string &p) -> std::string {
            if (p.empty()) return {};
            // absolute path? just return
            if (!p.empty() && p[0] == '/')
                return p;
            // otherwise treat as relative to configDir
            return joinPath(configDir, p);
        };

        std::string cafile   = resolvePath(g_mqttCfg.cafile);
        std::string certfile = resolvePath(g_mqttCfg.certfile);
        std::string keyfile  = resolvePath(g_mqttCfg.keyfile);

        std::cout << "[mqtt]   cafile:          " << (cafile.empty() ? "<none>" : cafile) << "\n";
        std::cout << "[mqtt]   certfile:        " << (certfile.empty() ? "<none>" : certfile) << "\n";
        std::cout << "[mqtt]   keyfile:         " << (keyfile.empty() ? "<none>" : keyfile) << "\n";
        std::cout << "[mqtt]   tls_version:     "
                  << (g_mqttCfg.tls_version.empty() ? "<default>" : g_mqttCfg.tls_version) << "\n";
        std::cout << "[mqtt]   tls_insecure:    " << (g_mqttCfg.tls_insecure ? "true" : "false") << "\n";

        // Basic existence checks (warn only)
        if (!cafile.empty() && !fs::exists(cafile)) {
            std::cout << "[mqtt] WARNING: cafile does not exist on disk: " << cafile << "\n";
        }

        if (!certfile.empty() && !fs::exists(certfile)) {
            std::cout << "[mqtt] WARNING: certfile does not exist on disk: " << certfile << "\n";
        }

        if (!keyfile.empty() && !fs::exists(keyfile)) {
            std::cout << "[mqtt] WARNING: keyfile does not exist on disk: " << keyfile << "\n";
        }

        if (g_mqttCfg.cafile.empty() && g_mqttCfg.capath.empty()) {
            std::cout << "[mqtt] WARNING: TLS enabled but no cafile/capath configured.\n";
            std::cout << "[mqtt]          TLS handshake may fail if the broker cert is not in the system trust store.\n";
        }
    }

    std::cout << "[mqtt] =======================================================\n";
}

bool mqtt_init(const std::string &configDir) {
    if (!load_mqtt_config(configDir)) {
        return false;
    }

    auto make_auto_mqtt_client_id = []() -> std::string {
        unsigned int rnd = 0;
        std::random_device rd;
        rnd = rd();
        if (rnd == 0) {
            rnd = static_cast<unsigned int>(
                std::chrono::steady_clock::now().time_since_epoch().count()
            );
        }
        std::ostringstream oss;
        oss << "opcbridge-" << getpid() << "-"
            << std::hex << std::setw(8) << std::setfill('0') << rnd;
        return oss.str();
    };

    std::string configuredClientId = trim_copy(g_mqttCfg.client_id);
    std::string configuredLower = to_lower_copy(configuredClientId);
    if (configuredClientId.empty() ||
        configuredLower == "auto" ||
        configuredLower == "opcbridge" ||
        configuredLower == "opcbridge-core") {
        g_mqttCfg.client_id = make_auto_mqtt_client_id();
        std::cout << "[mqtt] Auto-generated MQTT client_id: "
                  << g_mqttCfg.client_id << "\n";
    } else {
        g_mqttCfg.client_id = configuredClientId;
    }

    // Log a summary of the loaded configuration (for humans)
    mqtt_log_config_summary(configDir);

    if (!g_mqttCfg.enabled) {
        std::cerr << "[mqtt] Config sets enabled=false; MQTT will not start.\n";
        return false;
    }

    mosquitto_lib_init();

    std::string cid = g_mqttCfg.client_id;

    g_mqtt = mosquitto_new(cid.c_str(), true, nullptr);
    if (!g_mqtt) {
        std::cerr << "[mqtt] mosquitto_new failed.\n";
        mosquitto_lib_cleanup();
        return false;
    }

    // Optional auth
    if (!g_mqttCfg.username.empty()) {
        mosquitto_username_pw_set(
            g_mqtt,
            g_mqttCfg.username.c_str(),
            g_mqttCfg.password.empty() ? nullptr : g_mqttCfg.password.c_str()
        );
    }

    // Set callbacks
    mosquitto_connect_callback_set(g_mqtt,    mqtt_on_connect);
    mosquitto_disconnect_callback_set(g_mqtt, mqtt_on_disconnect);
    mosquitto_message_callback_set(g_mqtt,    mqtt_on_message);

    // ---------- TLS setup ----------
    if (g_mqttCfg.use_tls) {
        std::cout << "[mqtt] TLS enabled; configuring libmosquitto...\n";

        // Resolve cafile relative to configDir if it's not an absolute path
        std::string cafilePath;
        if (!g_mqttCfg.cafile.empty()) {
            cafilePath = resolve_ca_cert_path(configDir);
        }

        const char *cafile   = cafilePath.empty()           ? nullptr : cafilePath.c_str();
        const char *capath   = g_mqttCfg.capath.empty()     ? nullptr : g_mqttCfg.capath.c_str();
        const char *certfile = g_mqttCfg.certfile.empty()   ? nullptr : g_mqttCfg.certfile.c_str();
        const char *keyfile  = g_mqttCfg.keyfile.empty()    ? nullptr : g_mqttCfg.keyfile.c_str();

        std::cout << "[mqtt]   cafile:      " << (cafile   ? cafile   : "<none>") << "\n";
        std::cout << "[mqtt]   capath:      " << (capath   ? capath   : "<none>") << "\n";
        std::cout << "[mqtt]   certfile:    " << (certfile ? certfile : "<none>") << "\n";
        std::cout << "[mqtt]   keyfile:     " << (keyfile  ? keyfile  : "<none>") << "\n";
        std::cout << "[mqtt]   tls_version: "
                  << (g_mqttCfg.tls_version.empty() ? "<default>" : g_mqttCfg.tls_version)
                  << "\n";
        std::cout << "[mqtt]   tls_insecure:" << (g_mqttCfg.tls_insecure ? "true" : "false") << "\n";

        int rc = mosquitto_tls_set(
            g_mqtt,
            cafile,
            capath,
            certfile,
            keyfile,
            nullptr // pw_callback
        );
        if (rc != MOSQ_ERR_SUCCESS) {
            std::cerr << "[mqtt] mosquitto_tls_set failed: "
                      << mosquitto_strerror(rc) << "\n";
            mosquitto_destroy(g_mqtt);
            g_mqtt = nullptr;
            mosquitto_lib_cleanup();
            return false;
        }

        // Insecure mode (skip hostname / cert checks)
        if (g_mqttCfg.tls_insecure) {
            rc = mosquitto_tls_insecure_set(g_mqtt, true);
            if (rc != MOSQ_ERR_SUCCESS) {
                std::cerr << "[mqtt] tls_insecure_set error: "
                          << mosquitto_strerror(rc) << "\n";
            }
        }

        // Force a specific TLS version if requested
        if (!g_mqttCfg.tls_version.empty()) {
            rc = mosquitto_tls_opts_set(
                g_mqtt,
                1, // SSL_VERIFY_PEER
                g_mqttCfg.tls_version.c_str(), // <-- CORRECT SLOT
                nullptr                        // ciphers (default)
            );
            if (rc != MOSQ_ERR_SUCCESS) {
                std::cerr << "[mqtt] tls_opts_set error: "
                          << mosquitto_strerror(rc) << "\n";
            }
        }
    }

    int rc = mosquitto_connect_async(
        g_mqtt,
        g_mqttCfg.host.c_str(),
        g_mqttCfg.port,
        g_mqttCfg.keepalive
    );
    if (rc != MOSQ_ERR_SUCCESS) {
        std::cerr << "[mqtt] connect_async failed: "
                  << mosquitto_strerror(rc) << "\n";
        mosquitto_destroy(g_mqtt);
        g_mqtt = nullptr;
        mosquitto_lib_cleanup();
        return false;
    }

    rc = mosquitto_loop_start(g_mqtt);
    if (rc != MOSQ_ERR_SUCCESS) {
        std::cerr << "[mqtt] loop_start failed: "
                  << mosquitto_strerror(rc) << "\n";
        mosquitto_destroy(g_mqtt);
        g_mqtt = nullptr;
        mosquitto_lib_cleanup();
        return false;
    }
    g_mqttLoopStarted = true;

    std::cout << "[mqtt] Started: " << g_mqttCfg.host << ":" << g_mqttCfg.port
              << " base_topic='" << g_mqttCfg.base_topic << "'";
    if (g_mqttCfg.subscribe_enabled) {
        std::cout << " (subscribe enabled on '"
                  << g_mqttCfg.command_topic << "/#')";
    }
    std::cout << "\n";

    return true;
}

void mqtt_shutdown() {
    std::lock_guard<std::mutex> lock(g_mqttMutex);

    if (g_mqtt) {
        if (g_mqttLoopStarted) {
            mosquitto_loop_stop(g_mqtt, true);
            g_mqttLoopStarted = false;
        }
        mosquitto_disconnect(g_mqtt);
        mosquitto_destroy(g_mqtt);
        g_mqtt = nullptr;
        mosquitto_lib_cleanup();
    }
    g_mqttTagState.clear();
    g_mqttConnState.clear();
}

double snapshot_value_as_double(const TagSnapshot &snap, bool &ok) {
    ok = true;
    double v = 0.0;

    std::visit([&](auto &&arg) {
        using T = std::decay_t<decltype(arg)>;
        if constexpr (std::is_same_v<T, bool>) {
            v = arg ? 1.0 : 0.0;
        } else if constexpr (std::is_same_v<T, int16_t> ||
                             std::is_same_v<T, int32_t> ||
                             std::is_same_v<T, uint16_t> ||
                             std::is_same_v<T, uint32_t> ||
                             std::is_same_v<T, float> ||
                             std::is_same_v<T, double>) {
            v = static_cast<double>(arg);
        } else {
            ok = false;
        }
    }, snap.value);

    return v;
}

std::string snapshot_value_as_text(const TagSnapshot &snap) {
    return tag_value_to_string(snap.value);
}

void publish_alarm_event(const AlarmRuntime &alarm,
                         const TagSnapshot &snap,
                         const std::string &state)
{
    const std::string displayName = alarm.cfg.name.empty() ? alarm.cfg.id : alarm.cfg.name;
    std::string message;
    if (state == "active") {
        message = alarm.cfg.message_on_active.empty() ? displayName : alarm.cfg.message_on_active;
    } else if (state == "cleared") {
        message = alarm.cfg.message_on_return;
    } else {
        message = displayName;
    }

    // 1) MQTT alarm publish (unchanged)
    if (g_mqtt && g_mqttCfg.enabled) {
        const std::string base = g_mqttCfg.base_topic.empty()
                               ? std::string("opcbridge")
                               : g_mqttCfg.base_topic;

        std::string topic = base + "/alarm/" + mqtt_sanitize(alarm.cfg.id);

        auto now_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
            snap.timestamp.time_since_epoch()
        ).count();

        json j;
        j["alarm_id"]       = alarm.cfg.id;
        j["name"]           = displayName;
        j["connection_id"]  = alarm.cfg.connection_id;
        j["tag_name"]       = alarm.cfg.tag_name;
        j["type"]           = alarm.cfg.type;
        j["state"]          = state;  // "active", "cleared", "change"
        j["severity"]       = alarm.cfg.severity;
        j["message"]        = message.empty() ? nullptr : json(message);
        j["timestamp_ms"]   = now_ms;

        bool okNum = false;
        double v = snapshot_value_as_double(snap, okNum);
        if (okNum) {
            j["value"]      = v;
            j["threshold"]  = alarm.cfg.threshold;
            j["hysteresis"] = alarm.cfg.hysteresis;
        } else {
            std::visit([&](auto &&arg) {
                j["value"] = arg;
            }, snap.value);
        }

        if (alarm.cfg.type == "equals" || alarm.cfg.type == "not_equals" || alarm.cfg.type == "contains" || alarm.cfg.type == "not_contains") {
            j["equals_value"] = alarm.cfg.equals_value;
            j["tolerance"] = alarm.cfg.equals_tolerance;
        }

        mqtt_publish_raw(topic, j.dump());

		if (ws_is_enabled()) {
			ws_notify_alarm_event(alarm, snap, state);
		}

        // 2) SQLite event log for alarm state change
        //    We’ll store the process value as new_value and the full alarm
        //    payload as extra_json for later troubleshooting.
        std::string newVal = snapshot_value_to_string(snap);
        std::string oldVal;        // unknown / not tracked → leave empty
        int oldQ = -1;             // will be stored as NULL
        int newQ = snap.quality;   // typically 1 = good

        sqlite_log_event(
            alarm.cfg.connection_id,   // connection_id
            alarm.cfg.tag_name,        // tag_name
            oldVal,                    // old_value
            newVal,                    // new_value
            oldQ,                      // old_quality (NULL)
            newQ,                      // new_quality
            now_ms,                    // timestamp_ms
            j.dump()                   // extra_json (full alarm details)
        );

        // Optional: console line so you can see alarm transitions in the log
        std::cout << "[alarm] " << alarm.cfg.id << " state=" << state
                  << " [" << alarm.cfg.connection_id << "]."
                  << alarm.cfg.tag_name << " value=" << newVal << "\n";
    } else {
        // Even if MQTT is disabled, we still want to log the alarm to SQLite
        auto now_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
            snap.timestamp.time_since_epoch()
        ).count();

        std::string newVal = snapshot_value_to_string(snap);
        std::string oldVal;
        int oldQ = -1;
        int newQ = snap.quality;

        json j;
        j["alarm_id"]      = alarm.cfg.id;
        j["name"]          = displayName;
        j["connection_id"] = alarm.cfg.connection_id;
        j["tag_name"]      = alarm.cfg.tag_name;
        j["type"]          = alarm.cfg.type;
        j["state"]         = state;
        j["severity"]      = alarm.cfg.severity;
        j["message"]       = message.empty() ? nullptr : json(message);
        j["timestamp_ms"]  = now_ms;

        if (alarm.cfg.type == "equals" || alarm.cfg.type == "not_equals" || alarm.cfg.type == "contains" || alarm.cfg.type == "not_contains") {
            j["equals_value"] = alarm.cfg.equals_value;
            j["tolerance"] = alarm.cfg.equals_tolerance;
        }

        sqlite_log_event(
            alarm.cfg.connection_id,
            alarm.cfg.tag_name,
            oldVal,
            newVal,
            oldQ,
            newQ,
            now_ms,
            j.dump()
        );

        std::cout << "[alarm] " << alarm.cfg.id << " state=" << state
                  << " [" << alarm.cfg.connection_id << "]."
                  << alarm.cfg.tag_name << " value=" << newVal
                  << " (MQTT disabled)\n";
    }
}

void evaluate_tag_alarms(const std::string &conn_id,
                         const std::string &logical_name,
                         const TagSnapshot &snap)
{
    // bad quality? You can choose to ignore or raise a "comm" alarm later.
    if (snap.quality != 1) {
        return;
    }

    std::string key = make_tag_key(conn_id, logical_name);
    auto it = g_alarmIndexByTag.find(key);
    if (it == g_alarmIndexByTag.end()) return;

    bool okNum = false;
    double val = snapshot_value_as_double(snap, okNum);

    for (size_t idx : it->second) {
        AlarmRuntime &a = g_alarms[idx];
        if (!a.cfg.enabled) continue;

        const std::string &type = a.cfg.type;

        if (type == "change") {
            // fire on any change
            bool changed = false;
            if (!a.hasLastValue) {
                changed = true;
            } else {
                changed = (snap.value != a.lastValue);
            }

            if (changed) {
                publish_alarm_event(a, snap, "change");
            }
            a.lastValue = snap.value;
            a.hasLastValue = true;
        }
        else if (type == "equals" || type == "not_equals") {
            bool matchKnown = false;
            bool match = false;

            // Bool targets
            if (a.cfg.equals_value.is_boolean()) {
                const bool target = a.cfg.equals_value.get<bool>();
                bool curOk = false;
                bool cur = false;
                std::visit([&](auto&& arg) {
                    using T = std::decay_t<decltype(arg)>;
                    if constexpr (std::is_same_v<T, bool>) { cur = arg; curOk = true; }
                }, snap.value);
                if (curOk) { matchKnown = true; match = (cur == target); }
            }
            else if (std::holds_alternative<std::string>(snap.value)) {
                const std::string cur = std::get<std::string>(snap.value);
                const std::string target = a.cfg.equals_value.is_string() ? a.cfg.equals_value.get<std::string>() : a.cfg.equals_value.dump();
                matchKnown = true;
                match = (cur == target);
            }
            // Numeric targets (support analog + integer tags)
            else if (a.cfg.equals_value.is_number() || a.cfg.equals_value.is_string()) {
                bool targetOk = false;
                double target = 0.0;
                try {
                    if (a.cfg.equals_value.is_number()) { target = a.cfg.equals_value.get<double>(); targetOk = true; }
                    else if (a.cfg.equals_value.is_string()) {
                        target = std::stod(a.cfg.equals_value.get<std::string>());
                        targetOk = true;
                    }
                } catch (...) { targetOk = false; }

                if (targetOk && okNum) {
                    matchKnown = true;
                    const double tol = std::max(0.0, a.cfg.equals_tolerance);
                    match = std::fabs(val - target) <= tol;
                }
            }

            const bool shouldBeActive = matchKnown && (type == "equals" ? match : !match);

            if (shouldBeActive && !a.active) {
                a.active = true;
                publish_alarm_event(a, snap, "active");
            } else if (!shouldBeActive && a.active) {
                a.active = false;
                publish_alarm_event(a, snap, "cleared");
            }

            a.lastValue = snap.value;
            a.hasLastValue = true;
        }
        else if (type == "contains" || type == "not_contains") {
            const std::string cur = snapshot_value_as_text(snap);
            const std::string target = a.cfg.equals_value.is_string() ? a.cfg.equals_value.get<std::string>() : a.cfg.equals_value.dump();
            const bool match = cur.find(target) != std::string::npos;
            const bool shouldBeActive = (type == "contains") ? match : !match;

            if (shouldBeActive && !a.active) {
                a.active = true;
                publish_alarm_event(a, snap, "active");
            } else if (!shouldBeActive && a.active) {
                a.active = false;
                publish_alarm_event(a, snap, "cleared");
            }

            a.lastValue = snap.value;
            a.hasLastValue = true;
        }
        else if (type == "empty" || type == "not_empty") {
            const std::string cur = snapshot_value_as_text(snap);
            const bool match = cur.empty();
            const bool shouldBeActive = (type == "empty") ? match : !match;

            if (shouldBeActive && !a.active) {
                a.active = true;
                publish_alarm_event(a, snap, "active");
            } else if (!shouldBeActive && a.active) {
                a.active = false;
                publish_alarm_event(a, snap, "cleared");
            }

            a.lastValue = snap.value;
            a.hasLastValue = true;
        }
        else if ((type == "high" || type == "low") && okNum) {
            const double thr  = a.cfg.threshold;
            const double hyst = a.cfg.hysteresis;

            if (type == "high") {
                if (!a.active && val >= thr) {
                    a.active = true;
                    publish_alarm_event(a, snap, "active");
                } else if (a.active && val <= (thr - hyst)) {
                    a.active = false;
                    publish_alarm_event(a, snap, "cleared");
                }
            } else if (type == "low") {
                if (!a.active && val <= thr) {
                    a.active = true;
                    publish_alarm_event(a, snap, "active");
                } else if (a.active && val >= (thr + hyst)) {
                    a.active = false;
                    publish_alarm_event(a, snap, "cleared");
                }
            }

            // Track last value for UI/debugging (so /alarms shows the current PV).
            a.lastValue = snap.value;
            a.hasLastValue = true;
        }
        // Other types (rising_edge, falling_edge) could be added later.
    }
}

